


SET statement_timeout = '180s';
SET lock_timeout = '5s';
SET idle_in_transaction_session_timeout = '240s';
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "community_private";




CREATE SCHEMA IF NOT EXISTS "private";




CREATE SCHEMA IF NOT EXISTS "public";




COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE OR REPLACE FUNCTION "community_private"."can_access_room"("p_room_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select (select auth.uid()) is not null
    and exists (
      select 1
      from public.community_rooms r
      where r.id = p_room_id
        and r.is_archived = false
        and exists (
          select 1
          from public.community_memberships m
          where m.community_id = r.community_id
            and m.user_id = (select auth.uid())
            and m.status = 'active'
        )
        and (
          exists (
            select 1
            from public.community_communities c
            where c.id = r.community_id
              and c.owner_user_id = (select auth.uid())
          )
          or exists (
            select 1
            from public.community_memberships staff_membership
            where staff_membership.community_id = r.community_id
              and staff_membership.user_id = (select auth.uid())
              and staff_membership.status = 'active'
              and staff_membership.role in ('owner', 'moderator')
          )
          or r.access_type = 'free'
          or (
            r.access_type = 'entitlement'
            and exists (
              select 1
              from public.community_room_entitlement_rules rule
              join public.community_member_entitlements entitlement
                on entitlement.community_id = rule.community_id
               and entitlement.entitlement_key = rule.entitlement_key
              where rule.room_id = r.id
                and entitlement.user_id = (select auth.uid())
                and entitlement.status = 'active'
                and entitlement.starts_at <= now()
                and (entitlement.ends_at is null or entitlement.ends_at > now())
            )
          )
        )
    );
$$;




CREATE OR REPLACE FUNCTION "community_private"."enforce_community_staff_roles"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'community_private'
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_owner uuid;
begin
  select owner_user_id into v_owner
  from public.community_communities
  where id = new.community_id;

  -- Preserve service-role maintenance and migration operations.
  if v_actor is null then
    return new;
  end if;

  -- Ownership transfer requires a separate audited workflow. Until then the
  -- canonical owner's membership must stay active and keep the owner role.
  if old.user_id = v_owner then
    if new.role <> 'owner' or new.status <> 'active' then
      raise exception 'The Community owner cannot be demoted or suspended.';
    end if;
    return new;
  end if;

  -- No other membership may become an owner. Co-operators use moderator.
  if new.role = 'owner' then
    raise exception 'Use the moderator role for additional operators.';
  end if;

  -- Only the canonical owner may grant or revoke moderator privileges.
  if new.role is distinct from old.role and v_actor <> v_owner then
    raise exception 'Only the Community owner can change staff roles.';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "community_private"."guard_chat_message_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'community_private'
    AS $$
begin
  if new.id is distinct from old.id
    or new.community_id is distinct from old.community_id
    or new.room_id is distinct from old.room_id
    or new.author_user_id is distinct from old.author_user_id
    or new.reply_to_message_id is distinct from old.reply_to_message_id
    or new.stamp_id is distinct from old.stamp_id
    or new.created_at is distinct from old.created_at then
    raise exception 'Chat message identity cannot be changed';
  end if;

  if new.is_hidden is distinct from old.is_hidden
    and not community_private.is_staff(old.community_id) then
    raise exception 'Only Community staff can moderate chat messages';
  end if;

  if (select auth.uid()) is distinct from old.author_user_id
    and (
      new.body is distinct from old.body
      or new.edited_at is distinct from old.edited_at
      or new.deleted_at is distinct from old.deleted_at
      or new.deleted_by_user_id is distinct from old.deleted_by_user_id
    ) then
    raise exception 'Community staff can moderate but cannot rewrite a member message';
  end if;

  if new.deleted_at is distinct from old.deleted_at then
    if old.deleted_at is not null
      or new.deleted_at is null
      or new.deleted_by_user_id is distinct from (select auth.uid()) then
      raise exception 'Chat message deletion is invalid';
    end if;
  elsif new.deleted_by_user_id is distinct from old.deleted_by_user_id then
    raise exception 'Chat message deletion audit cannot be changed separately';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "community_private"."initialize_community_safety"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  insert into public.community_safety_settings (community_id) values (new.id)
  on conflict (community_id) do nothing;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "community_private"."is_active_member"("p_community_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select (select auth.uid()) is not null
    and exists (
      select 1
      from public.community_memberships m
      where m.community_id = p_community_id
        and m.user_id = (select auth.uid())
        and m.status = 'active'
    );
$$;




CREATE OR REPLACE FUNCTION "community_private"."is_staff"("p_community_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select (select auth.uid()) is not null
    and (
      exists (
        select 1
        from public.community_communities c
        where c.id = p_community_id
          and c.owner_user_id = (select auth.uid())
      )
      or exists (
        select 1
        from public.community_memberships m
        where m.community_id = p_community_id
          and m.user_id = (select auth.uid())
          and m.status = 'active'
          and m.role in ('owner', 'moderator')
      )
    );
$$;




CREATE OR REPLACE FUNCTION "community_private"."validate_community_content"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'community_private'
    AS $$
declare
  v_community_id uuid;
  v_author_id uuid;
  v_content text;
  v_membership public.community_memberships;
  v_settings public.community_safety_settings;
  v_action_count integer;
begin
  if tg_table_name = 'community_comments' then
    select p.community_id into v_community_id from public.community_posts p where p.id = new.post_id;
    v_author_id := new.author_user_id; v_content := new.body;
  else
    v_community_id := new.community_id; v_author_id := new.author_user_id;
    v_content := concat_ws(' ', case when tg_table_name = 'community_posts' then new.title else null end, new.body);
  end if;
  if v_author_id is null or v_author_id <> (select auth.uid()) then return new; end if;
  select * into v_membership from public.community_memberships m
  where m.community_id = v_community_id and m.user_id = v_author_id and m.status = 'active';
  if v_membership.role in ('owner', 'moderator') then return new; end if;
  if exists (
    select 1 from public.community_blocked_words w
    where w.community_id = v_community_id and w.is_active and w.action = 'block'
      and position(lower(w.term) in lower(v_content)) > 0
  ) then raise exception 'This content contains a prohibited word'; end if;
  select * into v_settings from public.community_safety_settings where community_id = v_community_id;
  if tg_op = 'INSERT' and v_settings.new_member_limit_enabled
     and v_membership.joined_at >= now() - make_interval(hours => v_settings.new_member_limit_hours) then
    select
      (select count(*) from public.community_posts p where p.community_id = v_community_id and p.author_user_id = v_author_id and p.created_at >= now() - make_interval(hours => v_settings.new_member_limit_hours))
      + (select count(*) from public.community_comments c join public.community_posts p on p.id = c.post_id where p.community_id = v_community_id and c.author_user_id = v_author_id and c.created_at >= now() - make_interval(hours => v_settings.new_member_limit_hours))
      + (select count(*) from public.community_chat_messages m where m.community_id = v_community_id and m.author_user_id = v_author_id and m.created_at >= now() - make_interval(hours => v_settings.new_member_limit_hours))
    into v_action_count;
    if v_action_count >= v_settings.new_member_max_actions then raise exception 'New member posting limit reached'; end if;
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_active_program_license_exists"("p_program_id" "uuid", "p_licensee_headquarters_id" "uuid", "p_program_version_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.academy_program_licenses license
    where license.program_id = p_program_id
      and license.licensee_headquarters_id = p_licensee_headquarters_id
      and license.status = 'active'
      and license.starts_at <= now()
      and (license.ends_at is null or license.ends_at > now())
      and (
        p_program_version_id is null
        or license.program_version_id is null
        or license.program_version_id = p_program_version_id
      )
  );
$$;




CREATE OR REPLACE FUNCTION "private"."academy_assign_licensed_program"("p_license_id" "uuid", "p_member_profile_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_license public.academy_program_licenses%rowtype;
  v_assignment_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select *
  into v_license
  from public.academy_program_licenses
  where id = p_license_id
    and public.academy_owns_hq(licensee_headquarters_id)
    and status = 'active'
    and starts_at <= now()
    and (ends_at is null or ends_at > now());

  if v_license.id is null then
    raise exception 'Active license not found or permission denied';
  end if;

  if not exists (
    select 1
    from public.academy_memberships membership
    where membership.headquarters_id = v_license.licensee_headquarters_id
      and membership.member_profile_id = p_member_profile_id
      and membership.status = 'active'
  ) then
    raise exception 'Active Academy member required';
  end if;

  insert into public.academy_program_assignments(
    headquarters_id,
    program_id,
    program_version_id,
    learner_profile_id,
    status
  )
  values (
    v_license.licensee_headquarters_id,
    v_license.program_id,
    v_license.program_version_id,
    p_member_profile_id,
    'active'
  )
  on conflict (program_id, learner_profile_id)
  do update set
    headquarters_id = excluded.headquarters_id,
    program_version_id = excluded.program_version_id,
    status = 'active',
    updated_at = now()
  returning id into v_assignment_id;

  return v_assignment_id;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_assignment_step_type"("p_assignment_id" "uuid", "p_step_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_program_id uuid;
  v_program_version_id uuid;
  v_snapshot jsonb;
  v_step_type text;
begin
  select assignment.program_id, assignment.program_version_id
  into v_program_id, v_program_version_id
  from public.academy_program_assignments assignment
  where assignment.id = p_assignment_id;

  if v_program_id is null then
    return null;
  end if;

  if v_program_version_id is null then
    select step.step_type
    into v_step_type
    from public.academy_program_steps step
    join public.academy_program_sections section
      on section.id = step.section_id
    where step.id = p_step_id
      and section.program_id = v_program_id;
  else
    select version.content_snapshot
    into v_snapshot
    from public.academy_program_versions version
    where version.id = v_program_version_id
      and version.program_id = v_program_id;

    select step.value ->> 'step_type'
    into v_step_type
    from jsonb_array_elements(v_snapshot -> 'sections') section(value)
    cross join lateral jsonb_array_elements(section.value -> 'steps') step(value)
    where (step.value ->> 'id')::uuid = p_step_id;
  end if;

  return v_step_type;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_calculate_credential_expires_at"("p_renewal_months" integer, "p_base" timestamp with time zone DEFAULT "now"()) RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when p_renewal_months is null then null
    else p_base + make_interval(months => p_renewal_months)
  end;
$$;




