CREATE OR REPLACE FUNCTION "private"."academy_can_read_assignment_learning_artifact"("p_assignment_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select (select auth.uid()) is not null
    and exists (
      select 1
      from public.academy_program_assignments assignment
      join public.profiles learner
        on learner.id = assignment.learner_profile_id
      where assignment.id = p_assignment_id
        and (
          public.academy_owns_hq(assignment.headquarters_id)
          or (
            learner.user_id = (select auth.uid())
            and private.academy_profile_has_program_access(
              assignment.learner_profile_id,
              assignment.program_id
            )
          )
          or public.academy_can_approve_program_progress(assignment.headquarters_id)
        )
    );
$$;




CREATE OR REPLACE FUNCTION "private"."academy_can_read_class"("p_class_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select (select auth.uid()) is not null
    and exists (
      select 1
      from public.academy_classes class_record
      where class_record.id = p_class_id
        and (
          public.academy_owns_hq(class_record.headquarters_id)
          or exists (
            select 1
            from public.academy_instructors instructor
            where instructor.id = class_record.instructor_id
              and instructor.user_id = (select auth.uid())
              and instructor.is_active = true
          )
          or exists (
            select 1
            from public.academy_enrollments enrollment
            join public.profiles learner
              on learner.id = enrollment.learner_profile_id
            where enrollment.class_id = class_record.id
              and enrollment.status <> 'cancelled'
              and learner.user_id = (select auth.uid())
          )
        )
    );
$$;




CREATE OR REPLACE FUNCTION "private"."academy_can_read_enrollment"("p_enrollment_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select (select auth.uid()) is not null
    and exists (
      select 1
      from public.academy_enrollments enrollment
      join public.academy_classes class_record
        on class_record.id = enrollment.class_id
      join public.profiles learner
        on learner.id = enrollment.learner_profile_id
      left join public.academy_instructors instructor
        on instructor.id = class_record.instructor_id
      where enrollment.id = p_enrollment_id
        and (
          public.academy_owns_hq(class_record.headquarters_id)
          or learner.user_id = (select auth.uid())
          or (
            instructor.user_id = (select auth.uid())
            and instructor.is_active = true
          )
        )
    );
$$;




CREATE OR REPLACE FUNCTION "private"."academy_can_read_program_version"("p_program_version_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select (select auth.uid()) is not null
    and exists (
      select 1
      from public.academy_program_versions version
      join public.academy_programs program
        on program.id = version.program_id
      where version.id = p_program_version_id
        and (
          public.academy_owns_hq(program.headquarters_id)
          or exists (
            select 1
            from public.academy_program_assignments assignment
            where assignment.program_version_id = version.id
              and assignment.program_id = version.program_id
              and assignment.status = 'active'
              and private.academy_profile_has_program_access(
                assignment.learner_profile_id,
                assignment.program_id
              )
          )
          or exists (
            select 1
            from public.academy_program_licenses license
            where license.program_id = version.program_id
              and license.status = 'active'
              and license.starts_at <= now()
              and (license.ends_at is null or license.ends_at > now())
              and (license.program_version_id is null or license.program_version_id = version.id)
              and (
                public.academy_owns_hq(license.licensor_headquarters_id)
                or public.academy_owns_hq(license.licensee_headquarters_id)
              )
          )
        )
    );
$$;




