CREATE OR REPLACE FUNCTION "private"."academy_class_scope_valid"("p_headquarters_id" "uuid", "p_course_id" "uuid", "p_program_id" "uuid", "p_instructor_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    exists (
      select 1
      from public.academy_courses course
      where course.id = p_course_id
        and course.headquarters_id = p_headquarters_id
    )
    and exists (
      select 1
      from public.academy_programs program
      where program.id = p_program_id
        and program.headquarters_id = p_headquarters_id
    )
    and (
      p_instructor_id is null
      or exists (
        select 1
        from public.academy_instructors instructor
        where instructor.id = p_instructor_id
          and instructor.headquarters_id = p_headquarters_id
      )
    );
$$;




CREATE OR REPLACE FUNCTION "private"."academy_create_program_license"("p_licensee_headquarters_id" "uuid", "p_program_id" "uuid", "p_program_version_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_program public.academy_programs%rowtype;
  v_program_version_id uuid;
  v_license_id uuid;
  v_now timestamptz := now();
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select *
  into v_program
  from public.academy_programs
  where id = p_program_id
  for update;

  if v_program.id is null
    or not public.academy_owns_hq(v_program.headquarters_id)
  then
    raise exception 'Program not found or permission denied';
  end if;

  if v_program.status <> 'published' then
    raise exception 'Publish the program before licensing it';
  end if;

  if p_licensee_headquarters_id = v_program.headquarters_id then
    raise exception 'Cannot license a program to the same headquarters';
  end if;

  if not exists (
    select 1
    from public.academy_headquarters hq
    where hq.id = p_licensee_headquarters_id
      and hq.is_active
  ) then
    raise exception 'Target headquarters not found';
  end if;

  if p_program_version_id is not null then
    select version.id
    into v_program_version_id
    from public.academy_program_versions version
    where version.id = p_program_version_id
      and version.program_id = p_program_id;

    if v_program_version_id is null then
      raise exception 'Program version not found';
    end if;
  else
    select version.id
    into v_program_version_id
    from public.academy_program_versions version
    where version.program_id = p_program_id
    order by version.version_number desc
    limit 1;
  end if;

  insert into public.academy_program_licenses(
    licensor_headquarters_id,
    licensee_headquarters_id,
    program_id,
    program_version_id,
    status,
    starts_at,
    ends_at,
    note,
    created_by_user_id,
    updated_at
  )
  values (
    v_program.headquarters_id,
    p_licensee_headquarters_id,
    p_program_id,
    v_program_version_id,
    'active',
    v_now,
    null,
    nullif(trim(coalesce(p_note, '')), ''),
    (select auth.uid()),
    v_now
  )
  on conflict (licensee_headquarters_id, program_id)
  do update set
    licensor_headquarters_id = excluded.licensor_headquarters_id,
    program_version_id = excluded.program_version_id,
    status = 'active',
    starts_at = v_now,
    ends_at = null,
    note = excluded.note,
    updated_at = v_now
  returning id into v_license_id;

  return v_license_id;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_grade_step_test"("p_attempt_id" "uuid", "p_passed" boolean, "p_score" numeric DEFAULT NULL::numeric, "p_max_score" numeric DEFAULT NULL::numeric, "p_review_note" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_attempt public.academy_step_test_attempts%rowtype;
  v_headquarters_id uuid;
  v_result text;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select attempt.*
  into v_attempt
  from public.academy_step_test_attempts attempt
  where attempt.id = p_attempt_id
    and attempt.status = 'submitted';

  if v_attempt.id is null then
    raise exception 'Pending test attempt not found';
  end if;

  select assignment.headquarters_id
  into v_headquarters_id
  from public.academy_program_assignments assignment
  where assignment.id = v_attempt.assignment_id;

  if not public.academy_can_approve_program_progress(v_headquarters_id) then
    raise exception 'Grading permission required';
  end if;

  if p_score is not null and p_score < 0 then
    raise exception 'Score must be zero or greater';
  end if;

  if p_max_score is not null and p_max_score <= 0 then
    raise exception 'Max score must be greater than zero';
  end if;

  v_result := case when p_passed then 'passed' else 'failed' end;

  update public.academy_step_test_attempts
  set
    status = v_result,
    score = p_score,
    max_score = p_max_score,
    reviewed_at = now(),
    reviewed_by_user_id = (select auth.uid()),
    review_note = nullif(trim(coalesce(p_review_note, '')), ''),
    updated_at = now()
  where id = p_attempt_id;

  update public.academy_step_progress
  set
    status = case when p_passed then 'completed' else 'not_started' end,
    completed_at = case when p_passed then now() else null end,
    approved_by_user_id = (select auth.uid()),
    review_note = nullif(trim(coalesce(p_review_note, '')), ''),
    reviewed_at = now(),
    updated_at = now()
  where assignment_id = v_attempt.assignment_id
    and step_id = v_attempt.step_id;

  return v_result;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_guard_course_collaboration"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_role text := private.academy_headquarters_role(old.headquarters_id, (select auth.uid()));
begin
  if new.headquarters_id is distinct from old.headquarters_id
    or new.user_id is distinct from old.user_id then
    raise exception 'academy_course_identity_is_immutable';
  end if;
  if new.is_published is distinct from old.is_published and v_role <> 'owner' then
    raise exception 'academy_course_publish_owner_required';
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_guard_headquarters_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.owner_user_id is distinct from old.owner_user_id
    or new.owner_profile_id is distinct from old.owner_profile_id then
    raise exception 'academy_headquarters_ownership_is_immutable';
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_guard_instructor_page_collaboration"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.headquarters_id is distinct from old.headquarters_id
    or new.course_id is distinct from old.course_id
    or new.user_id is distinct from old.user_id then
    raise exception 'academy_instructor_page_identity_is_immutable';
