  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_guard_program_child_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_name = 'academy_program_sections'
    and new.program_id is distinct from old.program_id then
    raise exception 'academy_program_section_scope_is_immutable';
  end if;
  if tg_table_name = 'academy_program_steps'
    and new.section_id is distinct from old.section_id then
    raise exception 'academy_program_step_scope_is_immutable';
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_guard_program_course_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and (
    new.headquarters_id is distinct from old.headquarters_id
    or new.course_id is distinct from old.course_id
  ) then
    raise exception 'academy_program_scope_is_immutable';
  end if;

  if tg_op = 'UPDATE'
    and new.status is distinct from old.status
    and private.academy_headquarters_role(old.headquarters_id, (select auth.uid())) <> 'owner' then
    raise exception 'academy_program_publish_owner_required';
  end if;

  if new.course_id is not null and not exists (
    select 1
    from public.academy_courses course
    where course.id = new.course_id
      and course.headquarters_id = new.headquarters_id
  ) then
    raise exception 'academy_program_course_scope_invalid';
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_guard_submission_progress"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_program_id uuid;
  v_program_version_id uuid;
  v_snapshot jsonb;
  v_step_type text;
begin
  if new.status <> 'awaiting_approval' then
    return new;
  end if;

  select assignment.program_id, assignment.program_version_id
  into v_program_id, v_program_version_id
  from public.academy_program_assignments assignment
  where assignment.id = new.assignment_id;

  if v_program_version_id is null then
    select step.step_type
    into v_step_type
    from public.academy_program_steps step
    join public.academy_program_sections section
      on section.id = step.section_id
    where step.id = new.step_id
      and section.program_id = v_program_id;
  else
    select version.content_snapshot
    into v_snapshot
    from public.academy_program_versions version
    where version.id = v_program_version_id;

    select step.value ->> 'step_type'
    into v_step_type
    from jsonb_array_elements(v_snapshot -> 'sections') section(value)
    cross join lateral jsonb_array_elements(section.value -> 'steps') step(value)
    where (step.value ->> 'id')::uuid = new.step_id;
  end if;

  if v_step_type = 'submission'
    and not exists (
      select 1
      from public.academy_step_submissions submission
      where submission.assignment_id = new.assignment_id
        and submission.step_id = new.step_id
        and submission.status = 'submitted'
    )
  then
    raise exception 'Submit the assignment content before requesting review';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_has_my_subscription_product"("p_product_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.academy_subscriptions subscription
    join public.profiles profile
      on profile.id = subscription.member_profile_id
    where subscription.subscription_product_id = p_product_id
      and profile.user_id = (select auth.uid())
  );
$$;




CREATE OR REPLACE FUNCTION "private"."academy_headquarters_role"("p_headquarters_id" "uuid", "p_user_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when exists (
      select 1
      from public.academy_headquarters h
      where h.id = p_headquarters_id
        and h.owner_user_id = p_user_id
    ) then 'owner'
    else (
      select m.role
      from public.academy_headquarters_members m
      join public.profiles p on p.id = m.member_profile_id
      where m.headquarters_id = p_headquarters_id
        and p.user_id = p_user_id
        and m.status = 'active'
      limit 1
    )
  end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_list_license_target_headquarters"() RETURNS TABLE("id" "uuid", "name" "text", "handle" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select hq.id, hq.name, hq.handle
  from public.academy_headquarters hq
  where (select auth.uid()) is not null
    and hq.is_active
    and not public.academy_owns_hq(hq.id)
  order by hq.name, hq.handle;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_list_live_session_steps"() RETURNS TABLE("assignment_id" "uuid", "step_id" "uuid", "live_session_id" "uuid", "learner_name" "text", "learner_handle" "text", "program_title" "text", "step_title" "text", "scheduled_at" timestamp with time zone, "meeting_url" "text", "meeting_id" "text", "passcode" "text", "status" "text", "attendance_status" "text", "note" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    assignment.id,
    step.id,
    session.id,
    learner.display_name,
    learner.handle,
    coalesce(version.title, program.title),
    coalesce(
      (
        select snapshot_step.value ->> 'title'
        from jsonb_array_elements(version.content_snapshot -> 'sections') snapshot_section(value)
        cross join lateral jsonb_array_elements(snapshot_section.value -> 'steps') snapshot_step(value)
        where (snapshot_step.value ->> 'id')::uuid = step.id
      ),
      step.title
    ),
    session.scheduled_at,
    session.meeting_url,
    session.meeting_id,
    session.passcode,
    session.status,
    session.attendance_status,
    session.note
  from public.academy_program_assignments assignment
  join public.profiles learner
    on learner.id = assignment.learner_profile_id
  join public.academy_programs program
    on program.id = assignment.program_id
  join public.academy_program_sections section
    on section.program_id = assignment.program_id
  join public.academy_program_steps step
    on step.section_id = section.id
   and step.step_type = 'live_session'
  left join public.academy_program_versions version
    on version.id = assignment.program_version_id
  left join public.academy_live_sessions session
    on session.assignment_id = assignment.id
   and session.step_id = step.id
  where assignment.status = 'active'
    and public.academy_can_approve_program_progress(assignment.headquarters_id)
  order by session.scheduled_at nulls first, learner.display_name, step.sort_order;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_list_pending_step_submissions"() RETURNS TABLE("submission_id" "uuid", "assignment_id" "uuid", "learner_name" "text", "learner_handle" "text", "program_title" "text", "step_title" "text", "attempt_number" integer, "body" "text", "attachment_url" "text", "submitted_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    submission.id,
    submission.assignment_id,
    learner.display_name,
    learner.handle,
    coalesce(version.title, program.title),
    coalesce(
      (
        select snapshot_step.value ->> 'title'
        from jsonb_array_elements(version.content_snapshot -> 'sections') snapshot_section(value)
        cross join lateral jsonb_array_elements(snapshot_section.value -> 'steps') snapshot_step(value)
        where (snapshot_step.value ->> 'id')::uuid = submission.step_id
      ),
      current_step.title
    ),
    submission.attempt_number,
    submission.body,
    submission.attachment_url,
    submission.submitted_at
  from public.academy_step_submissions submission
  join public.academy_program_assignments assignment
    on assignment.id = submission.assignment_id
  join public.profiles learner
    on learner.id = assignment.learner_profile_id
  join public.academy_programs program
    on program.id = assignment.program_id
  join public.academy_program_steps current_step
    on current_step.id = submission.step_id
  left join public.academy_program_versions version
    on version.id = assignment.program_version_id
  where submission.status = 'submitted'
    and public.academy_can_approve_program_progress(assignment.headquarters_id)
  order by submission.submitted_at;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_list_pending_step_tests"() RETURNS TABLE("attempt_id" "uuid", "assignment_id" "uuid", "learner_name" "text", "learner_handle" "text", "program_title" "text", "step_title" "text", "attempt_number" integer, "answers" "jsonb", "submitted_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    attempt.id,
    attempt.assignment_id,
    learner.display_name,
    learner.handle,
    coalesce(version.title, program.title),
    coalesce(
      (
        select snapshot_step.value ->> 'title'
        from jsonb_array_elements(version.content_snapshot -> 'sections') snapshot_section(value)
        cross join lateral jsonb_array_elements(snapshot_section.value -> 'steps') snapshot_step(value)
        where (snapshot_step.value ->> 'id')::uuid = attempt.step_id
      ),
      current_step.title
    ),
    attempt.attempt_number,
    attempt.answers,
    attempt.submitted_at
  from public.academy_step_test_attempts attempt
  join public.academy_program_assignments assignment
