  join public.profiles learner
    on learner.id = assignment.learner_profile_id
  join public.academy_programs program
    on program.id = assignment.program_id
  join public.academy_program_steps current_step
    on current_step.id = attempt.step_id
  left join public.academy_program_versions version
    on version.id = assignment.program_version_id
  where attempt.status = 'submitted'
    and public.academy_can_approve_program_progress(assignment.headquarters_id)
  order by attempt.submitted_at;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_mark_live_session_attendance"("p_live_session_id" "uuid", "p_attended" boolean, "p_note" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_session public.academy_live_sessions%rowtype;
  v_headquarters_id uuid;
  v_status text;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select session.*
  into v_session
  from public.academy_live_sessions session
  where session.id = p_live_session_id;

  if v_session.id is null then
    raise exception 'Live session not found';
  end if;

  select assignment.headquarters_id
  into v_headquarters_id
  from public.academy_program_assignments assignment
  where assignment.id = v_session.assignment_id;

  if not public.academy_can_approve_program_progress(v_headquarters_id) then
    raise exception 'Attendance permission required';
  end if;

  v_status := case when p_attended then 'attended' else 'absent' end;

  update public.academy_live_sessions
  set
    status = 'completed',
    attendance_status = v_status,
    note = nullif(trim(coalesce(p_note, '')), ''),
    reviewed_at = now(),
    reviewed_by_user_id = (select auth.uid()),
    updated_at = now()
  where id = p_live_session_id;

  update public.academy_step_progress
  set
    status = case when p_attended then 'completed' else 'not_started' end,
    completed_at = case when p_attended then now() else null end,
    approved_by_user_id = (select auth.uid()),
    review_note = nullif(trim(coalesce(p_note, '')), ''),
    reviewed_at = now(),
    updated_at = now()
  where assignment_id = v_session.assignment_id
    and step_id = v_session.step_id;

  return v_status;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_mark_program_draft"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_program_id uuid;
  v_section_id uuid;
begin
  if tg_table_name = 'academy_program_sections' then
    v_program_id := coalesce(new.program_id, old.program_id);
  else
    v_section_id := coalesce(new.section_id, old.section_id);
    select section.program_id
    into v_program_id
    from public.academy_program_sections section
    where section.id = v_section_id;
  end if;

  if v_program_id is not null then
    update public.academy_programs
    set status = 'draft', updated_at = now()
    where id = v_program_id
      and status = 'published';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_pin_class_program_version"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.program_version_id is null then
    select version.id
    into new.program_version_id
    from public.academy_program_versions version
    where version.program_id = new.program_id
    order by version.version_number desc
    limit 1;
  end if;

  if new.program_version_id is null then
    raise exception 'Publish the program before creating a class';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_pin_program_version"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_enrollment_version_id uuid;
begin
  if new.enrollment_id is not null then
    select class.program_version_id
    into v_enrollment_version_id
    from public.academy_enrollments enrollment
    join public.academy_classes class
      on class.id = enrollment.class_id
    where enrollment.id = new.enrollment_id;

    if v_enrollment_version_id is not null then
      new.program_version_id := v_enrollment_version_id;
    end if;
  end if;

  if new.program_version_id is null then
    select version.id
    into new.program_version_id
    from public.academy_program_versions version
    where version.program_id = new.program_id
    order by version.version_number desc
    limit 1;
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_profile_has_program_access"("p_profile_id" "uuid", "p_program_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.profiles profile
    where profile.id = p_profile_id
      and profile.user_id = (select auth.uid())
  )
  and (
    not exists (
      select 1
      from public.academy_subscription_product_programs mapping
      where mapping.program_id = p_program_id
    )
    or exists (
      select 1
      from public.academy_entitlement_grants entitlement
      where entitlement.member_profile_id = p_profile_id
        and entitlement.program_id = p_program_id
        and entitlement.status = 'active'
        and (entitlement.ends_at is null or entitlement.ends_at > now())
    )
    or exists (
      select 1
      from public.academy_program_assignments assignment
      where assignment.learner_profile_id = p_profile_id
        and assignment.program_id = p_program_id
        and assignment.status = 'active'
        and private.academy_active_program_license_exists(
          assignment.program_id,
          assignment.headquarters_id,
          assignment.program_version_id
        )
    )
  );
$$;



SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."academy_credential_applications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "credential_id" "uuid" NOT NULL,
    "applicant_profile_id" "uuid" NOT NULL,
    "holder_id" "uuid",
    "request_type" "text" NOT NULL,
    "status" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "applicant_note" "text",
    "review_note" "text",
    "reviewed_by_user_id" "uuid",
    "submitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "academy_credential_applications_request_type_check" CHECK (("request_type" = ANY (ARRAY['initial'::"text", 'renewal'::"text"]))),
    CONSTRAINT "academy_credential_applications_status_check" CHECK (("status" = ANY (ARRAY['submitted'::"text", 'approved'::"text", 'rejected'::"text", 'cancelled'::"text"])))
);




CREATE OR REPLACE FUNCTION "private"."academy_review_credential_application_impl"("p_application_id" "uuid", "p_approved" boolean, "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."academy_credential_applications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_application public.academy_credential_applications%rowtype;
  v_credential public.academy_credentials%rowtype;
  v_holder public.academy_credential_holders%rowtype;
  v_base_expires_at timestamptz;
  v_next_expires_at timestamptz;
begin
  if v_actor_user_id is null then
    raise exception 'Authentication required';
  end if;

  select *
  into v_application
  from public.academy_credential_applications
  where id = p_application_id
  for update;

  if v_application.id is null then
    raise exception 'Credential application not found';
  end if;

  if v_application.status <> 'submitted' then
    raise exception 'Credential application is already reviewed';
  end if;

  select *
  into v_credential
  from public.academy_credentials
  where id = v_application.credential_id;

  if v_credential.id is null or not public.academy_owns_hq(v_credential.headquarters_id) then
    raise exception 'Permission denied';
  end if;

  if p_approved then
    select *
    into v_holder
    from public.academy_credential_holders
    where credential_id = v_application.credential_id
      and holder_profile_id = v_application.applicant_profile_id
    for update;

    if v_application.request_type = 'renewal' and v_holder.id is null then
      raise exception 'Renewal requires an existing credential holder';
    end if;

    v_base_expires_at := case
      when v_application.request_type = 'renewal'
        then greatest(coalesce(v_holder.expires_at, now()), now())
      else now()
    end;
    v_next_expires_at := private.academy_calculate_credential_expires_at(v_credential.renewal_months, v_base_expires_at);

    insert into public.academy_credential_holders(
      credential_id,
      holder_profile_id,
      status,
      issued_at,
      expires_at
    )
    values (
      v_application.credential_id,
      v_application.applicant_profile_id,
      'active',
      now(),
      v_next_expires_at
    )
    on conflict (credential_id, holder_profile_id)
    do update set
      status = 'active',
      expires_at = excluded.expires_at,
      updated_at = now()
    returning * into v_holder;

    update public.academy_credential_applications
    set
      holder_id = v_holder.id,
      status = 'approved',
      review_note = nullif(trim(coalesce(p_note, '')), ''),
      reviewed_by_user_id = v_actor_user_id,
      reviewed_at = now(),
      updated_at = now()
    where id = p_application_id
    returning * into v_application;
  else
    update public.academy_credential_applications
    set
      status = 'rejected',
      review_note = nullif(trim(coalesce(p_note, '')), ''),
      reviewed_by_user_id = v_actor_user_id,
      reviewed_at = now(),
      updated_at = now()
    where id = p_application_id
    returning * into v_application;
  end if;

  return v_application;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_review_step_submission"("p_submission_id" "uuid", "p_approved" boolean, "p_review_note" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_submission public.academy_step_submissions%rowtype;
  v_headquarters_id uuid;
  v_result text;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select submission.*, assignment.headquarters_id
  into
    v_submission.id,
    v_submission.assignment_id,
    v_submission.step_id,
    v_submission.attempt_number,
    v_submission.body,
    v_submission.attachment_url,
    v_submission.status,
    v_submission.submitted_at,
    v_submission.reviewed_at,
    v_submission.reviewed_by_user_id,
    v_submission.review_note,
    v_submission.created_at,
    v_submission.updated_at,
    v_headquarters_id
  from public.academy_step_submissions submission
  join public.academy_program_assignments assignment
    on assignment.id = submission.assignment_id
  where submission.id = p_submission_id
    and submission.status = 'submitted';

  if v_submission.id is null then
    raise exception 'Pending submission not found';
  end if;

  if not public.academy_can_approve_program_progress(v_headquarters_id) then
    raise exception 'Review permission required';
  end if;

  if not p_approved and nullif(trim(coalesce(p_review_note, '')), '') is null then
    raise exception 'A return reason is required';
  end if;

  v_result := case when p_approved then 'approved' else 'returned' end;

  update public.academy_step_submissions
  set
    status = v_result,
    reviewed_at = now(),
    reviewed_by_user_id = (select auth.uid()),
    review_note = nullif(trim(coalesce(p_review_note, '')), ''),
    updated_at = now()
  where id = p_submission_id;

  update public.academy_step_progress
  set
    status = case when p_approved then 'completed' else 'not_started' end,
    completed_at = case when p_approved then now() else null end,
    approved_by_user_id = (select auth.uid()),
    review_note = nullif(trim(coalesce(p_review_note, '')), ''),
    reviewed_at = now(),
    updated_at = now()
  where assignment_id = v_submission.assignment_id
    and step_id = v_submission.step_id;

  return v_result;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_schedule_live_session"("p_assignment_id" "uuid", "p_step_id" "uuid", "p_scheduled_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_meeting_url" "text" DEFAULT NULL::"text", "p_meeting_id" "text" DEFAULT NULL::"text", "p_passcode" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_headquarters_id uuid;
  v_session_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select assignment.headquarters_id
  into v_headquarters_id
  from public.academy_program_assignments assignment
  where assignment.id = p_assignment_id
    and assignment.status = 'active';

  if v_headquarters_id is null then
    raise exception 'Assignment unavailable';
  end if;

  if not public.academy_can_approve_program_progress(v_headquarters_id) then
    raise exception 'Schedule permission required';
  end if;

  if private.academy_assignment_step_type(p_assignment_id, p_step_id) is distinct from 'live_session' then
    raise exception 'This step is not a live session';
  end if;

  insert into public.academy_live_sessions(
    assignment_id,
    step_id,
    scheduled_at,
    meeting_url,
    meeting_id,
    passcode,
    status,
    attendance_status,
    note
  )
  values (
    p_assignment_id,
    p_step_id,
    p_scheduled_at,
    nullif(trim(coalesce(p_meeting_url, '')), ''),
    nullif(trim(coalesce(p_meeting_id, '')), ''),
    nullif(trim(coalesce(p_passcode, '')), ''),
    'scheduled',
    'pending',
    nullif(trim(coalesce(p_note, '')), '')
  )
  on conflict (assignment_id, step_id)
  do update set
    scheduled_at = excluded.scheduled_at,
    meeting_url = excluded.meeting_url,
    meeting_id = excluded.meeting_id,
    passcode = excluded.passcode,
    status = 'scheduled',
    attendance_status = 'pending',
    note = excluded.note,
    reviewed_at = null,
    reviewed_by_user_id = null,
    updated_at = now()
  returning id into v_session_id;

  insert into public.academy_step_progress(
    assignment_id,
    step_id,
    status,
    completed_at,
    approved_by_user_id,
    review_note,
    reviewed_at
  )
  values (
    p_assignment_id,
    p_step_id,
    'awaiting_approval',
    null,
    null,
    null,
    null
  )
  on conflict (assignment_id, step_id)
  do update set
    status = 'awaiting_approval',
    completed_at = null,
    approved_by_user_id = null,
    review_note = null,
    reviewed_at = null,
    updated_at = now();

  return v_session_id;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_set_program_license_status"("p_license_id" "uuid", "p_status" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_license public.academy_program_licenses%rowtype;
  v_now timestamptz := now();
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  if p_status not in ('active', 'paused', 'revoked') then
    raise exception 'Invalid license status';
  end if;

  select *
  into v_license
  from public.academy_program_licenses
  where id = p_license_id
    and public.academy_owns_hq(licensor_headquarters_id)
  for update;

  if v_license.id is null then
    raise exception 'License not found or permission denied';
  end if;

  update public.academy_program_licenses
  set status = p_status,
      ends_at = case when p_status = 'active' then null else v_now end,
      note = coalesce(nullif(trim(coalesce(p_note, '')), ''), note),
      updated_at = v_now
  where id = p_license_id;

  update public.academy_program_assignments assignment
  set status = case when p_status = 'active' then 'active' else 'paused' end,
      updated_at = v_now
  where assignment.headquarters_id = v_license.licensee_headquarters_id
    and assignment.program_id = v_license.program_id
    and assignment.status <> 'completed';

  return p_status;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_submit_credential_application_impl"("p_credential_id" "uuid", "p_request_type" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."academy_credential_applications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_applicant_profile_id uuid;
  v_holder_id uuid;
  v_application public.academy_credential_applications%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'Authentication required';
  end if;

  if p_request_type not in ('initial', 'renewal') then
    raise exception 'Unsupported credential application type';
  end if;

  select profile.id
  into v_applicant_profile_id
  from public.profiles profile
  where profile.user_id = v_actor_user_id
  order by profile.created_at asc
  limit 1;

  if v_applicant_profile_id is null then
    raise exception 'Profile not found';
  end if;

  if not exists (
    select 1
    from public.academy_credentials credential
    join public.academy_memberships membership
      on membership.headquarters_id = credential.headquarters_id
    where credential.id = p_credential_id
      and credential.is_active = true
      and membership.member_profile_id = v_applicant_profile_id
      and membership.status = 'active'
  ) then
    raise exception 'Credential not found or membership inactive';
  end if;

  select holder.id
  into v_holder_id
  from public.academy_credential_holders holder
  where holder.credential_id = p_credential_id
    and holder.holder_profile_id = v_applicant_profile_id;

  if p_request_type = 'renewal' and v_holder_id is null then
    raise exception 'Renewal requires an existing credential holder';
  end if;

  if p_request_type = 'initial' and exists (
    select 1
    from public.academy_credential_holders holder
    where holder.credential_id = p_credential_id
      and holder.holder_profile_id = v_applicant_profile_id
      and holder.status = 'active'
  ) then
    raise exception 'Credential is already active';
  end if;

  insert into public.academy_credential_applications(
    credential_id,
    applicant_profile_id,
    holder_id,
    request_type,
    status,
    applicant_note
  )
  values (
    p_credential_id,
    v_applicant_profile_id,
    v_holder_id,
    p_request_type,
    'submitted',
    nullif(trim(coalesce(p_note, '')), '')
  )
  on conflict (credential_id, applicant_profile_id, request_type)
    where status = 'submitted'
  do update set
    applicant_note = excluded.applicant_note,
    holder_id = excluded.holder_id,
    submitted_at = now(),
    updated_at = now()
  returning * into v_application;

  return v_application;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_submit_program_step"("p_assignment_id" "uuid", "p_step_id" "uuid", "p_body" "text", "p_attachment_url" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_program_id uuid;
  v_program_version_id uuid;
  v_snapshot jsonb;
  v_step_type text;
  v_attempt_number integer;
  v_submission_id uuid := gen_random_uuid();
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  if nullif(trim(coalesce(p_body, '')), '') is null
    and nullif(trim(coalesce(p_attachment_url, '')), '') is null
  then
    raise exception 'Submission text or attachment URL is required';
  end if;

  select assignment.program_id, assignment.program_version_id
  into v_program_id, v_program_version_id
  from public.academy_program_assignments assignment
  join public.profiles learner
    on learner.id = assignment.learner_profile_id
  where assignment.id = p_assignment_id
    and assignment.status = 'active'
    and learner.user_id = (select auth.uid())
    and private.academy_profile_has_program_access(
      assignment.learner_profile_id,
      assignment.program_id
    );

  if v_program_id is null then
    raise exception 'Assignment unavailable';
  end if;

  if v_program_version_id is null then
    select step.step_type
    into v_step_type
    from public.academy_program_steps step
    join public.academy_program_sections section
      on section.id = step.section_id
    where step.id = p_step_id
      and section.program_id = v_program_id;
  else
    select version.content_snapshot
    into v_snapshot
    from public.academy_program_versions version
    where version.id = v_program_version_id
      and version.program_id = v_program_id;

    select step.value ->> 'step_type'
    into v_step_type
    from jsonb_array_elements(v_snapshot -> 'sections') section(value)
    cross join lateral jsonb_array_elements(section.value -> 'steps') step(value)
    where (step.value ->> 'id')::uuid = p_step_id;
  end if;

  if v_step_type is distinct from 'submission' then
    raise exception 'This step does not accept submissions';
  end if;

  if exists (
    select 1
    from public.academy_step_submissions submission
    where submission.assignment_id = p_assignment_id
      and submission.step_id = p_step_id
      and submission.status = 'submitted'
  ) then
    raise exception 'A submission is already awaiting review';
  end if;

  select coalesce(max(submission.attempt_number), 0) + 1
  into v_attempt_number
  from public.academy_step_submissions submission
  where submission.assignment_id = p_assignment_id
    and submission.step_id = p_step_id;

  insert into public.academy_step_submissions(
    id,
    assignment_id,
    step_id,
    attempt_number,
    body,
    attachment_url,
    status
  )
  values (
    v_submission_id,
    p_assignment_id,
    p_step_id,
    v_attempt_number,
    nullif(trim(coalesce(p_body, '')), ''),
    nullif(trim(coalesce(p_attachment_url, '')), ''),
    'submitted'
  );

  insert into public.academy_step_progress(
    assignment_id,
    step_id,
    status,
    completed_at,
    approved_by_user_id,
    review_note,
    reviewed_at
  )
  values (
    p_assignment_id,
    p_step_id,
    'awaiting_approval',
    null,
    null,
    null,
    null
  )
  on conflict (assignment_id, step_id)
  do update set
    status = 'awaiting_approval',
    completed_at = null,
    approved_by_user_id = null,
    review_note = null,
    reviewed_at = null,
    updated_at = now();

  return v_submission_id;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."academy_submit_step_test"("p_assignment_id" "uuid", "p_step_id" "uuid", "p_answers" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_program_id uuid;
  v_profile_id uuid;
  v_attempt_number integer;
  v_attempt_id uuid := gen_random_uuid();
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select profile.id
  into v_profile_id
  from public.profiles profile
  where profile.user_id = (select auth.uid())
  limit 1;

  select assignment.program_id
  into v_program_id
  from public.academy_program_assignments assignment
  where assignment.id = p_assignment_id
    and assignment.learner_profile_id = v_profile_id
    and assignment.status = 'active';

  if v_program_id is null
    or not private.academy_profile_has_program_access(v_profile_id, v_program_id)
  then
    raise exception 'Assignment unavailable';
  end if;

  if private.academy_assignment_step_type(p_assignment_id, p_step_id) is distinct from 'test' then
    raise exception 'This step is not a test';
  end if;

  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    raise exception 'Answers must be a JSON object';
  end if;

  if exists (
    select 1
    from public.academy_step_test_attempts attempt
    where attempt.assignment_id = p_assignment_id
      and attempt.step_id = p_step_id
      and attempt.status = 'submitted'
  ) then
    raise exception 'A test attempt is already awaiting grading';
  end if;

  select coalesce(max(attempt.attempt_number), 0) + 1
  into v_attempt_number
  from public.academy_step_test_attempts attempt
  where attempt.assignment_id = p_assignment_id
    and attempt.step_id = p_step_id;

  insert into public.academy_step_test_attempts(
    id,
    assignment_id,
    step_id,
    attempt_number,
    answers,
    status
  )
  values (
    v_attempt_id,
    p_assignment_id,
    p_step_id,
    v_attempt_number,
    p_answers,
    'submitted'
  );

  insert into public.academy_step_progress(
    assignment_id,
    step_id,
    status,
    completed_at,
    approved_by_user_id,
    review_note,
    reviewed_at
  )
  values (
    p_assignment_id,
    p_step_id,
    'awaiting_approval',
    null,
    null,
    null,
    null
  )
  on conflict (assignment_id, step_id)
  do update set
    status = 'awaiting_approval',
    completed_at = null,
    approved_by_user_id = null,
    review_note = null,
    reviewed_at = null,
    updated_at = now();

  return v_attempt_id;
end;
$$;




CREATE TABLE IF NOT EXISTS "public"."academy_classes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "headquarters_id" "uuid" NOT NULL,
    "course_id" "uuid" NOT NULL,
    "program_id" "uuid" NOT NULL,
    "instructor_id" "uuid",
    "title" "text" NOT NULL,
    "starts_at" timestamp with time zone NOT NULL,
    "format" "text" NOT NULL,
    "status" "text" DEFAULT 'planned'::"text" NOT NULL,
    "created_by_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "program_version_id" "uuid",
    "ends_at" timestamp with time zone,
    "capacity" integer,
    "venue_name" "text",
    "meeting_url" "text",
    "schedule_mode" "text" DEFAULT 'fixed'::"text" NOT NULL,
    "registration_status" "text" DEFAULT 'open'::"text" NOT NULL,
    CONSTRAINT "academy_classes_capacity_check" CHECK ((("capacity" IS NULL) OR ("capacity" > 0))),
    CONSTRAINT "academy_classes_ends_after_starts_check" CHECK ((("ends_at" IS NULL) OR ("ends_at" > "starts_at"))),
    CONSTRAINT "academy_classes_format_check" CHECK (("format" = ANY (ARRAY['in_person'::"text", 'online'::"text"]))),
    CONSTRAINT "academy_classes_registration_status_check" CHECK (("registration_status" = ANY (ARRAY['draft'::"text", 'open'::"text", 'closed'::"text"]))),
    CONSTRAINT "academy_classes_schedule_mode_check" CHECK (("schedule_mode" = ANY (ARRAY['fixed'::"text", 'arranged_after_application'::"text"]))),
    CONSTRAINT "academy_classes_status_check" CHECK (("status" = ANY (ARRAY['planned'::"text", 'active'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "academy_classes_title_check" CHECK (("length"(TRIM(BOTH FROM "title")) > 0))
);




CREATE OR REPLACE FUNCTION "private"."academy_update_class_status_impl"("p_class_id" "uuid", "p_status" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."academy_classes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_class public.academy_classes%rowtype;
  v_next public.academy_classes%rowtype;
  v_is_owner boolean := false;
  v_is_instructor boolean := false;
begin
  if v_actor_user_id is null then
    raise exception 'Authentication required';
  end if;

  if p_status not in ('active', 'completed', 'cancelled') then
    raise exception 'Unsupported class status';
  end if;

  select *
  into v_class
  from public.academy_classes
  where id = p_class_id
  for update;

  if v_class.id is null then
    raise exception 'Class not found';
  end if;

  v_is_owner := public.academy_owns_hq(v_class.headquarters_id);

  select exists (
    select 1
    from public.academy_instructors instructor
    where instructor.id = v_class.instructor_id
      and instructor.user_id = v_actor_user_id
      and instructor.is_active = true
  )
  into v_is_instructor;

  if not v_is_owner and not v_is_instructor then
    raise exception 'Permission denied';
  end if;

  if v_is_instructor and not v_is_owner and p_status not in ('active', 'completed') then
    raise exception 'Only headquarters can cancel a class';
  end if;

  if v_class.status in ('completed', 'cancelled') then
    raise exception 'Completed or cancelled class cannot be changed';
  end if;

  if v_class.status = 'planned' and p_status not in ('active', 'cancelled') then
    raise exception 'Planned class can only be started or cancelled';
  end if;

  if v_class.status = 'active' and p_status not in ('completed', 'cancelled') then
    raise exception 'Active class can only be completed or cancelled';
  end if;

  if v_class.status = p_status then
    return v_class;
  end if;

  update public.academy_classes
  set status = p_status,
      updated_at = now()
  where id = p_class_id
  returning * into v_next;

  insert into public.academy_class_status_events(
    class_id,
    actor_user_id,
    from_status,
    to_status,
    note
  )
  values (
    p_class_id,
    v_actor_user_id,
    v_class.status,
    p_status,
    nullif(trim(coalesce(p_note, '')), '')
  );

  if p_status = 'completed' then
    update public.academy_enrollments
    set status = 'completed',
        completed_at = coalesce(completed_at, now()),
        updated_at = now()
    where class_id = p_class_id
      and status = 'active';
  elsif p_status = 'cancelled' then
    update public.academy_enrollments
    set status = 'cancelled',
        completed_at = null,
        updated_at = now()
    where class_id = p_class_id
      and status <> 'cancelled';

    update public.academy_program_assignments assignment
    set status = 'paused',
        updated_at = now()
    where assignment.enrollment_id in (
      select enrollment.id
      from public.academy_enrollments enrollment
      where enrollment.class_id = p_class_id
    )
      and assignment.status = 'active';
  end if;

  return v_next;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."audit_mikkeos_email_campaign_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  audit_entity_id uuid;
  audit_status text;
  audit_campaign_type text;
begin
  if tg_op = 'DELETE' then
    audit_entity_id := old.id;
    audit_status := old.status;
    audit_campaign_type := old.campaign_type;
  else
    audit_entity_id := new.id;
    audit_status := new.status;
    audit_campaign_type := new.campaign_type;
  end if;

  insert into public.mikkeos_hq_audit_logs (
    actor_user_id, action, entity_type, entity_id, details
  ) values (
    (select auth.uid()), lower(tg_op), 'mikkeos_email_campaigns', audit_entity_id,
    jsonb_build_object('status', audit_status, 'campaign_type', audit_campaign_type)
  );

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."cancel_mikke_media_reservation"("p_asset_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_owner uuid := auth.uid();
begin
  if v_owner is null then
    raise exception 'MIKKE_MEDIA_AUTH_REQUIRED';
  end if;
  delete from public.mikke_media_assets
  where id = p_asset_id and owner_id = v_owner and status = 'pending';
end;
$$;




CREATE TABLE IF NOT EXISTS "public"."mikke_media_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "storage_path" "text" NOT NULL,
    "original_name" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "byte_size" bigint NOT NULL,
    "width" integer,
    "height" integer,
    "source_app" "text" DEFAULT 'page'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "trashed_at" timestamp with time zone,
    CONSTRAINT "mikke_media_assets_byte_size_check" CHECK ((("byte_size" > 0) AND ("byte_size" <= 3145728))),
    CONSTRAINT "mikke_media_assets_height_check" CHECK ((("height" IS NULL) OR ("height" > 0))),
    CONSTRAINT "mikke_media_assets_mime_type_check" CHECK (("mime_type" = 'image/webp'::"text")),
    CONSTRAINT "mikke_media_assets_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'active'::"text", 'trashed'::"text"]))),
    CONSTRAINT "mikke_media_assets_width_check" CHECK ((("width" IS NULL) OR ("width" > 0)))
);




CREATE OR REPLACE FUNCTION "private"."finalize_mikke_media_asset"("p_asset_id" "uuid") RETURNS "public"."mikke_media_assets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_owner uuid := auth.uid();
  v_asset public.mikke_media_assets;
  v_object_size bigint;
begin
  if v_owner is null then
    raise exception 'MIKKE_MEDIA_AUTH_REQUIRED';
  end if;

  select * into v_asset
  from public.mikke_media_assets
  where id = p_asset_id and owner_id = v_owner and status = 'pending'
  for update;

  if v_asset.id is null then
    raise exception 'MIKKE_MEDIA_RESERVATION_NOT_FOUND';
  end if;

  select nullif(metadata->>'size', '')::bigint into v_object_size
  from storage.objects
  where bucket_id = 'mikke-media'
    and name = v_asset.storage_path
    and owner_id = v_owner::text;

  if v_object_size is null then
    raise exception 'MIKKE_MEDIA_OBJECT_NOT_FOUND';
  end if;
  if v_object_size <> v_asset.byte_size then
    raise exception 'MIKKE_MEDIA_SIZE_MISMATCH';
  end if;

  update public.mikke_media_assets
  set status = 'active', updated_at = now()
  where id = v_asset.id
  returning * into v_asset;

  return v_asset;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."prepare_fund_challenge_record"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.source_local_id := btrim(new.source_local_id);
  new.title := btrim(new.title);
  new.summary := btrim(new.summary);
  new.outcome := btrim(coalesce(new.outcome, ''));
  new.image_url := btrim(coalesce(new.image_url, ''));
  new.story_enabled := coalesce(new.story_enabled, false) and new.visibility = 'public';

  if tg_op = 'UPDATE' then
    new.project_id := old.project_id;
    new.source_local_id := old.source_local_id;
    new.created_at := old.created_at;
    new.published_at := case
      when new.visibility = 'public' then coalesce(old.published_at, new.published_at, now())
      else null
    end;
  else
    new.created_at := now();
    new.published_at := case when new.visibility = 'public' then coalesce(new.published_at, now()) else null end;
  end if;

  new.updated_at := now();
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."prepare_fund_support"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.source_local_id := btrim(new.source_local_id);
  new.plan_source_id := nullif(btrim(new.plan_source_id), '');
  new.supporter_name := btrim(new.supporter_name);
  new.supporter_email := nullif(btrim(new.supporter_email), '');
  new.public_name := btrim(coalesce(new.public_name, ''));
  new.comment := btrim(coalesce(new.comment, ''));
  new.source := coalesce(nullif(btrim(new.source), ''), 'manual');

  if tg_op = 'UPDATE' then
    new.project_id := old.project_id;
    new.source_local_id := old.source_local_id;
    new.created_at := old.created_at;
    new.completed_at := case
      when new.fulfillment_status = 'completed' then coalesce(old.completed_at, new.completed_at, now())
      else null
    end;
    new.cancelled_at := case
      when new.payment_status = 'cancelled' or new.fulfillment_status = 'cancelled'
        then coalesce(old.cancelled_at, new.cancelled_at, now())
      else null
    end;
  else
    new.created_at := now();
    new.completed_at := case when new.fulfillment_status = 'completed' then coalesce(new.completed_at, now()) else null end;
    new.cancelled_at := case
      when new.payment_status = 'cancelled' or new.fulfillment_status = 'cancelled'
        then coalesce(new.cancelled_at, now())
      else null
    end;
  end if;

  new.updated_at := now();
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."prepare_fund_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.title := btrim(new.title);
  new.body := btrim(new.body);
  new.image_url := btrim(coalesce(new.image_url, ''));

  if tg_op = 'INSERT' then
    new.created_at := now();
  else
    new.project_id := old.project_id;
    new.source_local_id := old.source_local_id;
    new.created_at := old.created_at;
  end if;

  new.published_at := case
    when new.visibility = 'public' and tg_op = 'UPDATE' and old.visibility = 'public'
      then old.published_at
    when new.visibility = 'public' then now()
    else null
  end;
  new.updated_at := now();
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."purge_mikke_media_asset_record"("p_asset_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_owner uuid := auth.uid();
  v_path text;
begin
  if v_owner is null then raise exception 'MIKKE_MEDIA_AUTH_REQUIRED'; end if;
  select storage_path into v_path
  from public.mikke_media_assets
  where id = p_asset_id and owner_id = v_owner and status = 'trashed';
  if v_path is null then raise exception 'MIKKE_MEDIA_ASSET_NOT_AVAILABLE'; end if;
  if exists (select 1 from storage.objects where bucket_id = 'mikke-media' and name = v_path) then
    raise exception 'MIKKE_MEDIA_OBJECT_STILL_EXISTS';
  end if;
  delete from public.mikke_media_assets where id = p_asset_id and owner_id = v_owner;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."reserve_mikke_media_asset"("p_storage_path" "text", "p_original_name" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_width" integer, "p_height" integer, "p_source_app" "text") RETURNS "public"."mikke_media_assets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_owner uuid := auth.uid();
  v_max_bytes bigint;
  v_used_bytes bigint;
  v_asset public.mikke_media_assets;
begin
  if v_owner is null then
    raise exception 'MIKKE_MEDIA_AUTH_REQUIRED';
  end if;
  if p_mime_type <> 'image/webp' or p_byte_size <= 0 or p_byte_size > 3145728 then
    raise exception 'MIKKE_MEDIA_INVALID_FILE';
  end if;
  if p_storage_path !~ ('^' || v_owner::text || '/images/[0-9]{4}-[0-9]{2}/[a-zA-Z0-9-]+[.]webp$') then
    raise exception 'MIKKE_MEDIA_INVALID_PATH';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_owner::text, 0));

  insert into public.mikke_media_accounts (owner_id)
  values (v_owner)
  on conflict (owner_id) do nothing;

  select max_bytes into v_max_bytes
  from public.mikke_media_accounts
  where owner_id = v_owner;

  select coalesce(sum(byte_size), 0) into v_used_bytes
  from public.mikke_media_assets
  where owner_id = v_owner
    and status in ('pending', 'active', 'trashed');

  if v_used_bytes + p_byte_size > v_max_bytes then
    raise exception 'MIKKE_MEDIA_QUOTA_EXCEEDED';
  end if;

  insert into public.mikke_media_assets (
    owner_id, storage_path, original_name, mime_type, byte_size,
    width, height, source_app, status
  ) values (
    v_owner, p_storage_path, left(coalesce(nullif(p_original_name, ''), 'image.webp'), 255),
    p_mime_type, p_byte_size, p_width, p_height,
    left(coalesce(nullif(p_source_app, ''), 'unknown'), 50), 'pending'
  ) returning * into v_asset;

  return v_asset;
end;
$_$;




CREATE OR REPLACE FUNCTION "private"."restore_mikke_media_asset"("p_asset_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_owner uuid := auth.uid();
begin
  if v_owner is null then raise exception 'MIKKE_MEDIA_AUTH_REQUIRED'; end if;
  update public.mikke_media_assets
  set status = 'active', trashed_at = null, updated_at = now()
  where id = p_asset_id and owner_id = v_owner and status = 'trashed';
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_completion_after_public_project_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_record_id uuid;
  v_project_id uuid := case when tg_op = 'DELETE' then old.project_id else new.project_id end;
begin
  select id into v_record_id
  from public.fund_challenge_records
  where project_id = v_project_id;
  if v_record_id is not null then
    perform private.sync_fund_completion_outputs(v_record_id);
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_completion_after_record_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_project public.fund_projects%rowtype;
begin
  if tg_op = 'DELETE' then
    select * into v_project from public.fund_projects where id = old.project_id;
    delete from public.fund_public_challenge_records where challenge_record_id = old.id;
    if v_project.id is not null then
      delete from public.activity_logs
      where profile_id = v_project.owner_profile_id
        and source_service = 'fund'
        and source_record_id = 'completion:' || v_project.source_local_id;
    end if;
    return old;
  end if;

  perform private.sync_fund_completion_outputs(new.id);
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_completion_outputs"("p_challenge_record_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_record public.fund_challenge_records%rowtype;
  v_project public.fund_projects%rowtype;
  v_public_project public.fund_public_projects%rowtype;
  v_has_public_project boolean := false;
  v_story_public boolean := false;
  v_source_record_id text;
begin
  select * into v_record
  from public.fund_challenge_records
  where id = p_challenge_record_id;
  if not found then return; end if;

  select * into v_project
  from public.fund_projects
  where id = v_record.project_id;
  if not found then return; end if;

  select * into v_public_project
  from public.fund_public_projects
  where project_id = v_record.project_id;
  v_has_public_project := found;
  v_story_public := v_has_public_project and v_record.visibility = 'public' and v_record.story_enabled;

  if v_has_public_project and v_record.visibility = 'public' then
    insert into public.fund_public_challenge_records (
      challenge_record_id, project_id, profile_slug, project_slug,
      public_fund_path, title, summary, outcome, image_url,
      story_enabled, completed_at, published_at, updated_at
    ) values (
      v_record.id, v_record.project_id, v_public_project.profile_slug, v_public_project.slug,
      '/fund/' || v_public_project.profile_slug || '/' || v_public_project.slug,
      v_record.title, v_record.summary, v_record.outcome, v_record.image_url,
      v_record.story_enabled, v_record.completed_at, coalesce(v_record.published_at, now()), v_record.updated_at
    )
    on conflict (challenge_record_id) do update set
      project_id = excluded.project_id,
      profile_slug = excluded.profile_slug,
      project_slug = excluded.project_slug,
      public_fund_path = excluded.public_fund_path,
      title = excluded.title,
      summary = excluded.summary,
      outcome = excluded.outcome,
      image_url = excluded.image_url,
      story_enabled = excluded.story_enabled,
      completed_at = excluded.completed_at,
      published_at = excluded.published_at,
      updated_at = excluded.updated_at;
  else
    delete from public.fund_public_challenge_records
    where challenge_record_id = v_record.id;
  end if;

  v_source_record_id := 'completion:' || v_project.source_local_id;
  insert into public.activity_logs (
    user_id, profile_id, activity_type, category, source_service,
    source_record_id, occurred_at, title, description, visibility, status,
    display_on_story, display_in_timeline, display_as_achievement,
    counts_toward_summary, has_financial_value, amount,
    transaction_type, payment_status
  ) values (
    v_project.owner_user_id, v_project.owner_profile_id,
    'fund_project_completed', 'production', 'fund',
    v_source_record_id, v_record.completed_at::timestamp at time zone 'UTC',
    v_record.title, v_record.summary, 'private', 'completed',
    false, true, v_story_public, v_story_public,
    false, null, 'none', 'not_required'
  )
  on conflict (profile_id, source_service, source_record_id) do update set
    user_id = excluded.user_id,
    activity_type = excluded.activity_type,
    category = excluded.category,
    occurred_at = excluded.occurred_at,
    title = excluded.title,
    description = excluded.description,
    visibility = excluded.visibility,
    status = excluded.status,
    display_on_story = excluded.display_on_story,
    display_in_timeline = excluded.display_in_timeline,
    display_as_achievement = excluded.display_as_achievement,
    counts_toward_summary = excluded.counts_toward_summary,
    has_financial_value = excluded.has_financial_value,
    amount = excluded.amount,
    transaction_type = excluded.transaction_type,
    payment_status = excluded.payment_status,
    updated_at = now();
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_public_participation"("p_participation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_participation public.fund_participations%rowtype;
  v_project public.fund_projects%rowtype;
  v_support public.fund_supports%rowtype;
  v_owner_handle text;
  v_display_name text;
begin
  select * into v_participation
  from public.fund_participations
  where id = p_participation_id;

  if not found then
    delete from public.fund_public_participations
    where participation_id = p_participation_id;
    return;
  end if;

  select * into v_project
  from public.fund_projects
  where id = v_participation.project_id;

  select * into v_support
  from public.fund_supports
  where id = v_participation.support_id;

  select handle into v_owner_handle
  from public.profiles
  where id = v_project.owner_profile_id;

  if v_project.visibility <> 'public'
    or v_support.record_status <> 'valid'
    or v_participation.owner_consent_status <> 'granted'
    or v_participation.supporter_consent_status <> 'granted'
    or v_participation.display_mode = 'hidden'
    or v_owner_handle is null then
    delete from public.fund_public_participations
    where participation_id = p_participation_id;
    return;
  end if;

  v_display_name := case
    when v_participation.display_mode = 'anonymous' then '匿名の応援者'
    else coalesce(nullif(btrim(v_participation.public_name), ''), '応援者')
  end;

  insert into public.fund_public_participations (
    participation_id,
    project_id,
    project_title,
    supporter_profile_id,
    display_name,
    is_anonymous,
    public_fund_path,
    published_at
  ) values (
    v_participation.id,
    v_participation.project_id,
    v_project.title,
    case when v_participation.display_mode = 'anonymous' then null else v_participation.supporter_profile_id end,
    v_display_name,
    v_participation.display_mode = 'anonymous',
    '/fund/' || v_owner_handle || '/' || v_project.slug,
    now()
  )
  on conflict (participation_id) do update set
    project_id = excluded.project_id,
    project_title = excluded.project_title,
    supporter_profile_id = excluded.supporter_profile_id,
    display_name = excluded.display_name,
    is_anonymous = excluded.is_anonymous,
    public_fund_path = excluded.public_fund_path,
    published_at = excluded.published_at;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_public_participation_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_participation_id uuid;
begin
  if tg_table_name = 'fund_participations' then
    perform private.sync_fund_public_participation(new.id);
  elsif tg_table_name = 'fund_projects' then
    for v_participation_id in
      select id from public.fund_participations where project_id = new.id
    loop
      perform private.sync_fund_public_participation(v_participation_id);
    end loop;
  elsif tg_table_name = 'fund_supports' then
    for v_participation_id in
      select id from public.fund_participations where support_id = new.id
    loop
      perform private.sync_fund_public_participation(v_participation_id);
    end loop;
  elsif tg_table_name = 'profiles' then
    for v_participation_id in
      select participation.id
      from public.fund_participations as participation
      join public.fund_projects as project on project.id = participation.project_id
      where project.owner_profile_id = new.id
    loop
      perform private.sync_fund_public_participation(v_participation_id);
    end loop;
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_public_project"("p_project_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_project public.fund_projects%rowtype;
  v_profile_slug text;
  v_current_value numeric(12, 2) := 0;
begin
  select * into v_project
  from public.fund_projects
  where id = p_project_id;

  if not found then
    delete from public.fund_public_projects where project_id = p_project_id;
    return;
  end if;

  select handle into v_profile_slug
  from public.profiles
  where id = v_project.owner_profile_id;

  if v_project.visibility <> 'public'
    or v_project.status = 'draft'
    or v_profile_slug is null
    or v_profile_slug !~ '^[a-z0-9][a-z0-9_-]{0,79}$' then
    delete from public.fund_public_projects where project_id = p_project_id;
    return;
  end if;

  if v_project.goal_type = 'amount' then
    select coalesce(sum(support.amount), 0)::numeric(12, 2)
    into v_current_value
    from public.fund_supports as support
    where support.project_id = p_project_id
      and support.record_status = 'valid'
      and support.payment_status = 'confirmed'
      and support.fulfillment_status <> 'cancelled';
  elsif v_project.goal_type = 'supporters' then
    select count(distinct coalesce(
      participation.supporter_user_id::text,
      nullif(lower(btrim(support.supporter_email)), ''),
      nullif(lower(btrim(support.supporter_name)), ''),
      support.id::text
    ))::numeric(12, 2)
    into v_current_value
    from public.fund_supports as support
    left join public.fund_participations as participation on participation.support_id = support.id
    where support.project_id = p_project_id
      and support.record_status = 'valid'
      and support.payment_status not in ('refunded', 'cancelled')
      and support.fulfillment_status <> 'cancelled';
  else
    select coalesce(sum(support.quantity), 0)::numeric(12, 2)
    into v_current_value
    from public.fund_supports as support
    where support.project_id = p_project_id
      and support.record_status = 'valid'
      and support.payment_status not in ('refunded', 'cancelled')
      and support.fulfillment_status <> 'cancelled';
  end if;

  insert into public.fund_public_projects (
    project_id, owner_profile_id, profile_slug, slug, title,
    short_description, description, project_type, campaign_type, stage, status,
    cover_image_url, goal_type, goal_value, current_value, display_amount,
    start_at, end_at, external_payment_url, external_application_url,
    why_now, audience, use_of_support, schedule, risk_notes,
    cancellation_policy, contact_note, published_at, completed_at,
    created_at, updated_at
  ) values (
    v_project.id, v_project.owner_profile_id, v_profile_slug, v_project.slug, v_project.title,
    v_project.short_description, v_project.description, v_project.project_type,
    v_project.campaign_type, v_project.stage, v_project.status,
    v_project.cover_image_url, v_project.goal_type,
    case when v_project.goal_type = 'amount' and not v_project.display_amount then 0 else v_project.goal_value end,
    case when v_project.goal_type = 'amount' and not v_project.display_amount then 0 else v_current_value end,
    v_project.display_amount, v_project.start_at, v_project.end_at,
    v_project.external_payment_url, v_project.external_application_url,
    v_project.why_now, v_project.audience, v_project.use_of_support,
    v_project.schedule, v_project.risk_notes, v_project.cancellation_policy,
    v_project.contact_note, coalesce(v_project.published_at, v_project.created_at),
    v_project.completed_at, v_project.created_at, v_project.updated_at
  )
  on conflict (project_id) do update set
    owner_profile_id = excluded.owner_profile_id,
    profile_slug = excluded.profile_slug,
    slug = excluded.slug,
    title = excluded.title,
    short_description = excluded.short_description,
    description = excluded.description,
    project_type = excluded.project_type,
    campaign_type = excluded.campaign_type,
    stage = excluded.stage,
    status = excluded.status,
    cover_image_url = excluded.cover_image_url,
    goal_type = excluded.goal_type,
    goal_value = excluded.goal_value,
    current_value = excluded.current_value,
    display_amount = excluded.display_amount,
    start_at = excluded.start_at,
    end_at = excluded.end_at,
    external_payment_url = excluded.external_payment_url,
    external_application_url = excluded.external_application_url,
    why_now = excluded.why_now,
    audience = excluded.audience,
    use_of_support = excluded.use_of_support,
    schedule = excluded.schedule,
    risk_notes = excluded.risk_notes,
    cancellation_policy = excluded.cancellation_policy,
    contact_note = excluded.contact_note,
    published_at = excluded.published_at,
    completed_at = excluded.completed_at,
    created_at = excluded.created_at,
    updated_at = excluded.updated_at;

  delete from public.fund_public_plans where project_id = p_project_id;

  insert into public.fund_public_plans (
    plan_id, project_id, title, description, image_url, plan_type, price,
    quantity_limit, per_person_limit, delivery_date, external_payment_url,
    external_application_url, status, sort_order, created_at, updated_at
  )
  select
    plan.id, plan.project_id, plan.title, plan.description, plan.image_url,
    plan.plan_type, case when v_project.display_amount then plan.price else null end,
    plan.quantity_limit, plan.per_person_limit, plan.delivery_date,
    plan.external_payment_url, plan.external_application_url, plan.status,
    plan.sort_order, plan.created_at, plan.updated_at
  from public.fund_plans as plan
  where plan.project_id = p_project_id
    and plan.status not in ('draft', 'hidden');
end;
$_$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_public_project_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_project_id uuid;
begin
  if tg_table_name = 'fund_projects' then
    perform private.sync_fund_public_project(new.id);
  elsif tg_table_name = 'fund_plans' or tg_table_name = 'fund_supports' then
    v_project_id := case when tg_op = 'DELETE' then old.project_id else new.project_id end;
    perform private.sync_fund_public_project(v_project_id);
  elsif tg_table_name = 'profiles' then
    for v_project_id in
      select id from public.fund_projects where owner_profile_id = new.id
    loop
      perform private.sync_fund_public_project(v_project_id);
    end loop;
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_public_update"("p_update_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_update public.fund_updates%rowtype;
begin
  select * into v_update
  from public.fund_updates
  where id = p_update_id;

  if not found
    or v_update.visibility <> 'public'
    or v_update.published_at is null
    or not exists (
      select 1 from public.fund_public_projects
      where project_id = v_update.project_id
    ) then
    delete from public.fund_public_updates where update_id = p_update_id;
    return;
  end if;

  insert into public.fund_public_updates (
    update_id, project_id, title, body, image_url,
    published_at, created_at, updated_at
  ) values (
    v_update.id, v_update.project_id, v_update.title, v_update.body,
    v_update.image_url, v_update.published_at,
    v_update.created_at, v_update.updated_at
  )
  on conflict (update_id) do update set
    project_id = excluded.project_id,
    title = excluded.title,
    body = excluded.body,
    image_url = excluded.image_url,
    published_at = excluded.published_at,
    created_at = excluded.created_at,
    updated_at = excluded.updated_at;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_public_update_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.sync_fund_public_update(
    case when tg_op = 'DELETE' then old.id else new.id end
  );
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_public_updates_after_parent_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_project_id uuid;
begin
  if tg_table_name = 'fund_projects' then
    perform private.sync_fund_public_updates_for_project(new.id);
  elsif tg_table_name = 'profiles' then
    for v_project_id in
      select id from public.fund_projects where owner_profile_id = new.id
    loop
      perform private.sync_fund_public_updates_for_project(v_project_id);
    end loop;
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_fund_public_updates_for_project"("p_project_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_update_id uuid;
begin
  if not exists (
    select 1 from public.fund_public_projects where project_id = p_project_id
  ) then
    delete from public.fund_public_updates where project_id = p_project_id;
    return;
  end if;

  for v_update_id in
    select id from public.fund_updates where project_id = p_project_id
  loop
    perform private.sync_fund_public_update(v_update_id);
  end loop;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."sync_mikke_media_usages"("p_app_key" "text", "p_entity_type" "text", "p_entity_id" "text", "p_asset_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_owner uuid := auth.uid();
begin
  if v_owner is null then raise exception 'MIKKE_MEDIA_AUTH_REQUIRED'; end if;
  if p_app_key !~ '^[a-z0-9-]{1,50}$'
    or p_entity_type !~ '^[a-z0-9_-]{1,50}$'
    or length(p_entity_id) < 1 or length(p_entity_id) > 200 then
    raise exception 'MIKKE_MEDIA_INVALID_USAGE';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_owner::text, 0));

  if exists (
    select requested.id
    from unnest(coalesce(p_asset_ids, array[]::uuid[])) requested(id)
    left join public.mikke_media_assets asset
      on asset.id = requested.id and asset.owner_id = v_owner and asset.status = 'active'
    where asset.id is null
  ) then
    raise exception 'MIKKE_MEDIA_ASSET_NOT_AVAILABLE';
  end if;

  delete from public.mikke_media_usages
  where owner_id = v_owner
    and app_key = p_app_key
    and entity_type = p_entity_type
    and entity_id = p_entity_id;

  insert into public.mikke_media_usages (asset_id, owner_id, app_key, entity_type, entity_id, field_key)
  select distinct asset_id, v_owner, p_app_key, p_entity_type, p_entity_id, 'document'
  from unnest(coalesce(p_asset_ids, array[]::uuid[])) asset_id;
end;
$_$;




CREATE OR REPLACE FUNCTION "private"."team_works_can_accept_invite"("target_invite_id" "uuid", "target_organization_id" "uuid", "target_user_id" "uuid", "target_role" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select target_user_id = (select auth.uid()) and exists (
    select 1
    from public.team_works_member_invites i
    join auth.users u on u.id = target_user_id
    where i.id = target_invite_id
      and i.organization_id = target_organization_id
      and i.role = target_role
      and i.status = 'pending'
      and i.expires_at > now()
      and lower(i.email) = lower(u.email)
  );
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_can_read_deliverable_object"("object_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select private.team_works_is_project_staff(private.team_works_storage_project_id(object_name))
    or exists (
      select 1
      from public.team_works_project_tasks t
      where t.project_id = private.team_works_storage_project_id(object_name)
        and t.source_local_id = private.team_works_storage_task_source_id(object_name)
        and t.assignee_member_id = private.team_works_current_project_member_id(t.project_id)
        and private.team_works_current_project_role(t.project_id) = 'worker'
    )
    or exists (
      select 1
      from public.team_works_project_deliverables d
      where d.project_id = private.team_works_storage_project_id(object_name)
        and d.source_local_id = private.team_works_storage_deliverable_source_id(object_name)
        and d.storage_path = object_name
        and d.client_visible
        and d.status in ('client_review', 'revision_requested', 'approved', 'delivered')
        and private.team_works_current_project_role(d.project_id) = 'client'
    );
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_can_read_form_attachment_object"("object_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select private.team_works_is_project_staff(private.team_works_storage_form_project_id(object_name))
    or private.team_works_can_write_form_attachment_object(object_name)
    or exists (
      select 1
      from public.team_works_project_forms f
      join public.team_works_form_submissions s
        on s.project_id = f.project_id
       and s.form_id = f.id
      where f.project_id = private.team_works_storage_form_project_id(object_name)
        and f.source_local_id = private.team_works_storage_form_source_id(object_name)
        and s.source_local_id = private.team_works_storage_form_submission_source_id(object_name)
        and s.submitted_by_member_id = private.team_works_current_project_member_id(f.project_id)
  );
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_can_write_deliverable_object"("object_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.team_works_project_tasks t
    where t.project_id = private.team_works_storage_project_id(object_name)
      and t.source_local_id = private.team_works_storage_task_source_id(object_name)
      and t.assignee_member_id = private.team_works_current_project_member_id(t.project_id)
      and private.team_works_current_project_role(t.project_id) = 'worker'
  );
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_can_write_form_attachment_object"("object_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.team_works_project_forms f
    where f.project_id = private.team_works_storage_form_project_id(object_name)
      and f.source_local_id = private.team_works_storage_form_source_id(object_name)
      and f.input_actor = private.team_works_current_project_role(f.project_id)
      and (
        f.input_actor <> 'client'
        or f.client_visible
      )
      and exists (
        select 1
        from jsonb_array_elements(f.fields) as field
        where field->>'id' = private.team_works_storage_form_field_id(object_name)
          and field->>'type' in ('file', 'image')
      )
  );
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_copy_shared_manual_to_projects"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  source_organization_id uuid;
begin
  if new.sharing_scope <> 'organization'
     or new.status <> 'active'
     or new.archived_at is not null then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and old.sharing_scope = 'organization'
     and old.status = new.status
     and old.archived_at is not distinct from new.archived_at then
    return new;
  end if;

  select p.organization_id
    into source_organization_id
  from public.team_works_projects p
  where p.id = new.project_id;

  insert into public.team_works_manuals (
    project_id, source_template_manual_id, no, title, body, material_type,
    material_url, questions, expressions, cautions, status, sharing_scope
  )
  select
    target.id, new.id, new.no, new.title, new.body, new.material_type,
    new.material_url, new.questions, new.expressions, new.cautions,
    'active', 'project'
  from public.team_works_projects target
  where target.organization_id = source_organization_id
    and target.id <> new.project_id
    and target.style = 'operations'
    and target.status = 'active'
    and target.archived_at is null
    and not exists (
      select 1 from public.team_works_manuals existing
      where existing.project_id = target.id
        and existing.archived_at is null
        and (existing.no = new.no or existing.source_template_manual_id = new.id)
    )
  on conflict (project_id, no) do nothing;

  return new;
end
$$;




COMMENT ON FUNCTION "private"."team_works_copy_shared_manual_to_projects"() IS 'Copies a newly organization-shared Team Works manual into existing active operations projects without keeping the copies synchronized.';



CREATE OR REPLACE FUNCTION "private"."team_works_copy_shared_manuals_to_new_project"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.style <> 'operations'
     or new.status <> 'active'
     or new.archived_at is not null then
    return new;
  end if;

  insert into public.team_works_manuals (
    project_id, source_template_manual_id, no, title, body, material_type,
    material_url, questions, expressions, cautions, status, sharing_scope
  )
  select
    new.id, source.id, source.no, source.title, source.body,
    source.material_type, source.material_url, source.questions,
    source.expressions, source.cautions, 'active', 'project'
  from (
    select distinct on (manual.no) manual.*
    from public.team_works_manuals manual
    join public.team_works_projects source_project on source_project.id = manual.project_id
    where source_project.organization_id = new.organization_id
      and source_project.id <> new.id
      and manual.sharing_scope = 'organization'
      and manual.status = 'active'
      and manual.archived_at is null
    order by manual.no, manual.updated_at desc, manual.id
  ) source
  on conflict (project_id, no) do nothing;

  return new;
end
$$;




COMMENT ON FUNCTION "private"."team_works_copy_shared_manuals_to_new_project"() IS 'Seeds a new operations project with independent copies of the organization shared manual masters.';



CREATE OR REPLACE FUNCTION "private"."team_works_current_member_id"("target_organization_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select m.id from public.team_works_organization_members m
  where m.organization_id = target_organization_id
    and m.user_id = (select auth.uid()) and m.status = 'active'
  limit 1;
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_current_project_member_id"("target_project_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select pm.organization_member_id
  from public.team_works_project_members pm
  join public.team_works_organization_members m on m.id = pm.organization_member_id
  where pm.project_id = target_project_id
    and m.user_id = (select auth.uid()) and m.status = 'active'
  limit 1;
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_current_project_role"("target_project_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select pm.project_role
  from public.team_works_project_members pm
  join public.team_works_organization_members m on m.id = pm.organization_member_id
  where pm.project_id = target_project_id and m.user_id = (select auth.uid()) and m.status = 'active'
  limit 1;
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_guard_worker_deliverable_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if private.team_works_current_project_role(new.project_id) <> 'worker' then
    return new;
  end if;

  if new.project_id is distinct from old.project_id
    or new.task_id is distinct from old.task_id
    or new.source_local_id is distinct from old.source_local_id
    or new.title is distinct from old.title
    or new.deliverable_type is distinct from old.deliverable_type
    or new.client_visible is distinct from old.client_visible
    or new.reviewed_by_member_id is distinct from old.reviewed_by_member_id then
    raise exception 'worker cannot change managed deliverable fields';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_has_project_role"("target_project_id" "uuid", "target_role" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.team_works_project_members pm
    join public.team_works_organization_members m on m.id = pm.organization_member_id
    where pm.project_id = target_project_id
      and pm.project_role = target_role
      and m.user_id = (select auth.uid())
      and m.status = 'active'
  );
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_is_assigned_worker_for_deliverable"("target_project_id" "uuid", "target_task_id" "uuid", "target_submitted_by_member_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select private.team_works_current_project_role(target_project_id) = 'worker'
    and target_submitted_by_member_id = private.team_works_current_project_member_id(target_project_id)
    and exists (
      select 1
      from public.team_works_project_tasks t
      where t.id = target_task_id
        and t.project_id = target_project_id
        and t.assignee_member_id = private.team_works_current_project_member_id(target_project_id)
    );
$$;




CREATE OR REPLACE FUNCTION "private"."team_works_is_org_staff"("target_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.team_works_organizations o
    where o.id = target_organization_id and o.owner_user_id = (select auth.uid())
  ) or exists (
    select 1 from public.team_works_organization_members m
    where m.organization_id = target_organization_id
      and m.user_id = (select auth.uid()) and m.status = 'active'
      and m.role in ('owner', 'manager')
