CREATE OR REPLACE FUNCTION "private"."team_works_is_own_project_member_id"("target_project_id" "uuid", "target_member_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.team_works_project_members pm
    join public.team_works_organization_members m on m.id = pm.organization_member_id
    where pm.project_id = target_project_id
      and pm.organization_member_id = target_member_id
      and m.user_id = (select auth.uid())
      and m.status = 'active'
