CREATE OR REPLACE FUNCTION "public"."academy_can_approve_program_progress"("p_headquarters_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ select academy_owns_hq(p_headquarters_id) or exists(select 1 from academy_memberships m join academy_role_definitions r on r.id=m.role_definition_id join profiles p on p.id=m.member_profile_id where m.headquarters_id=p_headquarters_id and m.status='active' and p.user_id=(select auth.uid()) and coalesce((r.permission_flags->>'approve_progress')::boolean,false)); $$;




CREATE TABLE IF NOT EXISTS "public"."academy_class_instructor_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "headquarters_id" "uuid" NOT NULL,
    "class_id" "uuid" NOT NULL,
    "instructor_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'requested'::"text" NOT NULL,
    "request_note" "text",
    "response_note" "text",
    "respond_by" timestamp with time zone,
    "requested_by_user_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "responded_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "academy_class_instructor_requests_status_check" CHECK (("status" = ANY (ARRAY['requested'::"text", 'accepted'::"text", 'declined'::"text", 'cancelled'::"text"])))
);




CREATE OR REPLACE FUNCTION "public"."academy_cancel_class_instructor_request"("p_request_id" "uuid") RETURNS "public"."academy_class_instructor_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_request public.academy_class_instructor_requests%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'Authentication required';
  end if;

  select *
  into v_request
  from public.academy_class_instructor_requests
  where id = p_request_id
  for update;

  if v_request.id is null then
    raise exception 'Instructor request not found';
  end if;

  if not private.academy_can_manage_headquarters(v_request.headquarters_id) then
    raise exception 'Permission denied';
  end if;

  if v_request.status <> 'requested' then
    return v_request;
  end if;

  update public.academy_class_instructor_requests
  set status = 'cancelled',
      responded_at = now(),
      updated_at = now()
  where id = v_request.id
  returning * into v_request;

  return v_request;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_complete_program_step"("p_assignment_id" "uuid", "p_step_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_profile uuid;
  v_program uuid;
  v_program_version uuid;
  v_snapshot jsonb;
  v_step jsonb;
  v_self boolean;
  v_required boolean;
  v_current_section_sort integer;
  v_current_step_sort integer;
  v_status text;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select id
  into v_profile
  from public.profiles
  where user_id = (select auth.uid())
  limit 1;

  select assignment.program_id, assignment.program_version_id
  into v_program, v_program_version
  from public.academy_program_assignments assignment
  where assignment.id = p_assignment_id
    and assignment.learner_profile_id = v_profile
    and assignment.status = 'active';

  if v_program is null
    or not private.academy_profile_has_program_access(v_profile, v_program)
  then
    raise exception 'Assignment unavailable';
  end if;

  if v_program_version is null then
    select step.self_completion_allowed, step.requires_previous
    into v_self, v_required
    from public.academy_program_steps step
    join public.academy_program_sections section
      on section.id = step.section_id
    where step.id = p_step_id
      and section.program_id = v_program;

    if not found then
      raise exception 'Step unavailable';
    end if;

    if v_required and exists (
      select 1
      from public.academy_program_steps previous
      join public.academy_program_sections previous_section
        on previous_section.id = previous.section_id
      join public.academy_program_steps current_step
        on current_step.id = p_step_id
      join public.academy_program_sections current_section
        on current_section.id = current_step.section_id
      where previous_section.program_id = v_program
        and (
          previous_section.sort_order < current_section.sort_order
          or (
            previous_section.sort_order = current_section.sort_order
            and previous.sort_order < current_step.sort_order
          )
        )
        and not exists (
          select 1
          from public.academy_step_progress progress
          where progress.assignment_id = p_assignment_id
            and progress.step_id = previous.id
            and progress.status = 'completed'
        )
    ) then
      raise exception 'Previous step incomplete';
    end if;
  else
    select version.content_snapshot
    into v_snapshot
    from public.academy_program_versions version
    where version.id = v_program_version
      and version.program_id = v_program;

    select
      step.value,
      (section.value ->> 'sort_order')::integer,
      (step.value ->> 'sort_order')::integer
    into
      v_step,
      v_current_section_sort,
      v_current_step_sort
    from jsonb_array_elements(v_snapshot -> 'sections') section(value)
    cross join lateral jsonb_array_elements(section.value -> 'steps') step(value)
    where (step.value ->> 'id')::uuid = p_step_id;

    if v_step is null then
      raise exception 'Step unavailable';
    end if;

    v_self := (v_step ->> 'self_completion_allowed')::boolean;
    v_required := (v_step ->> 'requires_previous')::boolean;

    if v_required and exists (
      select 1
      from jsonb_array_elements(v_snapshot -> 'sections') previous_section(value)
      cross join lateral jsonb_array_elements(previous_section.value -> 'steps') previous_step(value)
      where (
        (previous_section.value ->> 'sort_order')::integer < v_current_section_sort
        or (
          (previous_section.value ->> 'sort_order')::integer = v_current_section_sort
          and (previous_step.value ->> 'sort_order')::integer < v_current_step_sort
        )
      )
      and not exists (
        select 1
        from public.academy_step_progress progress
        where progress.assignment_id = p_assignment_id
          and progress.step_id = (previous_step.value ->> 'id')::uuid
          and progress.status = 'completed'
      )
    ) then
      raise exception 'Previous step incomplete';
    end if;
  end if;

  v_status := case
    when v_self then 'completed'
    else 'awaiting_approval'
  end;

  insert into public.academy_step_progress(
    assignment_id,
    step_id,
    status,
    completed_at
  )
  values (
    p_assignment_id,
    p_step_id,
    v_status,
    case when v_self then now() else null end
  )
  on conflict (assignment_id, step_id)
  do update set
    status = excluded.status,
    completed_at = excluded.completed_at,
    updated_at = now();

  return v_status;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_confirm_application_enrollment"("p_application_id" "uuid", "p_class_id" "uuid", "p_learner_profile_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_headquarters_id uuid;
  v_course_id uuid;
  v_program_id uuid;
  v_starts_at timestamptz;
  v_format text;
  v_application_payment_status text;
  v_application_course_id uuid;
  v_application_headquarters_id uuid;
  v_learner_user_id uuid;
  v_enrollment_id uuid;
begin
  select
    class_record.headquarters_id,
    class_record.course_id,
    class_record.program_id,
    class_record.starts_at,
    class_record.format
  into
    v_headquarters_id,
    v_course_id,
    v_program_id,
    v_starts_at,
    v_format
  from public.academy_classes class_record
  where class_record.id = p_class_id
    and class_record.status <> 'cancelled'
    and public.academy_owns_hq(class_record.headquarters_id);

  if v_headquarters_id is null then
    raise exception 'Class not found or permission denied';
  end if;

  select
    application.payment_status,
    application.course_id,
    application.headquarters_id
  into
    v_application_payment_status,
    v_application_course_id,
    v_application_headquarters_id
  from public.academy_applications application
  where application.id = p_application_id
    and application.headquarters_id = v_headquarters_id;

  if v_application_headquarters_id is null then
    raise exception 'Application not found or permission denied';
  end if;

  if v_application_course_id <> v_course_id then
    raise exception 'Application and class course must match';
  end if;

  if v_application_payment_status not in ('paid', 'not_required') then
    raise exception 'Payment confirmation is required before enrollment';
  end if;

  select profile.user_id
  into v_learner_user_id
  from public.profiles profile
  where profile.id = p_learner_profile_id;

  if v_learner_user_id is null then
    raise exception 'Learner Mikke ID not found';
  end if;

  select enrollment.id
  into v_enrollment_id
  from public.academy_enrollments enrollment
  where enrollment.application_id = p_application_id;

  if v_enrollment_id is null then
    v_enrollment_id := gen_random_uuid();
    insert into public.academy_enrollments(
      id,
      class_id,
      application_id,
      learner_profile_id,
      status
    )
    values (
      v_enrollment_id,
      p_class_id,
      p_application_id,
      p_learner_profile_id,
      'active'
    );
  else
    update public.academy_enrollments
    set
      class_id = p_class_id,
      learner_profile_id = p_learner_profile_id,
      status = 'active',
      completed_at = null,
      updated_at = now()
    where id = v_enrollment_id;
  end if;

  insert into public.academy_program_assignments(
    headquarters_id,
    program_id,
    learner_profile_id,
    enrollment_id,
    status
  )
  values (
    v_headquarters_id,
    v_program_id,
    p_learner_profile_id,
    v_enrollment_id,
    'active'
  )
  on conflict (program_id, learner_profile_id)
  do update set
    enrollment_id = excluded.enrollment_id,
    status = 'active',
    updated_at = now();

  update public.academy_applications
  set
    user_id = v_learner_user_id,
    status = 'scheduled',
    event_date = coalesce(event_date, v_starts_at::date),
    format = coalesce(format, v_format),
    updated_at = now()
  where id = p_application_id
    and headquarters_id = v_headquarters_id;

  return v_enrollment_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_create_procurement_order"("p_headquarters_id" "uuid", "p_product_id" "uuid", "p_quantity" integer, "p_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_profile_id uuid;
  v_product_name text;
  v_unit_price integer;
  v_order_id uuid;
begin
  if (select auth.uid()) is null then raise exception 'Authentication required'; end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 10000 then raise exception 'Invalid quantity'; end if;
  select id into v_profile_id from public.profiles where user_id = (select auth.uid()) order by created_at limit 1;
  if v_profile_id is null then raise exception 'Profile not found'; end if;
  select product.name, product.price_yen into v_product_name, v_unit_price
  from public.academy_procurement_products as product
  where product.id = p_product_id and product.headquarters_id = p_headquarters_id and product.is_active
    and exists (select 1 from public.academy_memberships as membership join public.academy_product_role_access as access on access.role_definition_id = membership.role_definition_id where membership.headquarters_id = p_headquarters_id and membership.member_profile_id = v_profile_id and membership.status = 'active' and access.product_id = product.id);
  if not found then raise exception 'Product is unavailable'; end if;
  insert into public.academy_procurement_orders (headquarters_id, requester_profile_id, status, note, total_yen) values (p_headquarters_id, v_profile_id, 'submitted', nullif(trim(p_note), ''), v_unit_price * p_quantity) returning id into v_order_id;
  insert into public.academy_procurement_order_items (order_id, product_id, product_name, unit_price_yen, quantity) values (v_order_id, p_product_id, v_product_name, v_unit_price, p_quantity);
  insert into public.academy_order_status_history (order_id, status, changed_by_user_id) values (v_order_id, 'submitted', (select auth.uid()));
  return v_order_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_create_program_license"("p_licensee_headquarters_id" "uuid", "p_program_id" "uuid", "p_program_version_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select private.academy_create_program_license(
    p_licensee_headquarters_id,
    p_program_id,
    p_program_version_id,
    p_note
  );
$$;




CREATE OR REPLACE FUNCTION "public"."academy_find_profile_by_login_email"("p_headquarters_id" "uuid", "p_login_email" "text") RETURNS TABLE("id" "uuid", "user_id" "uuid", "display_name" "text", "handle" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  if (select auth.uid()) is null then raise exception 'Authentication required'; end if;
  if not public.academy_owns_hq(p_headquarters_id) then raise exception 'Academy owner access required'; end if;
  return query
    select profile.id, profile.user_id, profile.display_name, profile.handle
    from public.profiles as profile
    join auth.users as auth_user on auth_user.id = profile.user_id
    where lower(auth_user.email) = lower(trim(p_login_email))
    order by profile.created_at
    limit 1;
end;
$$;




