    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select private.academy_headquarters_role(p_headquarters_id, (select auth.uid()));
$$;




CREATE TABLE IF NOT EXISTS "public"."academy_headquarters" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_user_id" "uuid" NOT NULL,
    "owner_profile_id" "uuid",
    "name" "text" NOT NULL,
    "handle" "text" NOT NULL,
    "tagline" "text",
    "logo_url" "text",
    "main_color" "text",
    "contact_email" "text",
    "plan" "text" DEFAULT 'small'::"text" NOT NULL,
    "plan_started_at" "date",
    "default_payment_note" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "hero_image_url" "text",
    "front_message" "text",
    "renewal_period_months" integer,
    "front_blocks" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "next_instructor_number" integer,
    CONSTRAINT "academy_headquarters_handle_format" CHECK (("handle" ~ '^[a-z0-9_][a-z0-9_-]{2,29}$'::"text")),
    CONSTRAINT "academy_headquarters_next_instructor_number_check" CHECK ((("next_instructor_number" IS NULL) OR ("next_instructor_number" > 0))),
    CONSTRAINT "academy_headquarters_plan_check" CHECK (("plan" = ANY (ARRAY['small'::"text", 'standard'::"text", 'growth'::"text", 'pro'::"text", 'paused'::"text"])))
);




COMMENT ON COLUMN "public"."academy_headquarters"."renewal_period_months" IS '認定講師の更新周期（月数）。nullなら更新制度を使わない団体。講師登録時の認定日入力・更新完了操作の自動計算に使う。';



COMMENT ON COLUMN "public"."academy_headquarters"."front_blocks" IS 'フロントページの自由ブロック（ビルダー式）';



