CREATE OR REPLACE FUNCTION "public"."academy_grant_program_subscription"("p_product_id" "uuid", "p_member_profile_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_headquarters_id uuid;
  v_subscription_id uuid;
  v_now timestamptz := now();
begin
  select product.headquarters_id
  into v_headquarters_id
  from public.academy_subscription_products product
  where product.id = p_product_id
    and public.academy_owns_hq(product.headquarters_id);

  if v_headquarters_id is null then
    raise exception 'Subscription product not found or permission denied';
  end if;

  if not exists (
    select 1
    from public.academy_memberships membership
    where membership.headquarters_id = v_headquarters_id
      and membership.member_profile_id = p_member_profile_id
      and membership.status = 'active'
  ) then
    raise exception 'Active Academy member required';
  end if;

  insert into public.academy_subscriptions(
    subscription_product_id,
    member_profile_id,
    status,
    starts_at,
    ends_at,
    updated_at
  )
  values (
    p_product_id,
    p_member_profile_id,
    'active',
    v_now,
    null,
    v_now
  )
  on conflict (subscription_product_id, member_profile_id)
  do update set
    status = 'active',
    starts_at = v_now,
    ends_at = null,
    updated_at = v_now
  returning id into v_subscription_id;

  insert into public.academy_entitlement_grants(
    subscription_id,
    member_profile_id,
    program_id,
    status,
    starts_at,
    ends_at
  )
  select
    v_subscription_id,
    p_member_profile_id,
    mapping.program_id,
    'active',
    v_now,
    null
  from public.academy_subscription_product_programs mapping
  where mapping.subscription_product_id = p_product_id
  on conflict (subscription_id, program_id)
  do update set
    status = 'active',
    starts_at = v_now,
    ends_at = null,
    updated_at = v_now;

  insert into public.academy_program_assignments(
    headquarters_id,
    program_id,
    learner_profile_id,
    status
  )
  select
    v_headquarters_id,
    mapping.program_id,
    p_member_profile_id,
    'active'
  from public.academy_subscription_product_programs mapping
  where mapping.subscription_product_id = p_product_id
  on conflict (program_id, learner_profile_id)
  do update set
    status = 'active',
    updated_at = now();

  return v_subscription_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_guard_instructor_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.academy_owns_hq(new.headquarters_id) then
    new.headquarters_id  := old.headquarters_id;
    new.course_id        := old.course_id;
    new.profile_id       := old.profile_id;
    new.user_id          := old.user_id;
    new.instructor_number:= old.instructor_number;
    new.certified_at     := old.certified_at;
    new.renewal_due      := old.renewal_due;
    new.is_certified     := old.is_certified;
    new.is_active        := old.is_active;
    new.status           := old.status;
    new.memo             := old.memo;
  end if;
  return new;
end;
$$;




CREATE TABLE IF NOT EXISTS "public"."academy_headquarters_invitations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "headquarters_id" "uuid" NOT NULL,
    "target_profile_id" "uuid" NOT NULL,
    "role" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "invited_by_user_id" "uuid" NOT NULL,
    "responded_at" timestamp with time zone,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '14 days'::interval) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "academy_headquarters_invitations_role_check" CHECK (("role" = ANY (ARRAY['administrator'::"text", 'course_editor'::"text"]))),
    CONSTRAINT "academy_headquarters_invitations_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'declined'::"text", 'cancelled'::"text"])))
);




CREATE OR REPLACE FUNCTION "public"."academy_invite_headquarters_member"("p_headquarters_id" "uuid", "p_mikke_id" "text", "p_role" "text") RETURNS "public"."academy_headquarters_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_target public.profiles%rowtype;
  v_invitation public.academy_headquarters_invitations%rowtype;
begin
  if v_actor is null then
    raise exception 'academy_headquarters_forbidden';
  end if;
  if p_role not in ('administrator', 'course_editor') then
    raise exception 'academy_headquarters_invalid_role';
  end if;

  perform 1
  from public.academy_headquarters
  where id = p_headquarters_id
  for update;

  if not found or not private.academy_can_manage_headquarters(p_headquarters_id) then
    raise exception 'academy_headquarters_forbidden';
  end if;

  select p.* into v_target
  from public.profiles p
  where lower(p.handle) = lower(trim(p_mikke_id))
  limit 1;

  if v_target.id is null then
    raise exception 'academy_headquarters_member_not_found';
  end if;
  if v_target.user_id = v_actor then
    raise exception 'academy_headquarters_cannot_invite_self';
  end if;
  if exists (
    select 1
    from public.academy_headquarters_members member
    where member.headquarters_id = p_headquarters_id
      and member.member_profile_id = v_target.id
      and member.status = 'active'
  ) then
    raise exception 'academy_headquarters_member_already_active';
  end if;

  insert into public.academy_headquarters_invitations (
    headquarters_id,
    target_profile_id,
    role,
    status,
    invited_by_user_id,
    responded_at,
    expires_at,
    updated_at
  )
  values (
    p_headquarters_id,
    v_target.id,
    p_role,
    'pending',
    v_actor,
    null,
    now() + interval '14 days',
    now()
  )
  on conflict (headquarters_id, target_profile_id)
  do update set
    role = excluded.role,
    status = 'pending',
    invited_by_user_id = excluded.invited_by_user_id,
    responded_at = null,
    expires_at = excluded.expires_at,
    updated_at = now()
  returning * into v_invitation;

  return v_invitation;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_is_course_instructor"("p_course_id" "uuid", "p_require_active" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1 from public.academy_instructors i
    where i.course_id = p_course_id
      and i.user_id = auth.uid()
      and (p_require_active = false or i.is_active = true)
  );
$$;




CREATE OR REPLACE FUNCTION "public"."academy_is_instructor_self"("p_instructor_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1 from public.academy_instructors i
    where i.id = p_instructor_id
      and i.user_id = auth.uid()
  );
$$;




CREATE OR REPLACE FUNCTION "public"."academy_link_subscription_product_program"("p_product_id" "uuid", "p_program_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_headquarters_id uuid;
begin
  select product.headquarters_id
  into v_headquarters_id
  from public.academy_subscription_products product
  join public.academy_programs program
    on program.id = p_program_id
   and program.headquarters_id = product.headquarters_id
  where product.id = p_product_id
    and public.academy_owns_hq(product.headquarters_id);

  if v_headquarters_id is null then
    raise exception 'Product and program must belong to the owned Academy';
  end if;

  insert into public.academy_subscription_product_programs(
    subscription_product_id,
    program_id
  )
  values (p_product_id, p_program_id)
  on conflict do nothing;

  insert into public.academy_entitlement_grants(
    subscription_id,
    member_profile_id,
    program_id,
    status,
    starts_at,
    ends_at
  )
  select
    subscription.id,
    subscription.member_profile_id,
    p_program_id,
    case
      when subscription.status = 'active' then 'active'
      when subscription.status = 'paused' then 'paused'
      else 'revoked'
    end,
    subscription.starts_at,
    subscription.ends_at
  from public.academy_subscriptions subscription
  where subscription.subscription_product_id = p_product_id
  on conflict (subscription_id, program_id)
  do update set
    status = excluded.status,
    starts_at = excluded.starts_at,
    ends_at = excluded.ends_at,
    updated_at = now();

  insert into public.academy_program_assignments(
    headquarters_id,
    program_id,
    learner_profile_id,
    status
  )
  select
    v_headquarters_id,
    p_program_id,
    subscription.member_profile_id,
    'active'
  from public.academy_subscriptions subscription
  where subscription.subscription_product_id = p_product_id
  on conflict (program_id, learner_profile_id)
  do update set updated_at = now();
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_list_application_notifications"("p_application_id" "uuid") RETURNS TABLE("recipient_kind" "text", "status" "text", "last_error" "text", "sent_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select n.recipient_kind, n.status, n.last_error, n.sent_at, n.updated_at
  from public.academy_application_notifications n
  join public.academy_applications a on a.id = n.application_id
  where n.application_id = p_application_id
    and private.academy_can_manage_headquarters(a.headquarters_id)
  order by n.recipient_kind;
$$;




