CREATE OR REPLACE FUNCTION "public"."academy_list_pending_step_approvals"() RETURNS TABLE("progress_id" "uuid", "learner_name" "text", "learner_handle" "text", "program_title" "text", "step_title" "text", "requested_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  return query
  select
    progress.id,
    learner.display_name,
    learner.handle,
    program.title,
    step.title,
    progress.updated_at
  from public.academy_step_progress progress
  join public.academy_program_assignments assignment
    on assignment.id = progress.assignment_id
  join public.academy_programs program
    on program.id = assignment.program_id
  join public.academy_program_steps step
    on step.id = progress.step_id
  join public.profiles learner
    on learner.id = assignment.learner_profile_id
  where progress.status = 'awaiting_approval'
    and public.academy_can_approve_program_progress(assignment.headquarters_id)
    and not exists (
      select 1
      from public.academy_step_submissions submission
      where submission.assignment_id = progress.assignment_id
        and submission.step_id = progress.step_id
        and submission.status = 'submitted'
    )
  order by progress.updated_at;
end;
$$;




