    "instructor_number" "text",
    "certified_at" "date",
    "renewal_due" "date",
    "is_certified" boolean DEFAULT false NOT NULL,
    "is_active" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "memo" "text",
    "business_name" "text",
    "area" "text",
    "online_available" boolean DEFAULT false NOT NULL,
    "instagram_url" "text",
    "self_intro" "text",
    "message" "text",
    "available_note" "text",
    "accepts_applications" boolean DEFAULT false NOT NULL,
    "is_listed" boolean DEFAULT false NOT NULL,
    "display_on_story" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "photo_url" "text",
    "payment_method_note" "text",
    "payment_url" "text",
    "payment_provider" "text" DEFAULT 'manual'::"text" NOT NULL,
    CONSTRAINT "academy_instructors_payment_provider_check" CHECK (("payment_provider" = ANY (ARRAY['manual'::"text", 'stripe'::"text", 'square'::"text", 'paycas'::"text"]))),
    CONSTRAINT "academy_instructors_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'dormant'::"text", 'suspended'::"text", 'reapplying'::"text"])))
