CREATE OR REPLACE FUNCTION "public"."academy_promote_certified_application"("p_application_id" "uuid", "p_profile_id" "uuid") RETURNS "public"."academy_instructors"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_application public.academy_applications%rowtype;
  v_profile public.profiles%rowtype;
  v_headquarters public.academy_headquarters%rowtype;
  v_instructor public.academy_instructors%rowtype;
  v_number text;
begin
  select * into v_application
  from public.academy_applications a
  where a.id = p_application_id
  for update;

  if v_application.id is null then
    raise exception 'academy_application_not_found';
  end if;
  if not private.academy_can_manage_headquarters(v_application.headquarters_id) then
    raise exception 'academy_headquarters_forbidden';
  end if;
  if v_application.certification_status <> 'certified' then
    raise exception 'academy_application_not_certified';
  end if;

  select * into v_profile
  from public.profiles p
  where p.id = p_profile_id;
  if v_profile.id is null or v_profile.user_id is null then
    raise exception 'academy_profile_not_available';
  end if;

  select * into v_instructor
  from public.academy_instructors i
  where i.course_id = v_application.course_id
    and i.profile_id = v_profile.id
  limit 1;

  if v_instructor.id is not null then
    update public.academy_applications
    set status = 'instructor_added', updated_at = now()
    where id = v_application.id;
    return v_instructor;
  end if;

  select i.instructor_number into v_number
  from public.academy_instructors i
  where i.headquarters_id = v_application.headquarters_id
    and i.profile_id = v_profile.id
    and i.instructor_number is not null
  order by i.created_at asc
  limit 1;

  select * into v_headquarters
  from public.academy_headquarters h
  where h.id = v_application.headquarters_id
  for update;

  if v_number is null then
    v_number := coalesce(v_headquarters.next_instructor_number, 1)::text;
    update public.academy_headquarters
    set next_instructor_number = coalesce(next_instructor_number, 1) + 1,
        updated_at = now()
    where id = v_headquarters.id;
  end if;

  insert into public.academy_instructors (
    headquarters_id,
    course_id,
    profile_id,
    user_id,
    instructor_number,
    certified_at,
    renewal_due,
    is_certified,
    is_active,
    is_listed,
    accepts_applications
  ) values (
    v_application.headquarters_id,
    v_application.course_id,
    v_profile.id,
    v_profile.user_id,
    v_number,
    current_date,
    case
      when v_headquarters.renewal_period_months is null then null
      else current_date + make_interval(months => v_headquarters.renewal_period_months)
    end,
    true,
    true,
    false,
    false
  ) returning * into v_instructor;

  update public.academy_applications
  set status = 'instructor_added', updated_at = now()
  where id = v_application.id;

  return v_instructor;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_publish_program_version"("p_program_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_program public.academy_programs%rowtype;
  v_version_number integer;
  v_content_snapshot jsonb;
  v_version_id uuid;
begin
  select program.*
  into v_program
  from public.academy_programs program
  where program.id = p_program_id
    and public.academy_owns_hq(program.headquarters_id)
  for update;

  if v_program.id is null then
    raise exception 'Program not found or permission denied';
  end if;

  if not exists (
    select 1
    from public.academy_program_sections section
    join public.academy_program_steps step
      on step.section_id = section.id
    where section.program_id = p_program_id
  ) then
    raise exception 'Add at least one section and step before publishing';
  end if;

  select coalesce(max(version.version_number), 0) + 1
  into v_version_number
  from public.academy_program_versions version
  where version.program_id = p_program_id;

  select jsonb_build_object(
    'sections',
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', section.id,
          'program_id', section.program_id,
          'title', section.title,
          'sort_order', section.sort_order,
          'created_at', section.created_at,
          'updated_at', section.updated_at,
          'steps', coalesce(
            (
              select jsonb_agg(
                jsonb_build_object(
                  'id', step.id,
                  'section_id', step.section_id,
                  'step_type', step.step_type,
                  'title', step.title,
                  'content', step.content,
                  'external_url', step.external_url,
                  'sort_order', step.sort_order,
                  'requires_previous', step.requires_previous,
                  'self_completion_allowed', step.self_completion_allowed,
                  'created_at', step.created_at,
                  'updated_at', step.updated_at
                )
                order by step.sort_order, step.created_at, step.id
              )
              from public.academy_program_steps step
              where step.section_id = section.id
            ),
            '[]'::jsonb
          )
        )
        order by section.sort_order, section.created_at, section.id
      ),
      '[]'::jsonb
    )
  )
  into v_content_snapshot
  from public.academy_program_sections section
  where section.program_id = p_program_id;

  v_version_id := gen_random_uuid();

  insert into public.academy_program_versions(
    id,
    program_id,
    version_number,
    title,
    description,
    content_snapshot,
    published_by_user_id
  )
  values (
    v_version_id,
    p_program_id,
    v_version_number,
    v_program.title,
    v_program.description,
    v_content_snapshot,
    (select auth.uid())
  );

  update public.academy_programs
  set status = 'published', updated_at = now()
  where id = p_program_id;

  return v_version_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_record_payment_event"("p_provider" "text", "p_provider_event_id" "text", "p_application_id" "uuid", "p_provider_payment_id" "text", "p_amount" numeric, "p_currency" "text", "p_is_test" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_application public.academy_applications%rowtype;
begin
  if p_provider not in ('stripe', 'square') then
    raise exception 'academy_payment_provider_invalid';
  end if;

  select * into v_application
  from public.academy_applications a
  where a.id = p_application_id
  for update;

  if v_application.id is null then
    raise exception 'academy_application_not_found';
  end if;
  if v_application.payment_provider <> p_provider then
    raise exception 'academy_payment_provider_mismatch';
  end if;
  if upper(coalesce(p_currency, '')) <> 'JPY' or p_amount <> v_application.price then
    raise exception 'academy_payment_amount_mismatch';
  end if;

  insert into public.academy_payment_events (
    provider,
    provider_event_id,
    application_id,
    provider_payment_id,
    amount,
    currency,
    is_test
  ) values (
    p_provider,
    p_provider_event_id,
    v_application.id,
    nullif(trim(coalesce(p_provider_payment_id, '')), ''),
    p_amount,
    upper(p_currency),
    coalesce(p_is_test, true)
  ) on conflict (provider, provider_event_id) do nothing;

  if not found then
    return false;
  end if;

  update public.academy_applications
  set payment_status = 'paid',
      status = case when status in ('received', 'awaiting_payment') then 'paid' else status end,
      provider_payment_id = nullif(trim(coalesce(p_provider_payment_id, '')), ''),
      paid_at = coalesce(paid_at, now()),
      updated_at = now()
  where id = v_application.id;

  return true;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_request_class_instructor"("p_headquarters_id" "uuid", "p_class_id" "uuid", "p_instructor_id" "uuid", "p_request_note" "text" DEFAULT NULL::"text", "p_respond_by" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."academy_class_instructor_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_request public.academy_class_instructor_requests%rowtype;
begin
  if v_actor is null or not private.academy_can_manage_headquarters(p_headquarters_id) then
    raise exception 'academy_class_instructor_request_forbidden';
  end if;
  if not private.academy_class_instructor_request_scope_valid(
    p_headquarters_id,
    p_class_id,
    p_instructor_id
  ) then
    raise exception 'academy_class_instructor_request_scope_invalid';
  end if;

  insert into public.academy_class_instructor_requests (
    headquarters_id,
    class_id,
    instructor_id,
    status,
    request_note,
    response_note,
    respond_by,
    requested_by_user_id,
    requested_at,
    responded_at,
    updated_at
  ) values (
    p_headquarters_id,
    p_class_id,
    p_instructor_id,
    'requested',
    nullif(trim(p_request_note), ''),
    null,
    p_respond_by,
    v_actor,
    now(),
    null,
    now()
  )
  returning * into v_request;

  return v_request;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_respond_class_instructor_request"("p_request_id" "uuid", "p_status" "text", "p_response_note" "text" DEFAULT NULL::"text") RETURNS "public"."academy_class_instructor_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_class_id uuid;
  v_request public.academy_class_instructor_requests%rowtype;
  v_next public.academy_class_instructor_requests%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'Authentication required';
  end if;

  if p_status not in ('accepted', 'declined') then
    raise exception 'Unsupported response status';
  end if;

  select class_id
  into v_class_id
  from public.academy_class_instructor_requests
  where id = p_request_id;

  if v_class_id is null then
    raise exception 'Request not found';
  end if;

  perform 1
  from public.academy_classes
  where id = v_class_id
  for update;

  select *
  into v_request
  from public.academy_class_instructor_requests
  where id = p_request_id
  for update;

  if v_request.id is null then
    raise exception 'Request not found';
  end if;

  if v_request.status <> 'requested' then
    raise exception 'Request is already closed';
  end if;

  if not exists (
    select 1
    from public.academy_instructors instructor
    where instructor.id = v_request.instructor_id
      and instructor.user_id = v_actor_user_id
      and instructor.is_active = true
  ) then
    raise exception 'Permission denied';
  end if;

  if not private.academy_class_instructor_request_scope_valid(
    v_request.headquarters_id,
    v_request.class_id,
    v_request.instructor_id
  ) then
    raise exception 'Request scope is no longer valid';
  end if;

  update public.academy_class_instructor_requests
  set status = p_status,
      response_note = nullif(trim(coalesce(p_response_note, '')), ''),
      responded_at = now(),
      updated_at = now()
  where id = p_request_id
  returning * into v_next;

  if p_status = 'accepted' then
    update public.academy_classes
    set instructor_id = v_request.instructor_id,
        updated_at = now()
    where id = v_request.class_id
      and headquarters_id = v_request.headquarters_id;

    update public.academy_class_instructor_requests
    set status = 'cancelled',
        updated_at = now()
    where class_id = v_request.class_id
      and id <> p_request_id
      and status = 'requested';
  end if;

  return v_next;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_respond_headquarters_invitation"("p_invitation_id" "uuid", "p_response" "text") RETURNS "public"."academy_headquarters_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_headquarters_id uuid;
  v_invitation public.academy_headquarters_invitations%rowtype;
begin
  if v_actor is null or p_response not in ('accepted', 'declined') then
    raise exception 'academy_headquarters_invalid_response';
  end if;

  select i.headquarters_id into v_headquarters_id
  from public.academy_headquarters_invitations i
  join public.profiles p on p.id = i.target_profile_id
  where i.id = p_invitation_id
    and p.user_id = v_actor;

  if v_headquarters_id is null then
    raise exception 'academy_headquarters_invitation_not_available';
  end if;

  perform 1
  from public.academy_headquarters
  where id = v_headquarters_id
  for update;

  select i.* into v_invitation
  from public.academy_headquarters_invitations i
  join public.profiles p on p.id = i.target_profile_id
  where i.id = p_invitation_id
    and p.user_id = v_actor
    and i.status = 'pending'
    and i.expires_at > now()
  for update of i;

  if v_invitation.id is null then
    raise exception 'academy_headquarters_invitation_not_available';
  end if;

  if p_response = 'accepted' and exists (
    select 1
    from public.academy_headquarters_members member
    where member.headquarters_id = v_invitation.headquarters_id
      and member.member_profile_id = v_invitation.target_profile_id
      and member.status = 'active'
  ) then
    raise exception 'academy_headquarters_member_already_active';
  end if;

  update public.academy_headquarters_invitations
  set status = p_response, responded_at = now(), updated_at = now()
  where id = v_invitation.id
  returning * into v_invitation;

  if p_response = 'accepted' then
    insert into public.academy_headquarters_members (
      headquarters_id,
      member_profile_id,
      role,
      status,
      invited_by_user_id,
      accepted_at,
      stopped_at,
      updated_at
    )
    values (
      v_invitation.headquarters_id,
      v_invitation.target_profile_id,
      v_invitation.role,
      'active',
      v_invitation.invited_by_user_id,
      now(),
      null,
      now()
    )
    on conflict (headquarters_id, member_profile_id)
    do update set
      role = excluded.role,
      status = 'active',
      invited_by_user_id = excluded.invited_by_user_id,
      accepted_at = now(),
      stopped_at = null,
      updated_at = now();
  end if;

  return v_invitation;
end;
$$;




