CREATE OR REPLACE FUNCTION "public"."academy_review_program_step"("p_progress_id" "uuid", "p_approved" boolean, "p_note" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_headquarters_id uuid;
  v_assignment_id uuid;
  v_step_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select
    assignment.headquarters_id,
    progress.assignment_id,
    progress.step_id
  into
    v_headquarters_id,
    v_assignment_id,
    v_step_id
  from public.academy_step_progress progress
  join public.academy_program_assignments assignment
    on assignment.id = progress.assignment_id
  where progress.id = p_progress_id
    and progress.status = 'awaiting_approval';

  if v_headquarters_id is null then
    raise exception 'Pending approval not found';
  end if;

  if exists (
    select 1
    from public.academy_step_submissions submission
    where submission.assignment_id = v_assignment_id
      and submission.step_id = v_step_id
      and submission.status = 'submitted'
  ) then
    raise exception 'Use the submission review operation';
  end if;

  if not public.academy_can_approve_program_progress(v_headquarters_id) then
    raise exception 'Approval permission required';
  end if;

  update public.academy_step_progress
  set
    status = case when p_approved then 'completed' else 'not_started' end,
    completed_at = case when p_approved then now() else null end,
    approved_by_user_id = (select auth.uid()),
    review_note = nullif(trim(p_note), ''),
    reviewed_at = now(),
    updated_at = now()
  where id = p_progress_id;

  return case when p_approved then 'completed' else 'returned' end;
end;
$$;




