CREATE OR REPLACE FUNCTION "public"."academy_set_program_subscription_status"("p_subscription_id" "uuid", "p_status" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_product_id uuid;
  v_member_profile_id uuid;
  v_headquarters_id uuid;
  v_now timestamptz := now();
  v_grant_status text;
begin
  if p_status not in ('active', 'paused', 'cancelled') then
    raise exception 'Unsupported subscription status';
  end if;

  update public.academy_subscriptions subscription
  set
    status = p_status,
    ends_at = case when p_status = 'active' then null else v_now end,
    updated_at = v_now
  from public.academy_subscription_products product
  where subscription.id = p_subscription_id
    and product.id = subscription.subscription_product_id
    and public.academy_owns_hq(product.headquarters_id)
  returning
    subscription.subscription_product_id,
    subscription.member_profile_id,
    product.headquarters_id
  into v_product_id, v_member_profile_id, v_headquarters_id;

  if v_product_id is null then
    raise exception 'Subscription not found or permission denied';
  end if;

  v_grant_status := case
    when p_status = 'active' then 'active'
    when p_status = 'paused' then 'paused'
    else 'revoked'
  end;

  insert into public.academy_entitlement_grants(
    subscription_id,
    member_profile_id,
    program_id,
    status,
    starts_at,
    ends_at
  )
  select
    p_subscription_id,
    v_member_profile_id,
    mapping.program_id,
    v_grant_status,
    v_now,
    case when p_status = 'active' then null else v_now end
  from public.academy_subscription_product_programs mapping
  where mapping.subscription_product_id = v_product_id
  on conflict (subscription_id, program_id)
  do update set
    status = excluded.status,
    ends_at = excluded.ends_at,
    updated_at = v_now;

  insert into public.academy_program_assignments(
    headquarters_id,
    program_id,
    learner_profile_id,
    status
  )
  select
    v_headquarters_id,
    mapping.program_id,
    v_member_profile_id,
    'active'
  from public.academy_subscription_product_programs mapping
  where mapping.subscription_product_id = v_product_id
  on conflict (program_id, learner_profile_id)
  do update set updated_at = now();

  return p_status;
end;
$$;




CREATE TABLE IF NOT EXISTS "public"."academy_headquarters_members" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "headquarters_id" "uuid" NOT NULL,
    "member_profile_id" "uuid" NOT NULL,
    "role" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "invited_by_user_id" "uuid" NOT NULL,
    "accepted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "stopped_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "academy_headquarters_members_role_check" CHECK (("role" = ANY (ARRAY['administrator'::"text", 'course_editor'::"text"]))),
    CONSTRAINT "academy_headquarters_members_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'stopped'::"text"])))
);




CREATE OR REPLACE FUNCTION "public"."academy_stop_headquarters_member"("p_member_id" "uuid") RETURNS "public"."academy_headquarters_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_actor_role text;
  v_headquarters_id uuid;
  v_member public.academy_headquarters_members%rowtype;
begin
  select headquarters_id into v_headquarters_id
  from public.academy_headquarters_members
  where id = p_member_id;

  if v_headquarters_id is null then
    raise exception 'academy_headquarters_forbidden';
  end if;

  perform 1
  from public.academy_headquarters
  where id = v_headquarters_id
  for update;

  select * into v_member
  from public.academy_headquarters_members
  where id = p_member_id
  for update;

  v_actor_role := private.academy_headquarters_role(v_member.headquarters_id, v_actor);
  if v_member.id is null or v_actor_role not in ('owner', 'administrator') then
    raise exception 'academy_headquarters_forbidden';
  end if;
  if v_actor_role = 'administrator' and v_member.role = 'administrator' then
    raise exception 'academy_headquarters_owner_required';
  end if;

  update public.academy_headquarters_members
  set status = 'stopped', stopped_at = now(), updated_at = now()
  where id = p_member_id
  returning * into v_member;

  update public.academy_headquarters_invitations
  set status = 'cancelled', responded_at = now(), updated_at = now()
  where headquarters_id = v_member.headquarters_id
    and target_profile_id = v_member.member_profile_id
    and status = 'pending';

  return v_member;
end;
$$;




