CREATE OR REPLACE FUNCTION "public"."academy_update_headquarters_profile"("p_headquarters_id" "uuid", "p_patch" "jsonb") RETURNS "public"."academy_headquarters"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_headquarters public.academy_headquarters%rowtype;
begin
  if (select auth.uid()) is null
    or not private.academy_can_manage_headquarters(p_headquarters_id) then
    raise exception 'academy_headquarters_forbidden';
  end if;
  if jsonb_typeof(coalesce(p_patch, '{}'::jsonb)) <> 'object' then
    raise exception 'academy_headquarters_invalid_patch';
  end if;

  update public.academy_headquarters h
  set name = case when p_patch ? 'name' then coalesce(nullif(trim(p_patch ->> 'name'), ''), h.name) else h.name end,
      tagline = case when p_patch ? 'tagline' then nullif(trim(p_patch ->> 'tagline'), '') else h.tagline end,
      front_message = case when p_patch ? 'front_message' then nullif(trim(p_patch ->> 'front_message'), '') else h.front_message end,
      hero_image_url = case when p_patch ? 'hero_image_url' then nullif(trim(p_patch ->> 'hero_image_url'), '') else h.hero_image_url end,
      logo_url = case when p_patch ? 'logo_url' then nullif(trim(p_patch ->> 'logo_url'), '') else h.logo_url end,
      contact_email = case when p_patch ? 'contact_email' then nullif(trim(p_patch ->> 'contact_email'), '') else h.contact_email end,
      default_payment_note = case when p_patch ? 'default_payment_note' then nullif(trim(p_patch ->> 'default_payment_note'), '') else h.default_payment_note end,
      main_color = case when p_patch ? 'main_color' then nullif(trim(p_patch ->> 'main_color'), '') else h.main_color end,
      renewal_period_months = case when p_patch ? 'renewal_period_months' then (p_patch ->> 'renewal_period_months')::integer else h.renewal_period_months end,
      next_instructor_number = case when p_patch ? 'next_instructor_number' then (p_patch ->> 'next_instructor_number')::integer else h.next_instructor_number end,
      front_blocks = case when p_patch ? 'front_blocks' then coalesce(p_patch -> 'front_blocks', '[]'::jsonb) else h.front_blocks end,
      updated_at = now()
  where h.id = p_headquarters_id
  returning * into v_headquarters;

  if v_headquarters.id is null then
    raise exception 'academy_headquarters_not_found';
  end if;
  return v_headquarters;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."academy_update_procurement_order_status"("p_order_id" "uuid", "p_status" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_headquarters_id uuid;
begin
  if (select auth.uid()) is null then raise exception 'Authentication required'; end if;
  if p_status not in ('submitted', 'accepted', 'paid', 'shipped', 'completed', 'cancelled') then raise exception 'Invalid order status'; end if;
  select headquarters_id into v_headquarters_id from public.academy_procurement_orders where id = p_order_id;
  if v_headquarters_id is null then raise exception 'Order not found'; end if;
  if not public.academy_owns_hq(v_headquarters_id) then raise exception 'Academy owner access required'; end if;
  update public.academy_procurement_orders set status = p_status, updated_at = now() where id = p_order_id;
  insert into public.academy_order_status_history (order_id, status, changed_by_user_id, note) values (p_order_id, p_status, (select auth.uid()), nullif(trim(p_note), ''));
  return p_order_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."accept_fund_support_claim"("p_token" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_claim public.fund_support_claims%rowtype;
  v_support public.fund_supports%rowtype;
  v_project public.fund_projects%rowtype;
  v_profile_id uuid;
  v_participation_id uuid;
begin
  if v_actor is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if p_token is null or p_token !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid claim token' using errcode = '22023';
  end if;

  select * into v_claim
  from public.fund_support_claims
  where token_hash = encode(extensions.digest(p_token, 'sha256'), 'hex')
  for update;

  if not found
    or v_claim.revoked_at is not null
    or v_claim.accepted_at is not null
    or v_claim.expires_at <= now() then
    raise exception 'claim token is unavailable' using errcode = '42501';
  end if;

  select * into v_support
  from public.fund_supports
  where id = v_claim.support_id
  for update;

  select * into v_project
  from public.fund_projects
  where id = v_support.project_id;

  if v_support.record_status <> 'valid' then
    raise exception 'support record is unavailable' using errcode = '42501';
  end if;

  select id into v_profile_id
  from public.profiles
  where user_id = v_actor
  limit 1;

  if v_profile_id is null then
    raise exception 'a Mikke profile is required before accepting a claim' using errcode = '42501';
  end if;

  insert into public.fund_participations (
    project_id,
    support_id,
    owner_user_id,
    supporter_user_id,
    supporter_profile_id,
    owner_consent_status,
    supporter_consent_status,
    display_mode
  ) values (
    v_project.id,
    v_support.id,
    v_project.owner_user_id,
    v_actor,
    v_profile_id,
    'granted',
    'pending',
    'hidden'
  ) returning id into v_participation_id;

  insert into public.activity_logs (
    user_id,
    profile_id,
    activity_type,
    category,
    source_service,
    source_record_id,
    occurred_at,
    title,
    description,
    visibility,
    status,
    display_on_story,
    display_in_timeline,
    display_as_achievement,
    counts_toward_summary,
    has_financial_value,
    amount,
    transaction_type,
    payment_status
  ) values (
    v_actor,
    v_profile_id,
    'fund_participation_recorded',
    'production',
    'fund',
    v_participation_id::text,
    now(),
    'Fundの応援を受け取りました',
    '応援参加をMikke IDへ登録しました。応援者情報と金額は公開されません。',
    'private',
    'completed',
    false,
    false,
    false,
    false,
    false,
    null,
    'none',
    'not_required'
  )
  on conflict (profile_id, source_service, source_record_id) do nothing;

  update public.fund_support_claims
  set accepted_by_user_id = v_actor,
      accepted_at = now()
  where id = v_claim.id;

  return v_participation_id;
end;
$_$;




COMMENT ON FUNCTION "public"."accept_fund_support_claim"("p_token" "text") IS 'Atomically accepts a Fund claim, creates the participation, and records a private non-financial Activity Log.';



CREATE OR REPLACE FUNCTION "public"."cancel_mikke_media_reservation"("p_asset_id" "uuid") RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$ select private.cancel_mikke_media_reservation(p_asset_id); $$;




CREATE TABLE IF NOT EXISTS "public"."community_communities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "slug" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "join_mode" "text" DEFAULT 'open_free'::"text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "owner_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "logo_url" "text",
    "banner_url" "text",
    "home_metric_1" "text" DEFAULT 'unread'::"text" NOT NULL,
    "home_metric_2" "text" DEFAULT 'today_activity'::"text" NOT NULL,
    "home_metric_3" "text" DEFAULT 'upcoming_events'::"text" NOT NULL,
    CONSTRAINT "community_communities_banner_url_check" CHECK ((("banner_url" IS NULL) OR (("char_length"("banner_url") <= 2048) AND ("banner_url" ~ '^https://'::"text")))),
    CONSTRAINT "community_communities_home_metrics_valid" CHECK ((("home_metric_1" = ANY (ARRAY['unread'::"text", 'today_activity'::"text", 'upcoming_events'::"text", 'rooms'::"text", 'posts'::"text", 'comments'::"text", 'chat_messages'::"text", 'resources'::"text"])) AND ("home_metric_2" = ANY (ARRAY['unread'::"text", 'today_activity'::"text", 'upcoming_events'::"text", 'rooms'::"text", 'posts'::"text", 'comments'::"text", 'chat_messages'::"text", 'resources'::"text"])) AND ("home_metric_3" = ANY (ARRAY['unread'::"text", 'today_activity'::"text", 'upcoming_events'::"text", 'rooms'::"text", 'posts'::"text", 'comments'::"text", 'chat_messages'::"text", 'resources'::"text"])) AND ("home_metric_1" <> "home_metric_2") AND ("home_metric_1" <> "home_metric_3") AND ("home_metric_2" <> "home_metric_3"))),
    CONSTRAINT "community_communities_join_mode_check" CHECK (("join_mode" = ANY (ARRAY['open_free'::"text", 'invite_only'::"text", 'paid'::"text"]))),
    CONSTRAINT "community_communities_logo_url_check" CHECK ((("logo_url" IS NULL) OR (("char_length"("logo_url") <= 2048) AND ("logo_url" ~ '^https://'::"text")))),
    CONSTRAINT "community_communities_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"])))
);




COMMENT ON COLUMN "public"."community_communities"."logo_url" IS 'Public Community logo image URL backed by the shared mikke-media asset flow.';



COMMENT ON COLUMN "public"."community_communities"."banner_url" IS 'Public Community wide banner image URL backed by the shared mikke-media asset flow.';



CREATE OR REPLACE FUNCTION "public"."community_create"("p_name" "text", "p_slug" "text", "p_description" "text" DEFAULT NULL::"text", "p_display_name" "text" DEFAULT NULL::"text") RETURNS "public"."community_communities"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_user_id uuid := (select auth.uid());
  v_slug text := lower(trim(p_slug));
  v_name text := lower(trim(p_name));
  v_compact_name text := regexp_replace(lower(trim(p_name)), '[[:space:]_-]+', '', 'g');
  v_community public.community_communities;
begin
  if v_user_id is null then
    raise exception 'Authentication is required';
  end if;
  if length(trim(p_name)) < 2 then
    raise exception 'Community name must be at least 2 characters';
  end if;
  if v_slug !~ '^[a-z0-9][a-z0-9-]{2,59}$' then
    raise exception 'Slug must be 3-60 lowercase letters, numbers, or hyphens';
  end if;
  if v_slug = any(array[
    'admin',
    'administrator',
    'api',
    'app',
    'apps',
    'auth',
    'billing',
    'community',
    'communities',
    'dashboard',
    'help',
    'home',
    'login',
    'logout',
    'manager',
    'member',
    'members',
    'mikke',
    'mikke-community',
    'mikke-id',
    'mikke-os',
    'mikkeos',
    'mikkeruu',
    'official',
    'official-academy',
    'official-academy-community',
    'official-partner',
    'official-trainer',
    'officialacademy',
    'officialpartner',
    'officialtrainer',
    'owner',
    'profile',
    'root',
    'settings',
    'staff',
    'support',
    'system'
  ]) or v_slug like 'admin-%'
    or v_slug like 'api-%'
    or v_slug like 'mikke-%'
    or v_slug like 'mikkeos-%'
    or v_slug like 'mikkeruu-%'
    or v_slug like 'official-%'
    or v_slug like 'system-%' then
    raise exception 'This slug is reserved for mikke official or system use';
  end if;
  if v_compact_name like '%mikke%'
    or v_compact_name like '%mikkeos%'
    or v_compact_name like '%official%'
    or v_compact_name like '%officialacademy%'
    or v_compact_name like '%admin%'
    or v_compact_name like '%system%' then
    raise exception 'This Community name is reserved for mikke official or system use';
  end if;

  insert into public.community_communities (slug, name, description, join_mode, status, owner_user_id)
  values (v_slug, trim(p_name), nullif(trim(p_description), ''), 'open_free', 'active', v_user_id)
  returning * into v_community;

  insert into public.community_memberships (community_id, user_id, role, status)
  values (v_community.id, v_user_id, 'owner', 'active');

  insert into public.community_member_profiles (community_id, user_id, display_name)
  values (v_community.id, v_user_id, coalesce(nullif(trim(p_display_name), ''), 'Community owner'));

  insert into public.community_entitlement_definitions (community_id, key, name, description)
  values (v_community.id, 'paid:member', 'Paid member', 'Basic entitlement for limited rooms');

  insert into public.community_rooms (community_id, title, description, kind, access_type, sort_order, member_can_post, member_can_comment)
  values
    (v_community.id, 'Announcements', 'Post official community announcements.', 'announcement', 'free', 10, false, true),
    (v_community.id, 'Free talk', 'Members can post and talk freely.', 'normal', 'free', 20, true, true),
    (v_community.id, 'Questions', 'Members can post questions and consultations.', 'question', 'free', 30, true, true);

  return v_community;
end;
$_$;




CREATE TABLE IF NOT EXISTS "public"."community_invitations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "community_id" "uuid" NOT NULL,
    "invited_user_id" "uuid" NOT NULL,
    "invited_by_user_id" "uuid" NOT NULL,
    "invited_mikke_id" "text" NOT NULL,
    "entitlement_key" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "expires_at" timestamp with time zone,
    "accepted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "community_invitations_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'declined'::"text", 'revoked'::"text", 'expired'::"text"])))
);




CREATE OR REPLACE FUNCTION "public"."community_invite_by_mikke_id"("p_community_id" "uuid", "p_mikke_id" "text", "p_entitlement_key" "text" DEFAULT NULL::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."community_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'community_private'
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_invited_user uuid;
  v_invitation public.community_invitations;
  v_handle text := lower(trim(regexp_replace(coalesce(p_mikke_id, ''), '^@', '')));
begin
  if v_actor is null or not community_private.is_staff(p_community_id) then
    raise exception 'Staff permission is required';
  end if;
  select p.user_id into v_invited_user from public.profiles p where lower(p.handle) = v_handle limit 1;
  if v_invited_user is null then raise exception 'Mikke ID was not found'; end if;
  if exists (select 1 from public.community_memberships m where m.community_id = p_community_id and m.user_id = v_invited_user and m.status = 'active') then
    raise exception 'This user is already an active member';
  end if;
  insert into public.community_invitations (community_id, invited_user_id, invited_by_user_id, invited_mikke_id, entitlement_key, status, expires_at)
  values (p_community_id, v_invited_user, v_actor, v_handle, nullif(trim(p_entitlement_key), ''), 'pending', p_expires_at)
  on conflict (community_id, invited_user_id) do update set
    invited_by_user_id = excluded.invited_by_user_id,
    invited_mikke_id = excluded.invited_mikke_id,
    entitlement_key = excluded.entitlement_key,
    status = 'pending', expires_at = excluded.expires_at, accepted_at = null, updated_at = now()
  returning * into v_invitation;
  return v_invitation;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."community_leave"("p_community_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'community_private'
    AS $$
declare v_user uuid := (select auth.uid());
begin
  if v_user is null then raise exception 'Authentication is required'; end if;
  if exists (select 1 from public.community_communities where id = p_community_id and owner_user_id = v_user) then
    raise exception 'The owner must transfer ownership before leaving';
  end if;
  update public.community_memberships set status = 'left' where community_id = p_community_id and user_id = v_user;
  if not found then raise exception 'Active membership was not found'; end if;
  update public.community_member_entitlements set status = 'revoked', ends_at = coalesce(ends_at, now())
    where community_id = p_community_id and user_id = v_user and status = 'active';
end;
$$;




CREATE TABLE IF NOT EXISTS "public"."community_join_applications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "community_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "display_name" "text" NOT NULL,
    "legal_name" "text",
    "email" "text" NOT NULL,
    "phone" "text",
    "join_reason" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "reviewed_by_user_id" "uuid",
    "review_note" "text",
    "submitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reviewed_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "community_join_applications_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'cancelled'::"text"])))
);




CREATE OR REPLACE FUNCTION "public"."community_review_join_application"("p_application_id" "uuid", "p_decision" "text", "p_review_note" "text" DEFAULT NULL::"text") RETURNS "public"."community_join_applications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'community_private'
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_application public.community_join_applications;
begin
  if v_user_id is null then raise exception 'Authentication is required'; end if;
  if p_decision not in ('approved', 'rejected') then raise exception 'Invalid decision'; end if;
  select * into v_application from public.community_join_applications where id = p_application_id for update;
  if v_application.id is null or not community_private.is_staff(v_application.community_id) then raise exception 'Staff permission is required'; end if;
  update public.community_join_applications set
    status = p_decision, reviewed_by_user_id = v_user_id,
    review_note = nullif(trim(p_review_note), ''), reviewed_at = now()
  where id = p_application_id returning * into v_application;
  if p_decision = 'approved' then
    insert into public.community_memberships (community_id, user_id, role, status)
    values (v_application.community_id, v_application.user_id, 'member', 'active')
    on conflict (community_id, user_id) do update set status = 'active';
    insert into public.community_member_profiles (community_id, user_id, display_name)
    values (v_application.community_id, v_application.user_id, v_application.display_name)
    on conflict (community_id, user_id) do update set display_name = excluded.display_name;
  end if;
  insert into public.community_moderation_actions (community_id, actor_user_id, action_type, target_type, target_id, reason)
  values (v_application.community_id, v_user_id, 'join_application_' || p_decision, 'join_application', v_application.id, p_review_note);
  return v_application;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."community_submit_join_application"("p_community_id" "uuid", "p_display_name" "text", "p_legal_name" "text", "p_phone" "text", "p_join_reason" "text", "p_accept_terms" boolean, "p_accept_rules" boolean, "p_accept_privacy" boolean) RETURNS "public"."community_join_applications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'community_private'
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_email text;
  v_settings public.community_safety_settings;
  v_application public.community_join_applications;
  v_status text;
  v_invitation public.community_invitations;
begin
  if v_user_id is null then raise exception 'Authentication is required'; end if;
  select email into v_email from auth.users where id = v_user_id;
  select i.* into v_invitation from public.community_invitations i
    where i.community_id = p_community_id and i.invited_user_id = v_user_id and i.status = 'pending'
      and (i.expires_at is null or i.expires_at > now()) for update;
  select s.* into v_settings
  from public.community_safety_settings s
  join public.community_communities c on c.id = s.community_id
  where s.community_id = p_community_id and c.status = 'active'
    and (c.join_mode = 'open_free' or v_invitation.id is not null);
  if v_settings.community_id is null then raise exception 'This Community is not accepting applications'; end if;
  if char_length(trim(coalesce(p_display_name, ''))) < 1 then raise exception 'Display name is required'; end if;
  if v_settings.require_legal_name and char_length(trim(coalesce(p_legal_name, ''))) < 1 then raise exception 'Legal name is required'; end if;
  if v_settings.require_phone and char_length(regexp_replace(coalesce(p_phone, ''), '[^0-9+]', '', 'g')) < 8 then raise exception 'A valid phone number is required'; end if;
  if v_settings.require_join_reason and char_length(trim(coalesce(p_join_reason, ''))) < 1 then raise exception 'Join reason is required'; end if;
  if not (p_accept_terms and p_accept_rules and p_accept_privacy) then raise exception 'All required documents must be accepted'; end if;
  v_status := case when v_invitation.id is not null or v_settings.approval_mode = 'auto' then 'approved' else 'pending' end;

  insert into public.community_join_applications (
    community_id, user_id, display_name, legal_name, email, phone, join_reason,
    status, reviewed_by_user_id, review_note, submitted_at, reviewed_at
  ) values (
    p_community_id, v_user_id, trim(p_display_name), nullif(trim(p_legal_name), ''), v_email,
    nullif(trim(p_phone), ''), nullif(trim(p_join_reason), ''), v_status,
    case when v_invitation.id is not null then v_invitation.invited_by_user_id when v_status = 'approved' then v_user_id else null end,
    case when v_invitation.id is not null then 'Approved by mikke ID invitation' when v_status = 'approved' then 'Auto approved' else null end,
    now(), case when v_status = 'approved' then now() else null end
  ) on conflict (community_id, user_id) do update set
    display_name = excluded.display_name, legal_name = excluded.legal_name,
    email = excluded.email, phone = excluded.phone, join_reason = excluded.join_reason,
    status = excluded.status, reviewed_by_user_id = excluded.reviewed_by_user_id,
    review_note = excluded.review_note, submitted_at = now(), reviewed_at = excluded.reviewed_at
  returning * into v_application;

  insert into public.community_consent_records (community_id, application_id, user_id, document_type, document_version)
  values
    (p_community_id, v_application.id, v_user_id, 'terms', v_settings.terms_version),
    (p_community_id, v_application.id, v_user_id, 'rules', v_settings.rules_version),
    (p_community_id, v_application.id, v_user_id, 'privacy', v_settings.privacy_version)
  on conflict do nothing;

  if v_status = 'approved' then
    insert into public.community_memberships (community_id, user_id, role, status)
    values (p_community_id, v_user_id, 'member', 'active')
    on conflict (community_id, user_id) do update set status = 'active';
    insert into public.community_member_profiles (community_id, user_id, display_name)
    values (p_community_id, v_user_id, trim(p_display_name))
    on conflict (community_id, user_id) do update set display_name = excluded.display_name;
    if v_invitation.id is not null then
      update public.community_invitations set status = 'accepted', accepted_at = now() where id = v_invitation.id;
      if v_invitation.entitlement_key is not null then
        insert into public.community_member_entitlements (
          community_id, user_id, entitlement_key, source, source_reference, status, granted_by_user_id
        ) values (
          p_community_id, v_user_id, v_invitation.entitlement_key, 'external', 'invitation:' || v_invitation.id, 'active', v_invitation.invited_by_user_id
        ) on conflict (community_id, user_id, entitlement_key, source) do update set
          status = 'active', source_reference = excluded.source_reference, granted_by_user_id = excluded.granted_by_user_id,
          starts_at = now(), ends_at = null;
      end if;
    end if;
  end if;
  return v_application;
end;
$$;




