CREATE OR REPLACE FUNCTION "public"."mikke_mark_marketnote_owned_from_login"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  insert into public.mikke_app_entitlements (
    user_id,
    app_key,
    status,
    source,
    starts_at,
    ends_at,
    note,
    updated_at
  ) values (
    v_user_id,
