$$;




CREATE OR REPLACE FUNCTION "public"."mikke_normalize_mikke_id"("p_handle" "text", "p_current" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_handle text;
begin
  v_handle := lower(trim(regexp_replace(
    coalesce(nullif(trim(p_handle), ''), p_current, ''),
    '^@', ''
  )));

  if v_handle = '' then
    raise exception 'mikke IDを入力してください。' using errcode = '22023';
  end if;

  -- 現在値のままなら、書式・予約語の検査を通さずそのまま返す
  if p_current is not null and v_handle = lower(trim(p_current)) then
    return v_handle;
  end if;

  if v_handle !~ '^[a-z0-9_][a-z0-9_-]{2,29}$' then
    raise exception 'mikke IDは半角英数字・_・- の3〜30文字で入力してください。' using errcode = '22023';
  end if;

  -- 公式・システム予約（全アプリ共通）
  if public.mikke_reserved_slug(v_handle) then
    raise exception 'このmikke IDは公式またはシステム用です。別のIDを選んでください。' using errcode = '22023';
  end if;

  -- STORYの公開URL（/story/配下）と衝突する語
  if v_handle = any (array['story', 'start', 'edit', 'new', 'preview', 'collection', 'share']) then
    raise exception 'このmikke IDは公式またはシステム用です。別のIDを選んでください。' using errcode = '22023';
  end if;

  return v_handle;
end;
$_$;




COMMENT ON FUNCTION "public"."mikke_normalize_mikke_id"("p_handle" "text", "p_current" "text") IS 'mikke IDを正規化し、書式と予約語を検査して返す。重複は profiles_handle_unique に委ねる。現在値と同じ場合は検査を飛ばす。';



CREATE OR REPLACE FUNCTION "public"."mikke_reserved_slug"("p_slug" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_slug is null then false
    when p_slug = any (array[
      'admin', 'administrator', 'api', 'app', 'apps', 'auth', 'billing',
      'community', 'communities', 'dashboard', 'help', 'home', 'login', 'logout',
      'manager', 'member', 'members', 'mikke', 'mikke-community', 'mikke-id',
      'mikke-os', 'mikkeos', 'mikkeruu', 'official', 'official-academy',
      'official-academy-community', 'official-partner', 'official-trainer',
      'officialacademy', 'officialpartner', 'officialtrainer', 'owner',
      'profile', 'root', 'settings', 'staff', 'support', 'system'
    ]) then true
    when p_slug like 'admin-%'
      or p_slug like 'api-%'
      or p_slug like 'mikke-%'
      or p_slug like 'mikkeos-%'
      or p_slug like 'mikkeruu-%'
      or p_slug like 'official-%'
      or p_slug like 'system-%' then true
    else false
  end;
$$;




COMMENT ON FUNCTION "public"."mikke_reserved_slug"("p_slug" "text") IS 'mikke公式・システムに予約されたスラッグかを判定する。正典: docs/MIKKEOS_RESERVED_NAMES_POLICY_2026-08-04.md';



CREATE OR REPLACE FUNCTION "public"."mikke_update_my_mikke_id"("p_handle" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_profile_id uuid;
  v_current text;
  v_next text;
  v_constraint_name text;
begin
  if v_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  select p.id, p.handle
  into v_profile_id, v_current
  from public.profiles p
  where p.user_id = v_user_id
  order by p.created_at asc
  limit 1
  for update;

  if v_profile_id is null then
    raise exception 'Profile not found for authenticated user.' using errcode = 'P0002';
  end if;

  v_next := public.mikke_normalize_mikke_id(p_handle, v_current);

  if v_next = v_current then
    return v_current;
  end if;

  begin
    update public.profiles
    set handle = v_next,
        updated_at = now()
    where id = v_profile_id
      and user_id = v_user_id;
  exception
    when unique_violation then
      get stacked diagnostics v_constraint_name = constraint_name;

      if v_constraint_name in (
        'profiles_handle_unique',
        'profiles_user_handle_unique',
        'story_profiles_handle_lower_key'
      ) then
        raise exception 'このmikke IDは使用されています。別のIDを選んでください。'
          using errcode = '23505';
      end if;

      raise;
  end;

  return v_next;
end;
$$;




COMMENT ON FUNCTION "public"."mikke_update_my_mikke_id"("p_handle" "text") IS '認証中の本人のmikke IDを変更する。書式・予約語検査はmikke_normalize_mikke_idへ委譲する。';



CREATE OR REPLACE FUNCTION "public"."mikkeos_ai_tech_approve_for_lab"("p_candidate_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  experiment_id uuid;
begin
  if actor_id is null or not exists (
    select 1 from public.mikkeos_hq_staff_members staff
    where staff.user_id = actor_id and staff.is_active and staff.role in ('owner', 'admin')
  ) then
    raise exception 'AI TECH LAB approval permission required';
  end if;

  if not exists (
    select 1 from public.mikkeos_ai_tech_candidates candidate
    where candidate.id = p_candidate_id and candidate.status in ('candidate', 'held', 'approved_for_lab')
  ) then
    raise exception 'AI TECH LAB candidate unavailable';
  end if;

  insert into public.mikkeos_ai_tech_experiments as existing_experiment (
    candidate_id, title, objective, test_plan, approved_by
  )
  select
    candidate.id,
    news.title,
    candidate.possible_use,
    coalesce(nullif(candidate.test_idea, ''), '小規模な比較サンプルを作成し、品質・速度・費用・既存環境への影響を確認する。'),
    actor_id
  from public.mikkeos_ai_tech_candidates candidate
  join public.mikkeos_ai_tech_news news on news.id = candidate.news_id
  where candidate.id = p_candidate_id
  on conflict (candidate_id) do update
    set status = case
      when existing_experiment.status in ('held', 'rejected') then 'approved'
      else existing_experiment.status
    end,
    approved_by = actor_id,
    approved_at = now()
  returning id into experiment_id;

  update public.mikkeos_ai_tech_candidates
  set status = 'approved_for_lab'
  where id = p_candidate_id;

  insert into public.mikkeos_hq_audit_logs (actor_user_id, action, entity_type, entity_id, details)
  values (actor_id, 'approve_for_lab', 'mikkeos_ai_tech_experiments', experiment_id, jsonb_build_object('candidate_id', p_candidate_id));

  return experiment_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_ai_tech_decide_experiment"("p_experiment_id" "uuid", "p_decision" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  next_status text;
  adoption_area text;
begin
  if actor_id is null or not exists (
    select 1 from public.mikkeos_hq_staff_members staff
    where staff.user_id = actor_id and staff.is_active and staff.role in ('owner', 'admin')
  ) then
    raise exception 'AI TECH LAB decision permission required';
  end if;

  next_status := case p_decision
    when 'adopt' then 'adopted'
    when 'hold' then 'held'
    when 'reject' then 'rejected'
    else null
  end;
  if next_status is null then raise exception 'Invalid AI TECH LAB decision'; end if;

  if not exists (
    select 1 from public.mikkeos_ai_tech_experiments experiment
    where experiment.id = p_experiment_id and experiment.status in ('result_ready', 'held')
  ) then
    raise exception 'Experiment result is not ready for decision';
  end if;

  update public.mikkeos_ai_tech_experiments
  set status = next_status,
      decided_by = actor_id,
      decided_at = now(),
      decision_note = coalesce(trim(p_note), '')
  where id = p_experiment_id;

  if next_status = 'adopted' then
    select case candidate.category
      when 'web_ui' then 'web'
      when 'new_feature' then 'product'
      else candidate.category
    end
    into adoption_area
    from public.mikkeos_ai_tech_experiments experiment
    join public.mikkeos_ai_tech_candidates candidate on candidate.id = experiment.candidate_id
    where experiment.id = p_experiment_id;

    insert into public.mikkeos_ai_tech_adoptions as existing_adoption (
      experiment_id, title, area, summary, adopted_by
    )
    select experiment.id, experiment.title, adoption_area,
      coalesce(nullif(experiment.result_summary, ''), experiment.recommendation), actor_id
    from public.mikkeos_ai_tech_experiments experiment
    where experiment.id = p_experiment_id
    on conflict (experiment_id) do update
      set summary = excluded.summary,
          adopted_by = excluded.adopted_by,
          adopted_at = now(),
          integration_status = case
            when existing_adoption.integration_status = 'retired' then 'pending'
            else existing_adoption.integration_status
          end;
  end if;

  insert into public.mikkeos_hq_audit_logs (actor_user_id, action, entity_type, entity_id, details)
  values (actor_id, 'decide_experiment', 'mikkeos_ai_tech_experiments', p_experiment_id, jsonb_build_object('decision', p_decision));

  return next_status;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_ai_tech_touch_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_claim_local_preview"("p_worker_secret" "text") RETURNS TABLE("item_id" "uuid", "project_id" "uuid", "app_key" "text", "local_path" "text", "local_branch" "text", "local_head" "text", "requested_action" "text", "current_url" "text", "current_port" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  claimed_id uuid;
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1 from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary'
      and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;

  select item.id into claimed_id
  from public.mikkeos_implementation_items item
  where item.item_type = 'local_result'
    and item.archived_at is null
    and item.preview_status in ('queued', 'stopping')
  order by item.preview_requested_at asc nulls last
  for update skip locked
  limit 1;

  if claimed_id is null then return; end if;

  update public.mikkeos_implementation_items item
  set preview_status = case when item.preview_requested_action = 'stop' then 'stopping' else 'preparing' end,
      preview_note = case when item.preview_requested_action = 'stop' then 'ローカルUIを停止しています。' else '依存関係と起動環境を準備しています。' end,
      updated_at = now()
  where item.id = claimed_id;

  return query
  select item.id, item.project_id, coalesce(project.app_key, ''), item.local_path,
         item.local_branch, item.local_head, item.preview_requested_action,
         item.preview_url, item.preview_port
  from public.mikkeos_implementation_items item
  left join public.mikkeos_implementation_projects project on project.id = item.project_id
  where item.id = claimed_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_claim_next_consultation"("p_worker_secret" "text") RETURNS TABLE("item_id" "uuid", "project_id" "uuid", "app_key" "text", "app_name" "text", "branch_ref" "text", "priority" "text", "title" "text", "body" "text", "attempt" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  claimed_id uuid;
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1
    from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary'
      and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;

  update public.mikkeos_implementation_items
  set status = 'open',
      task_ref = '',
      dispatcher_claimed_at = null,
      dispatcher_last_error = '前回のdispatcherが完了通知前に停止したため再受付しました。',
      updated_at = now()
  where item_type = 'consultation'
    and status = 'in_progress'
    and task_ref like 'dispatcher:%'
    and dispatcher_claimed_at < now() - interval '90 minutes';

  select candidate.id into claimed_id
  from public.mikkeos_implementation_items candidate
  where candidate.item_type = 'consultation'
    and candidate.status = 'open'
    and candidate.archived_at is null
    and candidate.dispatcher_attempts < 3
  order by
    case candidate.priority when 'urgent' then 1 when 'high' then 2 when 'normal' then 3 else 4 end,
    candidate.created_at
  for update skip locked
  limit 1;

  if claimed_id is null then
    return;
  end if;

  update public.mikkeos_implementation_items claimed
  set status = 'in_progress',
      dispatcher_attempts = claimed.dispatcher_attempts + 1,
      dispatcher_claimed_at = now(),
      dispatcher_last_error = '',
      task_ref = 'dispatcher:' || claimed.id::text,
      updated_at = now()
  where claimed.id = claimed_id;

  return query
  select
    item.id,
    item.project_id,
    project.app_key,
    project.app_name,
    project.branch_ref,
    item.priority,
    item.title,
    item.body,
    item.dispatcher_attempts
  from public.mikkeos_implementation_items item
  left join public.mikkeos_implementation_projects project on project.id = item.project_id
  where item.id = claimed_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_claim_next_conversation_message"("p_worker_secret" "text") RETURNS TABLE("message_id" "uuid", "conversation_id" "uuid", "conversation_title" "text", "message_mode" "text", "message_content" "text", "attempt" integer, "codex_thread_id" "text", "app_key" "text", "app_name" "text", "source_branch" "text", "project_snapshot" "jsonb", "gate_snapshot" "jsonb", "visible_history" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  claimed_id uuid;
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1
    from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary'
      and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;

  update public.mikkeos_implementation_messages message
  set status = 'pending',
      dispatcher_claimed_at = null,
      dispatcher_last_error = '前回のdispatcherが応答保存前に停止したため再受付しました。',
      updated_at = now()
  where message.role = 'user'
    and message.status = 'in_progress'
    and message.dispatcher_claimed_at < now() - interval '90 minutes';

  update public.mikkeos_implementation_conversations conversation
  set status = 'queued', updated_at = now()
  where exists (
    select 1 from public.mikkeos_implementation_messages message
    where message.conversation_id = conversation.id
      and message.role = 'user'
      and message.status = 'pending'
  ) and not exists (
    select 1 from public.mikkeos_implementation_messages active
    where active.conversation_id = conversation.id
      and active.role = 'user'
      and active.status = 'in_progress'
  ) and conversation.status in ('responding', 'executing');

  select candidate.id into claimed_id
  from public.mikkeos_implementation_messages candidate
  join public.mikkeos_implementation_conversations conversation
    on conversation.id = candidate.conversation_id
  where candidate.role = 'user'
    and candidate.status = 'pending'
    and candidate.dispatcher_attempts < 3
    and conversation.archived_at is null
    and not exists (
      select 1
      from public.mikkeos_implementation_messages active
      where active.conversation_id = candidate.conversation_id
        and active.role = 'user'
        and active.status = 'in_progress'
    )
  order by candidate.created_at
  for update of conversation, candidate skip locked
  limit 1;

  if claimed_id is null then
    return;
  end if;

  update public.mikkeos_implementation_messages claimed
  set status = 'in_progress',
      dispatcher_attempts = claimed.dispatcher_attempts + 1,
      dispatcher_claimed_at = now(),
      dispatcher_last_error = '',
      updated_at = now()
  where claimed.id = claimed_id;

  update public.mikkeos_implementation_conversations conversation
  set status = case message.mode when 'execution' then 'executing' else 'responding' end,
      updated_at = now()
  from public.mikkeos_implementation_messages message
  where message.id = claimed_id and conversation.id = message.conversation_id;

  return query
  select
    message.id,
    conversation.id,
    conversation.title,
    message.mode,
    message.content,
    message.dispatcher_attempts,
    conversation.codex_thread_id,
    coalesce(project.app_key, 'mikkeos'),
    coalesce(project.app_name, 'mikkeOS全体'),
    coalesce(nullif(project.branch_ref, ''), 'master'),
    jsonb_build_object(
      'status', project.status,
      'phase', project.phase,
      'current_focus', project.current_focus,
      'public_state', project.public_state,
      'verification_note', project.verification_note,
      'verify_path', project.verify_path,
      'branch_ref', project.branch_ref
    ),
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'gate', gate.gate_key,
        'status', gate.status,
        'summary', gate.summary,
        'evidence_ref', gate.evidence_ref
      ) order by gate.gate_key)
      from public.mikkeos_implementation_gates gate
      where gate.project_id = conversation.project_id
    ), '[]'::jsonb),
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'role', history.role,
        'mode', history.mode,
        'content', history.content,
        'created_at', history.created_at
      ) order by history.created_at)
      from (
        select prior.role, prior.mode, prior.content, prior.created_at
        from public.mikkeos_implementation_messages prior
        where prior.conversation_id = conversation.id
          and prior.id <> message.id
          and prior.status = 'completed'
        order by prior.created_at desc
        limit 30
      ) history
    ), '[]'::jsonb)
  from public.mikkeos_implementation_messages message
  join public.mikkeos_implementation_conversations conversation
    on conversation.id = message.conversation_id
  left join public.mikkeos_implementation_projects project
    on project.id = conversation.project_id
  where message.id = claimed_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_create_implementation_conversation"("p_project_id" "uuid", "p_title" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  new_conversation_id uuid;
begin
  if caller_id is null or not exists (
    select 1 from public.mikkeos_hq_staff_members staff
    where staff.user_id = caller_id
      and staff.is_active and staff.role in ('owner', 'admin')
  ) then
    raise exception 'HQ owner or admin access required' using errcode = '42501';
  end if;

  if p_project_id is not null and not exists (
    select 1 from public.mikkeos_implementation_projects project
    where project.id = p_project_id and project.archived_at is null
  ) then
    raise exception 'implementation project not found' using errcode = '22023';
  end if;

  if char_length(trim(coalesce(p_title, ''))) not between 1 and 160 then
    raise exception 'invalid conversation title' using errcode = '22023';
  end if;

  insert into public.mikkeos_implementation_conversations (
    project_id, title, status, created_by, updated_by
  ) values (
    p_project_id, trim(p_title), 'active', caller_id, caller_id
  ) returning id into new_conversation_id;

  return new_conversation_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_finish_consultation"("p_worker_secret" "text", "p_item_id" "uuid", "p_status" "text", "p_result" "text" DEFAULT ''::"text", "p_question" "text" DEFAULT ''::"text", "p_evidence_ref" "text" DEFAULT ''::"text", "p_task_ref" "text" DEFAULT ''::"text", "p_error" "text" DEFAULT ''::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1
    from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary'
      and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;

  if p_status not in ('open', 'waiting_user', 'completed') then
    raise exception 'invalid dispatcher status';
  end if;

  update public.mikkeos_implementation_items item
  set status = p_status,
      result = left(coalesce(p_result, ''), 8000),
      question = left(coalesce(p_question, ''), 2000),
      evidence_ref = left(coalesce(p_evidence_ref, ''), 2000),
      task_ref = left(coalesce(nullif(p_task_ref, ''), item.task_ref), 2000),
      dispatcher_claimed_at = null,
      dispatcher_last_error = left(coalesce(p_error, ''), 2000),
      completed_at = case when p_status = 'completed' then now() else null end,
      updated_at = now()
  where item.id = p_item_id
    and item.item_type = 'consultation'
    and item.status = 'in_progress'
    and item.task_ref like 'dispatcher:%';

  return found;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_finish_conversation_message"("p_worker_secret" "text", "p_message_id" "uuid", "p_status" "text", "p_reply" "text" DEFAULT ''::"text", "p_evidence_ref" "text" DEFAULT ''::"text", "p_codex_thread_id" "text" DEFAULT ''::"text", "p_branch_ref" "text" DEFAULT ''::"text", "p_error" "text" DEFAULT ''::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_conversation_id uuid;
  target_mode text;
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1
    from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary'
      and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;

  if p_status not in ('active', 'waiting_user', 'retry', 'failed') then
    raise exception 'invalid conversation dispatcher status' using errcode = '22023';
  end if;

  select message.conversation_id, message.mode
  into target_conversation_id, target_mode
  from public.mikkeos_implementation_messages message
  where message.id = p_message_id
    and message.role = 'user'
    and message.status = 'in_progress'
  for update;

  if target_conversation_id is null then
    return false;
  end if;

  if p_status = 'retry' then
    update public.mikkeos_implementation_messages
    set status = 'pending',
        dispatcher_claimed_at = null,
        dispatcher_last_error = left(coalesce(p_error, ''), 2000),
        updated_at = now()
    where id = p_message_id;

    update public.mikkeos_implementation_conversations
    set status = 'queued', updated_at = now()
    where id = target_conversation_id;
    return true;
  end if;

  update public.mikkeos_implementation_messages
  set status = case when p_status = 'failed' then 'failed' else 'completed' end,
      dispatcher_claimed_at = null,
      dispatcher_last_error = left(coalesce(p_error, ''), 2000),
      updated_at = now()
  where id = p_message_id;

  insert into public.mikkeos_implementation_messages (
    conversation_id, role, mode, status, content, evidence_ref
  ) values (
    target_conversation_id,
    'assistant',
    target_mode,
    case when p_status = 'failed' then 'failed' else 'completed' end,
    left(coalesce(nullif(trim(p_reply), ''), '応答を完了できませんでした。'), 12000),
    left(coalesce(p_evidence_ref, ''), 4000)
  );

  update public.mikkeos_implementation_conversations
  set status = case when p_status = 'waiting_user' then 'waiting_user' else 'active' end,
      codex_thread_id = left(coalesce(nullif(p_codex_thread_id, ''), codex_thread_id), 200),
      branch_ref = left(coalesce(nullif(p_branch_ref, ''), branch_ref), 300),
      last_response_at = now(),
      last_message_at = now(),
      updated_at = now()
  where id = target_conversation_id;

  return true;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_finish_local_preview"("p_worker_secret" "text", "p_item_id" "uuid", "p_status" "text", "p_url" "text" DEFAULT ''::"text", "p_port" integer DEFAULT NULL::integer, "p_note" "text" DEFAULT ''::"text", "p_error" "text" DEFAULT ''::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_project_id uuid;
  prior_url text;
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1 from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary'
      and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;
  if p_status not in ('starting', 'ready', 'stopped', 'failed')
    or (p_port is not null and p_port not between 3000 and 3999) then
    raise exception 'invalid preview result' using errcode = '22023';
  end if;

  select item.project_id, item.preview_url into target_project_id, prior_url
  from public.mikkeos_implementation_items item
  where item.id = p_item_id and item.item_type = 'local_result'
  for update;
  if not found then return false; end if;

  update public.mikkeos_implementation_items
  set preview_status = p_status,
      preview_requested_action = '',
      preview_url = case when p_status in ('starting', 'ready') then left(coalesce(p_url, ''), 500) else '' end,
      preview_port = case when p_status in ('starting', 'ready') then p_port else null end,
      preview_note = left(coalesce(p_note, ''), 500),
      preview_error = left(coalesce(p_error, ''), 2000),
      preview_started_at = case when p_status = 'ready' then coalesce(preview_started_at, now()) when p_status in ('stopped', 'failed') then null else preview_started_at end,
      updated_at = now()
  where id = p_item_id;

  if p_status = 'ready' and target_project_id is not null then
    update public.mikkeos_implementation_projects
    set local_verify_url = left(coalesce(p_url, ''), 500), updated_at = now()
    where id = target_project_id;
  elsif p_status in ('stopped', 'failed') and target_project_id is not null then
    update public.mikkeos_implementation_projects
    set local_verify_url = '' , updated_at = now()
    where id = target_project_id and local_verify_url = prior_url;
  end if;
  return true;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_get_message_attachments"("p_worker_secret" "text", "p_message_id" "uuid") RETURNS TABLE("attachment_id" "uuid", "file_name" "text", "mime_type" "text", "worker_url" "text", "worker_url_expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1 from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary' and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;

  return query
  select attachment.id, attachment.file_name, attachment.mime_type, attachment.worker_url, attachment.worker_url_expires_at
  from public.mikkeos_implementation_attachments attachment
  where attachment.message_id = p_message_id
  order by attachment.created_at;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_hq_journal_touch_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_hq_journal_write_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  audit_details jsonb;
begin
  if tg_table_name = 'mikkeos_hq_article_categories' then
    if tg_op = 'INSERT' then
      audit_details := jsonb_build_object('slug', new.slug);
    else
      audit_details := jsonb_build_object('is_active', new.is_active);
    end if;
  else
    audit_details := jsonb_build_object('status', new.status, 'slug', new.slug);
  end if;

  insert into public.mikkeos_hq_audit_logs (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    details
  ) values (
    (select auth.uid()),
    lower(tg_op),
    tg_table_name,
    new.id,
    audit_details
  );

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_public_journal_article"("p_slug" "text") RETURNS TABLE("id" "uuid", "category_id" "uuid", "slug" "text", "title" "text", "excerpt" "text", "cover_image_url" "text", "blocks" "jsonb", "is_featured" boolean, "cta_label" "text", "cta_url" "text", "published_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "category_name" "text", "category_slug" "text", "category_color" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    article.id,
    article.category_id,
    article.slug,
    article.title,
    article.excerpt,
    article.cover_image_url,
    article.blocks,
    article.is_featured,
    article.cta_label,
    article.cta_url,
    article.published_at,
    article.created_at,
    article.updated_at,
    category.name,
    category.slug,
    category.color
  from public.mikkeos_hq_articles article
  left join public.mikkeos_hq_article_categories category
    on category.id = article.category_id
   and category.is_active
  where article.status = 'published'
    and article.published_at <= now()
    and article.slug = lower(btrim(p_slug))
  limit 1;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_public_journal_articles"("p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "category_id" "uuid", "slug" "text", "title" "text", "excerpt" "text", "cover_image_url" "text", "blocks" "jsonb", "is_featured" boolean, "cta_label" "text", "cta_url" "text", "published_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "category_name" "text", "category_slug" "text", "category_color" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    article.id,
    article.category_id,
    article.slug,
    article.title,
    article.excerpt,
    article.cover_image_url,
    article.blocks,
    article.is_featured,
    article.cta_label,
    article.cta_url,
    article.published_at,
    article.created_at,
    article.updated_at,
    category.name,
    category.slug,
    category.color
  from public.mikkeos_hq_articles article
  left join public.mikkeos_hq_article_categories category
    on category.id = article.category_id
   and category.is_active
  where article.status = 'published'
    and article.published_at <= now()
  order by article.is_featured desc, article.published_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 50));
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_record_conversation_detail"("p_worker_secret" "text", "p_user_message_id" "uuid", "p_summary" "text" DEFAULT ''::"text", "p_detail" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  assistant_message_id uuid;
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1 from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary'
      and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;
  if jsonb_typeof(coalesce(p_detail, '{}'::jsonb)) <> 'object' or pg_column_size(coalesce(p_detail, '{}'::jsonb)) > 65536 then
    raise exception 'invalid response detail' using errcode = '22023';
  end if;

  select response.id into assistant_message_id
  from public.mikkeos_implementation_messages source
  join public.mikkeos_implementation_messages response
    on response.conversation_id = source.conversation_id
   and response.role = 'assistant'
   and response.created_at >= source.created_at
  where source.id = p_user_message_id and source.role = 'user'
  order by response.created_at desc
  limit 1;
  if assistant_message_id is null then return false; end if;

  update public.mikkeos_implementation_messages
  set response_summary = left(coalesce(p_summary, ''), 1000),
      response_detail = coalesce(p_detail, '{}'::jsonb),
      updated_at = now()
  where id = assistant_message_id;
  return true;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_record_conversation_outcomes"("p_worker_secret" "text", "p_message_id" "uuid", "p_decision_question" "text" DEFAULT ''::"text", "p_recommended_execution" "text" DEFAULT ''::"text", "p_updates" "jsonb" DEFAULT '[]'::"jsonb", "p_handoffs" "jsonb" DEFAULT '[]'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source_conversation_id uuid;
  source_project_id uuid;
  assistant_message_id uuid;
  entry jsonb;
  target_project_id uuid;
  lane text;
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1 from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary' and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;

  select message.conversation_id, conversation.project_id
  into source_conversation_id, source_project_id
  from public.mikkeos_implementation_messages message
  join public.mikkeos_implementation_conversations conversation on conversation.id = message.conversation_id
  where message.id = p_message_id and message.role = 'user';

  if source_conversation_id is null then
    return false;
  end if;

  select response.id into assistant_message_id
  from public.mikkeos_implementation_messages response
  where response.conversation_id = source_conversation_id
    and response.role = 'assistant'
    and response.created_at >= (select created_at from public.mikkeos_implementation_messages where id = p_message_id)
  order by response.created_at desc limit 1;

  update public.mikkeos_implementation_messages
  set decision_question = left(coalesce(p_decision_question, ''), 1000),
      recommended_execution = left(coalesce(p_recommended_execution, ''), 12000),
      updated_at = now()
  where id = assistant_message_id;

  for entry in select value from jsonb_array_elements(coalesce(p_updates, '[]'::jsonb))
  loop
    lane := entry->>'lane';
    if lane not in ('request', 'proposal', 'local_result', 'production_result') then
      continue;
    end if;
    select id into target_project_id
    from public.mikkeos_implementation_projects
    where app_key = coalesce(nullif(entry->>'app_key', ''), (select app_key from public.mikkeos_implementation_projects where id = source_project_id))
      and archived_at is null;
    target_project_id := coalesce(target_project_id, source_project_id);

    insert into public.mikkeos_implementation_items (
      project_id, origin_project_id, source_conversation_id, source_message_id,
      item_type, status, priority, title, body, result, evidence_ref,
      local_verify_url, production_url
    ) values (
      target_project_id, source_project_id, source_conversation_id, p_message_id,
      lane,
      case when lane in ('local_result', 'production_result') then 'completed' else 'open' end,
      'normal', left(coalesce(nullif(entry->>'title', ''), 'Codexからの更新'), 160),
      left(coalesce(entry->>'summary', ''), 8000),
      case when lane in ('local_result', 'production_result') then left(coalesce(entry->>'summary', ''), 8000) else '' end,
      left(coalesce(entry->>'evidence_ref', ''), 2000),
      left(coalesce(entry->>'local_verify_url', ''), 2000),
      left(coalesce(entry->>'production_url', ''), 2000)
    );
  end loop;

  for entry in select value from jsonb_array_elements(coalesce(p_handoffs, '[]'::jsonb))
  loop
    select id into target_project_id
    from public.mikkeos_implementation_projects
    where app_key = entry->>'app_key' and archived_at is null;
    if target_project_id is null then
      continue;
    end if;

    insert into public.mikkeos_implementation_items (
      project_id, origin_project_id, source_conversation_id, source_message_id,
      item_type, status, priority, title, body, task_ref
    ) values (
      target_project_id, source_project_id, source_conversation_id, p_message_id,
      'handoff', 'open', 'normal',
      left(coalesce(nullif(entry->>'title', ''), '他アプリからの連携依頼'), 160),
      left(coalesce(entry->>'request', ''), 8000),
      left(coalesce(entry->>'room', ''), 2000)
    );
  end loop;

  update public.mikkeos_implementation_conversations
  set progress_stage = '', progress_note = '', progress_updated_at = now(), updated_at = now()
  where id = source_conversation_id;

  return true;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_request_local_preview"("p_item_id" "uuid", "p_action" "text" DEFAULT 'start'::"text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
begin
  if caller_id is null or not exists (
    select 1 from public.mikkeos_hq_staff_members staff
    where staff.user_id = caller_id
      and staff.is_active and staff.role in ('owner', 'admin')
  ) then
    raise exception 'HQ owner or admin access required' using errcode = '42501';
  end if;

  if p_action not in ('start', 'stop') then
    raise exception 'invalid preview action' using errcode = '22023';
  end if;

  update public.mikkeos_implementation_items item
  set preview_status = case when p_action = 'start' then 'queued' else 'stopping' end,
      preview_requested_action = p_action,
      preview_note = case when p_action = 'start' then 'ローカルUIの起動を受け付けました。' else 'ローカルUIの停止を受け付けました。' end,
      preview_error = '',
      preview_requested_at = now(),
      updated_by = caller_id,
      updated_at = now()
  where item.id = p_item_id
    and item.item_type = 'local_result'
    and item.archived_at is null
    and (p_action = 'stop' or item.local_path <> '');

  if not found then
    raise exception 'previewable local result not found' using errcode = '22023';
  end if;
  return true;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_send_implementation_message"("p_conversation_id" "uuid", "p_mode" "text", "p_content" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  new_message_id uuid;
begin
  if caller_id is null or not exists (
    select 1 from public.mikkeos_hq_staff_members staff
    where staff.user_id = caller_id
      and staff.is_active
      and staff.role in ('owner', 'admin')
  ) then
    raise exception 'HQ owner or admin access required' using errcode = '42501';
  end if;

  if p_mode not in ('discussion', 'execution')
    or char_length(trim(coalesce(p_content, ''))) not between 1 and 12000 then
    raise exception 'invalid message content' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.mikkeos_implementation_conversations conversation
    where conversation.id = p_conversation_id
      and conversation.archived_at is null
  ) then
    raise exception 'active conversation not found' using errcode = '22023';
  end if;

  insert into public.mikkeos_implementation_messages (
    conversation_id, role, mode, status, content, created_by
  ) values (
    p_conversation_id, 'user', p_mode, 'pending', trim(p_content), caller_id
  ) returning id into new_message_id;

  update public.mikkeos_implementation_conversations
  set status = 'queued',
      updated_by = caller_id,
      last_message_at = now(),
      updated_at = now()
  where id = p_conversation_id;

  return new_message_id;
exception
  when unique_violation then
    raise exception 'Codexの返答を待ってから次のメッセージを送ってください。' using errcode = '55000';
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_send_implementation_message_v2"("p_conversation_id" "uuid", "p_mode" "text", "p_content" "text", "p_attachment_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  new_message_id uuid;
  requested_attachments integer := coalesce(cardinality(p_attachment_ids), 0);
  owned_attachments integer;
begin
  if caller_id is null or not exists (
    select 1 from public.mikkeos_hq_staff_members staff
    where staff.user_id = caller_id
      and staff.is_active and staff.role in ('owner', 'admin')
  ) then
    raise exception 'HQ owner or admin access required' using errcode = '42501';
  end if;

  if p_mode not in ('discussion', 'execution')
    or char_length(trim(coalesce(p_content, ''))) not between 1 and 12000
    or requested_attachments > 3 then
    raise exception 'invalid message content' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.mikkeos_implementation_conversations conversation
    where conversation.id = p_conversation_id and conversation.archived_at is null
  ) then
    raise exception 'active conversation not found' using errcode = '22023';
  end if;

  select count(*) into owned_attachments
  from public.mikkeos_implementation_attachments attachment
  where attachment.id = any(coalesce(p_attachment_ids, array[]::uuid[]))
    and attachment.conversation_id = p_conversation_id
    and attachment.created_by = caller_id
    and attachment.message_id is null
    and attachment.worker_url_expires_at > now();

  if owned_attachments <> requested_attachments then
    raise exception 'invalid or expired attachment' using errcode = '22023';
  end if;

  insert into public.mikkeos_implementation_messages (
    conversation_id, role, mode, status, content, created_by
  ) values (
    p_conversation_id, 'user', p_mode, 'pending', trim(p_content), caller_id
  ) returning id into new_message_id;

  update public.mikkeos_implementation_attachments
  set message_id = new_message_id
  where id = any(coalesce(p_attachment_ids, array[]::uuid[]));

  update public.mikkeos_implementation_conversations
  set status = 'queued', progress_stage = 'queued', progress_note = '相談を受け付けました。',
      progress_updated_at = now(), updated_by = caller_id,
      last_message_at = now(), updated_at = now()
  where id = p_conversation_id;

  return new_message_id;
exception
  when unique_violation then
    raise exception 'Codexの返答を待ってから次のメッセージを送ってください。' using errcode = '55000';
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_set_conversation_progress"("p_worker_secret" "text", "p_conversation_id" "uuid", "p_stage" "text", "p_note" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1 from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary' and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;

  if p_stage not in ('queued', 'preparing', 'inspecting', 'planning', 'composing', 'saving') then
    raise exception 'invalid progress stage' using errcode = '22023';
  end if;

  update public.mikkeos_implementation_conversations
  set progress_stage = p_stage,
      progress_note = left(coalesce(p_note, ''), 240),
      progress_updated_at = now(), updated_at = now()
  where id = p_conversation_id and archived_at is null;
  return found;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_start_implementation_conversation"("p_project_id" "uuid", "p_title" "text", "p_content" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  new_conversation_id uuid;
begin
  if caller_id is null or not exists (
    select 1 from public.mikkeos_hq_staff_members staff
    where staff.user_id = caller_id
      and staff.is_active
      and staff.role in ('owner', 'admin')
  ) then
    raise exception 'HQ owner or admin access required' using errcode = '42501';
  end if;

  if p_project_id is not null and not exists (
    select 1 from public.mikkeos_implementation_projects project
    where project.id = p_project_id and project.archived_at is null
  ) then
    raise exception 'implementation project not found' using errcode = '22023';
  end if;

  if char_length(trim(coalesce(p_title, ''))) not between 1 and 160
    or char_length(trim(coalesce(p_content, ''))) not between 1 and 12000 then
    raise exception 'invalid conversation content' using errcode = '22023';
  end if;

  insert into public.mikkeos_implementation_conversations (
    project_id, title, status, created_by, updated_by
  ) values (
    p_project_id, trim(p_title), 'queued', caller_id, caller_id
  ) returning id into new_conversation_id;

  insert into public.mikkeos_implementation_messages (
    conversation_id, role, mode, status, content, created_by
  ) values (
    new_conversation_id, 'user', 'discussion', 'pending', trim(p_content), caller_id
  );

  return new_conversation_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mikkeos_sync_local_inventory"("p_worker_secret" "text", "p_snapshots" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  snapshot jsonb;
  target_project_id uuid;
  changed_count integer := 0;
  stable_key text;
  snapshot_files jsonb;
begin
  if p_worker_secret is null or char_length(p_worker_secret) < 32 or not exists (
    select 1 from private.mikkeos_dispatcher_credentials credential
    where credential.credential_key = 'primary' and credential.is_active
      and credential.secret_sha256 = encode(extensions.digest(p_worker_secret, 'sha256'), 'hex')
  ) then
    raise exception 'dispatcher authentication failed' using errcode = '28000';
  end if;

  if jsonb_typeof(coalesce(p_snapshots, '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(p_snapshots, '[]'::jsonb)) > 80 then
    raise exception 'invalid inventory payload' using errcode = '22023';
  end if;

  for snapshot in select value from jsonb_array_elements(coalesce(p_snapshots, '[]'::jsonb))
  loop
    select id into target_project_id
    from public.mikkeos_implementation_projects
    where app_key = snapshot->>'app_key' and archived_at is null;
    if target_project_id is null then continue; end if;

    snapshot_files := case
      when jsonb_typeof(snapshot->'changed_files') = 'array' then snapshot->'changed_files'
      else '[]'::jsonb
    end;
    stable_key := 'worktree:' || left(encode(extensions.digest(
      coalesce(snapshot->>'branch', '') || '|' || coalesce(snapshot->>'path', ''), 'sha256'
    ), 'hex'), 48);

    insert into public.mikkeos_implementation_items as current_item (
      project_id, item_type, status, priority, title, result, evidence_ref, inventory_key,
      local_path, local_branch, local_head, changed_files
    ) values (
      target_project_id,
      'local_result',
      case when coalesce((snapshot->>'dirty')::boolean, false) then 'in_progress' else 'completed' end,
      'normal',
      left(case when coalesce((snapshot->>'dirty')::boolean, false) then 'ローカル作業中: ' else 'ローカルコミット済み: ' end || coalesce(snapshot->>'branch', 'detached'), 160),
      left(coalesce(snapshot->>'summary', ''), 8000),
      left('branch=' || coalesce(snapshot->>'branch', '') || ' / head=' || coalesce(snapshot->>'head', '') || ' / path=' || coalesce(snapshot->>'path', ''), 2000),
      stable_key,
      left(coalesce(snapshot->>'path', ''), 1000),
      left(coalesce(snapshot->>'branch', ''), 500),
      left(coalesce(snapshot->>'head', ''), 100),
      snapshot_files
    )
    on conflict (inventory_key) where inventory_key <> '' and archived_at is null do update
    set status = excluded.status,
        title = excluded.title,
        result = excluded.result,
        evidence_ref = excluded.evidence_ref,
        local_path = excluded.local_path,
        local_branch = excluded.local_branch,
        local_head = excluded.local_head,
        changed_files = excluded.changed_files,
        updated_at = now();

    update public.mikkeos_implementation_projects
    set local_state = case when coalesce((snapshot->>'dirty')::boolean, false) then 'in_progress' else 'implemented' end,
        local_evidence_ref = left('branch=' || coalesce(snapshot->>'branch', '') || ' / head=' || coalesce(snapshot->>'head', '') || ' / path=' || coalesce(snapshot->>'path', ''), 2000),
        branch_ref = coalesce(nullif(snapshot->>'branch', ''), branch_ref),
        updated_at = now()
    where id = target_project_id;
    changed_count := changed_count + 1;
  end loop;

  return changed_count;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."nintei_koza_prepare_textbook_fulfillment"("p_provider" "text", "p_provider_event_id" "text", "p_checkout_session_id" "text", "p_provider_payment_id" "text", "p_payment_link_id" "text", "p_customer_email" "text", "p_referral" "text", "p_amount" integer, "p_currency" "text", "p_livemode" boolean, "p_owner_user_id" "uuid") RETURNS TABLE("fulfillment_id" "uuid", "purchase_code" "text", "conversion_id" "uuid", "email_status" "text", "already_completed" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_fulfillment public.nintei_koza_fulfillments%rowtype;
  v_referral public.nintei_koza_referrers%rowtype;
  v_code text;
  v_alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  v_random bytea;
  v_reward_due boolean := false;
  v_reward_amount integer := null;
  v_attempt integer;
  v_position integer;
  v_was_inserted boolean := false;
begin
  if p_provider <> 'stripe' then
    raise exception 'unsupported provider';
  end if;
  if nullif(btrim(p_provider_event_id), '') is null
    or nullif(btrim(p_checkout_session_id), '') is null
    or nullif(btrim(p_payment_link_id), '') is null then
    raise exception 'missing provider identifiers';
  end if;
  if p_amount <> 39800 or upper(p_currency) <> 'JPY' then
    raise exception 'unexpected textbook payment';
  end if;
  if p_customer_email is null or btrim(p_customer_email) !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception 'invalid purchaser email';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_provider || ':' || p_checkout_session_id, 0));

  insert into public.nintei_koza_fulfillments (
    provider,
    provider_event_id,
    checkout_session_id,
    provider_payment_id,
    payment_link_id,
    product,
    customer_email,
    amount,
    currency,
    livemode
  ) values (
    p_provider,
    btrim(p_provider_event_id),
    btrim(p_checkout_session_id),
    nullif(btrim(p_provider_payment_id), ''),
    btrim(p_payment_link_id),
    'textbook',
    lower(btrim(p_customer_email)),
    p_amount,
    upper(p_currency),
    p_livemode
  )
  on conflict do nothing
  returning true into v_was_inserted;

  select *
  into v_fulfillment
  from public.nintei_koza_fulfillments
  where provider = p_provider
    and (provider_event_id = btrim(p_provider_event_id) or checkout_session_id = btrim(p_checkout_session_id))
  order by (provider_event_id = btrim(p_provider_event_id)) desc
  limit 1
  for update;

  if v_fulfillment.id is null then
    raise exception 'could not claim fulfillment';
  end if;

  update public.nintei_koza_fulfillments as fulfillment
  set attempt_count = attempt_count + case when coalesce(v_was_inserted, false) then 0 else 1 end,
      last_received_at = now(),
      updated_at = now()
  where id = v_fulfillment.id
  returning * into v_fulfillment;

  if v_fulfillment.email_status = 'sent' then
    return query select v_fulfillment.id, v_fulfillment.purchase_code,
      v_fulfillment.conversion_id, v_fulfillment.email_status, true;
    return;
  end if;

  select *
  into v_referral
  from public.nintei_koza_referrers
  where code = lower(btrim(coalesce(p_referral, '')))
    and active
  limit 1;

  if v_referral.code is not null then
    v_reward_due := v_referral.reward_textbook;
    if v_reward_due and v_referral.reward_textbook_amount > 0 then
      v_reward_amount := v_referral.reward_textbook_amount;
    end if;
  end if;

  if v_fulfillment.purchase_code is null then
    for v_attempt in 1..8 loop
      v_code := '';
      for v_position in 1..8 loop
        v_random := extensions.gen_random_bytes(1);
        v_code := v_code || substr(v_alphabet, 1 + (get_byte(v_random, 0) % char_length(v_alphabet)), 1);
      end loop;
      begin
        insert into public.nintei_koza_purchases (
          code, email, role, active, issued_for, note, owner_user_id
        ) values (
          v_code,
          lower(btrim(p_customer_email)),
          'textbook',
          true,
          'stripe-auto',
          'Stripe自動発行 / メール送信準備中 / session ' || btrim(p_checkout_session_id),
          p_owner_user_id
        );
        exit;
      exception when unique_violation then
        if v_attempt = 8 then
          raise;
        end if;
      end;
    end loop;
    v_fulfillment.purchase_code := v_code;
  end if;

  if v_fulfillment.conversion_id is null then
    insert into public.nintei_koza_conversions (
      product,
      amount,
      referral,
      reward_due,
      reward_amount,
      note,
      owner_user_id
    ) values (
      'textbook',
      p_amount,
      v_referral.code,
      v_reward_due,
      v_reward_amount,
      'Stripe自動登録 / session ' || btrim(p_checkout_session_id) || ' / event ' || btrim(p_provider_event_id),
      p_owner_user_id
    )
    returning id into v_fulfillment.conversion_id;
  end if;

  update public.nintei_koza_fulfillments as fulfillment
  set referral = v_referral.code,
      purchase_code = v_fulfillment.purchase_code,
      conversion_id = v_fulfillment.conversion_id,
      fulfillment_status = 'ready_to_email',
      email_status = case when fulfillment.email_status = 'sent' then 'sent' else 'pending' end,
      last_error = null,
      updated_at = now()
  where fulfillment.id = v_fulfillment.id
  returning fulfillment.* into v_fulfillment;

  return query select v_fulfillment.id, v_fulfillment.purchase_code,
    v_fulfillment.conversion_id, v_fulfillment.email_status, false;
end;
$_$;




COMMENT ON FUNCTION "public"."nintei_koza_prepare_textbook_fulfillment"("p_provider" "text", "p_provider_event_id" "text", "p_checkout_session_id" "text", "p_provider_payment_id" "text", "p_payment_link_id" "text", "p_customer_email" "text", "p_referral" "text", "p_amount" integer, "p_currency" "text", "p_livemode" boolean, "p_owner_user_id" "uuid") IS 'Atomically creates one textbook code and one conversion for one verified Stripe checkout.';



CREATE OR REPLACE FUNCTION "public"."profiles_guard_handle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.handle is not null and btrim(new.handle) <> '' then
      new.handle := public.mikke_normalize_mikke_id(new.handle, null);
    end if;
    return new;
  end if;

  if new.handle is distinct from old.handle then
    new.handle := public.mikke_normalize_mikke_id(new.handle, old.handle);
  end if;

  return new;
end;
$$;




COMMENT ON FUNCTION "public"."profiles_guard_handle"() IS 'profiles.handle に入る値を、経路に関係なく mikke_normalize_mikke_id で検査・正規化する。';



