CREATE OR REPLACE FUNCTION "public"."revoke_fund_support_claim"("p_claim_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  update public.fund_support_claims
  set revoked_at = now()
  where id = p_claim_id
    and accepted_at is null
    and revoked_at is null
    and exists (
      select 1
      from public.fund_supports
      join public.fund_projects on fund_projects.id = fund_supports.project_id
      where fund_supports.id = fund_support_claims.support_id
        and fund_projects.owner_user_id = v_actor
    );

  if not found then
    raise exception 'active claim not found' using errcode = '42501';
  end if;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."save_fund_completion"("p_owner_profile_id" "uuid", "p_project_source_local_id" "text", "p_record" "jsonb", "p_targets" "text"[] DEFAULT ARRAY[]::"text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_project_id uuid;
  v_record_id uuid;
  v_source_local_id text := nullif(btrim(p_record ->> 'id'), '');
  v_title text := nullif(btrim(p_record ->> 'title'), '');
  v_summary text := nullif(btrim(p_record ->> 'summary'), '');
  v_completed_at date := nullif(btrim(p_record ->> 'completedAt'), '')::date;
begin
  if v_actor_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if nullif(btrim(p_project_source_local_id), '') is null
    or v_source_local_id is null
    or v_title is null
    or v_summary is null
    or v_completed_at is null then
    raise exception 'Project id, completion id, title, summary, and completed date are required' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.profiles
    where id = p_owner_profile_id and user_id = v_actor_user_id
  ) then
    raise exception 'Owner profile does not belong to the authenticated user' using errcode = '42501';
  end if;

  select id into v_project_id
  from public.fund_projects
  where owner_user_id = v_actor_user_id
    and owner_profile_id = p_owner_profile_id
    and source_local_id = btrim(p_project_source_local_id)
  for update;
  if v_project_id is null then
    raise exception 'Fund project was not found for the authenticated owner' using errcode = '42501';
  end if;

  update public.fund_projects
  set stage = 'realization',
      status = 'completed',
      completed_at = v_completed_at::timestamp at time zone 'UTC'
  where id = v_project_id;

  select id into v_record_id
  from public.fund_challenge_records
  where project_id = v_project_id;

  if v_record_id is null then
    insert into public.fund_challenge_records (
      project_id, source_local_id, title, summary, outcome, image_url,
      visibility, story_enabled, completed_at
    ) values (
      v_project_id, v_source_local_id, v_title, v_summary,
      coalesce(p_record ->> 'outcome', ''), coalesce(p_record ->> 'imageUrl', ''),
      coalesce(p_record ->> 'visibility', 'private'),
      coalesce((p_record ->> 'storyEnabled')::boolean, false), v_completed_at
    ) returning id into v_record_id;
  else
    update public.fund_challenge_records
    set title = v_title,
        summary = v_summary,
        outcome = coalesce(p_record ->> 'outcome', ''),
        image_url = coalesce(p_record ->> 'imageUrl', ''),
        visibility = coalesce(p_record ->> 'visibility', 'private'),
        story_enabled = coalesce((p_record ->> 'storyEnabled')::boolean, false),
        completed_at = v_completed_at
    where id = v_record_id;
  end if;

  update public.fund_app_links
  set link_status = 'cancelled'
  where project_id = v_project_id
    and not (target_service = any(coalesce(p_targets, array[]::text[])));

  insert into public.fund_app_links (project_id, target_service, link_status)
  select v_project_id, target_service, 'ready'
  from (
    select distinct btrim(value) as target_service
    from unnest(coalesce(p_targets, array[]::text[])) as target(value)
    where nullif(btrim(value), '') is not null
  ) selected_targets
  on conflict (project_id, target_service) do update set link_status = 'ready';

  return v_record_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."save_fund_project_content"("p_owner_profile_id" "uuid", "p_project" "jsonb", "p_plans" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_project_id uuid;
  v_source_local_id text := nullif(btrim(p_project ->> 'id'), '');
  v_visibility text := p_project ->> 'visibility';
  v_status text := p_project ->> 'status';
  v_plan jsonb;
begin
  if v_actor_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if v_source_local_id is null then
    raise exception 'Project local id is required' using errcode = '22023';
  end if;
  if jsonb_typeof(p_plans) <> 'array' then
    raise exception 'Plans must be a JSON array' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.profiles
    where id = p_owner_profile_id and user_id = v_actor_user_id
  ) then
    raise exception 'Owner profile does not belong to the authenticated user' using errcode = '42501';
  end if;

  select id into v_project_id
  from public.fund_projects
  where owner_user_id = v_actor_user_id
    and source_local_id = v_source_local_id;

  if v_project_id is null then
    insert into public.fund_projects (
      owner_user_id, owner_profile_id, source_local_id, slug, title,
      visibility, status, short_description, description, project_type,
      campaign_type, stage, cover_image_url, goal_type, goal_value,
      display_amount, start_at, end_at, external_payment_url,
      external_application_url, why_now, audience, use_of_support,
      schedule, risk_notes, cancellation_policy, contact_note,
      published_at, completed_at, archived_at
    ) values (
      v_actor_user_id, p_owner_profile_id, v_source_local_id,
      p_project ->> 'slug', p_project ->> 'title', v_visibility, v_status,
      coalesce(p_project ->> 'shortDescription', ''),
      coalesce(p_project ->> 'description', ''),
      p_project ->> 'projectType', p_project ->> 'campaignType',
      p_project ->> 'stage', coalesce(p_project ->> 'coverImageUrl', ''),
      p_project ->> 'goalType', (p_project ->> 'goalValue')::numeric,
      coalesce((p_project ->> 'displayAmount')::boolean, false),
      nullif(p_project ->> 'startAt', '')::date,
      nullif(p_project ->> 'endAt', '')::date,
      coalesce(p_project ->> 'externalPaymentUrl', ''),
      coalesce(p_project ->> 'externalApplicationUrl', ''),
      coalesce(p_project ->> 'whyNow', ''), coalesce(p_project ->> 'audience', ''),
      coalesce(p_project ->> 'useOfSupport', ''), coalesce(p_project ->> 'schedule', ''),
      coalesce(p_project ->> 'riskNotes', ''),
      coalesce(p_project ->> 'cancellationPolicy', ''),
      coalesce(p_project ->> 'contactNote', ''),
      case when v_visibility = 'public' and v_status <> 'draft' then now() else null end,
      case when v_status = 'completed' then now() else null end,
      case when v_status = 'archived' then now() else null end
    ) returning id into v_project_id;
  else
    update public.fund_projects
    set owner_profile_id = p_owner_profile_id,
        slug = p_project ->> 'slug',
        title = p_project ->> 'title',
        visibility = v_visibility,
        status = v_status,
        short_description = coalesce(p_project ->> 'shortDescription', ''),
        description = coalesce(p_project ->> 'description', ''),
        project_type = p_project ->> 'projectType',
        campaign_type = p_project ->> 'campaignType',
        stage = p_project ->> 'stage',
        cover_image_url = coalesce(p_project ->> 'coverImageUrl', ''),
        goal_type = p_project ->> 'goalType',
        goal_value = (p_project ->> 'goalValue')::numeric,
        display_amount = coalesce((p_project ->> 'displayAmount')::boolean, false),
        start_at = nullif(p_project ->> 'startAt', '')::date,
        end_at = nullif(p_project ->> 'endAt', '')::date,
        external_payment_url = coalesce(p_project ->> 'externalPaymentUrl', ''),
        external_application_url = coalesce(p_project ->> 'externalApplicationUrl', ''),
        why_now = coalesce(p_project ->> 'whyNow', ''),
        audience = coalesce(p_project ->> 'audience', ''),
        use_of_support = coalesce(p_project ->> 'useOfSupport', ''),
        schedule = coalesce(p_project ->> 'schedule', ''),
        risk_notes = coalesce(p_project ->> 'riskNotes', ''),
        cancellation_policy = coalesce(p_project ->> 'cancellationPolicy', ''),
        contact_note = coalesce(p_project ->> 'contactNote', ''),
        published_at = case
          when v_visibility = 'public' and v_status <> 'draft' then coalesce(published_at, now())
          else published_at
        end,
        completed_at = case when v_status = 'completed' then coalesce(completed_at, now()) else completed_at end,
        archived_at = case when v_status = 'archived' then coalesce(archived_at, now()) else archived_at end
    where id = v_project_id;
  end if;

  delete from public.fund_plans where project_id = v_project_id;

  for v_plan in select value from jsonb_array_elements(p_plans)
  loop
    if nullif(btrim(v_plan ->> 'id'), '') is null
      or nullif(btrim(v_plan ->> 'title'), '') is null then
      raise exception 'Each plan requires id and title' using errcode = '22023';
    end if;

    insert into public.fund_plans (
      project_id, source_local_id, title, description, image_url, plan_type,
      price, quantity_limit, per_person_limit, delivery_date,
      external_payment_url, external_application_url,
      required_information_note, requires_shipping, status, sort_order
    ) values (
      v_project_id, v_plan ->> 'id', v_plan ->> 'title',
      coalesce(v_plan ->> 'description', ''), coalesce(v_plan ->> 'imageUrl', ''),
      v_plan ->> 'planType', nullif(v_plan ->> 'price', '')::numeric,
      nullif(v_plan ->> 'quantityLimit', '')::integer,
      nullif(v_plan ->> 'perPersonLimit', '')::integer,
      nullif(v_plan ->> 'deliveryDate', '')::date,
      coalesce(v_plan ->> 'externalPaymentUrl', ''),
      coalesce(v_plan ->> 'externalApplicationUrl', ''),
      coalesce(v_plan ->> 'requiredInformationNote', ''),
      coalesce((v_plan ->> 'requiresShipping')::boolean, false),
      v_plan ->> 'status', coalesce((v_plan ->> 'sortOrder')::integer, 0)
    );
  end loop;

  return v_project_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."save_fund_support"("p_owner_profile_id" "uuid", "p_project_source_local_id" "text", "p_support" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_project_id uuid;
  v_support_id uuid;
  v_source_local_id text := nullif(btrim(p_support ->> 'id'), '');
  v_supporter_name text := nullif(btrim(p_support ->> 'supporterName'), '');
  v_supported_at text := nullif(btrim(p_support ->> 'supportedAt'), '');
begin
  if v_actor_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if nullif(btrim(p_project_source_local_id), '') is null
    or v_source_local_id is null
    or v_supporter_name is null
    or v_supported_at is null then
    raise exception 'Project id, support id, supporter name, and supported date are required' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.profiles
    where id = p_owner_profile_id and user_id = v_actor_user_id
  ) then
    raise exception 'Owner profile does not belong to the authenticated user' using errcode = '42501';
  end if;

  select id into v_project_id
  from public.fund_projects
  where owner_user_id = v_actor_user_id
    and owner_profile_id = p_owner_profile_id
    and source_local_id = btrim(p_project_source_local_id);

  if v_project_id is null then
    raise exception 'Fund project was not found for the authenticated owner' using errcode = '42501';
  end if;

  select id into v_support_id
  from public.fund_supports
  where project_id = v_project_id and source_local_id = v_source_local_id;

  if v_support_id is null then
    insert into public.fund_supports (
      project_id, source_local_id, plan_source_id,
      supporter_name, supporter_email, public_name, is_anonymous, comment,
      support_type, amount, quantity, payment_status, fulfillment_status,
      record_status, source, supported_at
    ) values (
      v_project_id, v_source_local_id, nullif(btrim(p_support ->> 'planId'), ''),
      v_supporter_name, nullif(btrim(p_support ->> 'supporterEmail'), ''),
      coalesce(p_support ->> 'publicName', ''),
      coalesce((p_support ->> 'isAnonymous')::boolean, false),
      coalesce(p_support ->> 'comment', ''),
      p_support ->> 'supportType', nullif(p_support ->> 'amount', '')::numeric,
      (p_support ->> 'quantity')::integer, p_support ->> 'paymentStatus',
      p_support ->> 'fulfillmentStatus', p_support ->> 'recordStatus',
      coalesce(nullif(btrim(p_support ->> 'source'), ''), 'manual'),
      v_supported_at::timestamptz
    ) returning id into v_support_id;
  else
    update public.fund_supports
    set plan_source_id = nullif(btrim(p_support ->> 'planId'), ''),
        supporter_name = v_supporter_name,
        supporter_email = nullif(btrim(p_support ->> 'supporterEmail'), ''),
        public_name = coalesce(p_support ->> 'publicName', ''),
        is_anonymous = coalesce((p_support ->> 'isAnonymous')::boolean, false),
        comment = coalesce(p_support ->> 'comment', ''),
        support_type = p_support ->> 'supportType',
        amount = nullif(p_support ->> 'amount', '')::numeric,
        quantity = (p_support ->> 'quantity')::integer,
        payment_status = p_support ->> 'paymentStatus',
        fulfillment_status = p_support ->> 'fulfillmentStatus',
        record_status = p_support ->> 'recordStatus',
        source = coalesce(nullif(btrim(p_support ->> 'source'), ''), 'manual'),
        supported_at = v_supported_at::timestamptz
    where id = v_support_id;
  end if;

  return v_support_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."save_fund_update"("p_owner_profile_id" "uuid", "p_project_source_local_id" "text", "p_update" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_project_id uuid;
  v_update_id uuid;
  v_source_local_id text := nullif(btrim(p_update ->> 'id'), '');
  v_title text := nullif(btrim(p_update ->> 'title'), '');
  v_body text := nullif(btrim(p_update ->> 'body'), '');
begin
  if v_actor_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if nullif(btrim(p_project_source_local_id), '') is null
    or v_source_local_id is null
    or v_title is null
    or v_body is null then
    raise exception 'Project id, update id, title, and body are required' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.profiles
    where id = p_owner_profile_id and user_id = v_actor_user_id
  ) then
    raise exception 'Owner profile does not belong to the authenticated user' using errcode = '42501';
  end if;

  select id into v_project_id
  from public.fund_projects
  where owner_user_id = v_actor_user_id
    and owner_profile_id = p_owner_profile_id
    and source_local_id = btrim(p_project_source_local_id);

  if v_project_id is null then
    raise exception 'Fund project was not found for the authenticated owner' using errcode = '42501';
  end if;

  select id into v_update_id
  from public.fund_updates
  where project_id = v_project_id and source_local_id = v_source_local_id;

  if v_update_id is null then
    insert into public.fund_updates (
      project_id, source_local_id, title, body, image_url, visibility
    ) values (
      v_project_id, v_source_local_id, v_title, v_body,
      coalesce(p_update ->> 'imageUrl', ''), p_update ->> 'visibility'
    ) returning id into v_update_id;
  else
    update public.fund_updates
    set title = v_title,
        body = v_body,
        image_url = coalesce(p_update ->> 'imageUrl', ''),
        visibility = p_update ->> 'visibility'
    where id = v_update_id;
  end if;

  return v_update_id;
end;
$$;




