CREATE OR REPLACE FUNCTION "public"."story_achievement_get_mine_from_marketnote"("p_source_record_id" "uuid") RETURNS TABLE("achievement_id" "uuid", "source_record_id" "text", "display_mode" "text", "publication_status" "text", "public_title" "text", "public_type_label" "text", "occurred_on" "date", "public_location" "text")
