CREATE OR REPLACE FUNCTION "public"."story_achievement_list_mine"() RETURNS TABLE("achievement_id" "uuid", "display_mode" "text", "publication_status" "text", "public_title" "text", "public_type_label" "text", "occurred_on" "date", "public_location" "text", "published_at" timestamp with time zone, "updated_at" timestamp with time zone)
