CREATE OR REPLACE FUNCTION "public"."story_achievement_metric_options_mine"() RETURNS TABLE("source_service" "text", "metric_key" "text", "suggested_label" "text", "achievement_count" bigint, "selected" boolean, "selected_label" "text", "sort_order" smallint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with my_story as (
    select sp.id as story_profile_id, sp.owner_profile_id
    from public.story_profiles sp
    where sp.owner_user_id = (select auth.uid())
    limit 1
  ),
  explicit_sources as (
    select sa.story_profile_id, sa.source_service, sa.source_record_id
    from public.story_achievements sa
    join my_story ms on ms.story_profile_id = sa.story_profile_id
    where sa.published_at is not null
  ),
  distinct_sources as (
    select ms.story_profile_id, al.source_service, al.source_record_id, al.subject_type_key as metric_key
    from my_story ms
    join public.activity_logs al on al.profile_id = ms.owner_profile_id
    where al.source_service = 'marketnote'
      and al.source_record_id is not null
      and al.subject_type_key is not null
      and al.counts_toward_summary = true
      and al.status = 'confirmed'
      and al.ended_at < (now() at time zone 'Asia/Tokyo')::date
      and not exists (
        select 1
        from explicit_sources es
        where es.story_profile_id = ms.story_profile_id
          and es.source_service = al.source_service
          and es.source_record_id = al.source_record_id
      )
    union
    select sa.story_profile_id, sa.source_service, sa.source_record_id, sa.metric_key
    from public.story_achievements sa
    join my_story ms on ms.story_profile_id = sa.story_profile_id
    where sa.publication_status = 'published'
      and sa.display_mode in ('count_only', 'card_and_count')
  ),
  counts as (
    select ds.story_profile_id, ds.source_service, ds.metric_key, count(*)::bigint as achievement_count
    from (
      select distinct story_profile_id, source_service, source_record_id, metric_key
      from distinct_sources
    ) ds
    group by ds.story_profile_id, ds.source_service, ds.metric_key
  )
  select c.source_service,
         c.metric_key,
         met.name as suggested_label,
         c.achievement_count,
         (settings.metric_key is not null) as selected,
         settings.public_label as selected_label,
         settings.sort_order
  from counts c
  join my_story ms on ms.story_profile_id = c.story_profile_id
  join public.market_event_types met
    on met.profile_id = ms.owner_profile_id
   and met.id::text = c.metric_key
  left join public.story_achievement_metric_settings settings
    on settings.story_profile_id = c.story_profile_id
   and settings.source_service = c.source_service
   and settings.metric_key = c.metric_key
  order by settings.sort_order nulls last, c.achievement_count desc, met.name;
$$;




CREATE OR REPLACE FUNCTION "public"."story_achievement_metric_settings_save_mine"("p_items" "jsonb") RETURNS TABLE("source_service" "text", "metric_key" "text", "public_label" "text", "sort_order" smallint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_caller_user_id uuid := (select auth.uid());
  v_story_profile_id uuid;
  v_owner_profile_id uuid;
  v_items jsonb := coalesce(p_items, '[]'::jsonb);
begin
  if v_caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;
  if jsonb_typeof(v_items) <> 'array' or jsonb_array_length(v_items) > 3 then
    raise exception 'STORY can display at most three achievement metrics.' using errcode = '22023';
  end if;

  select sp.id, sp.owner_profile_id
  into v_story_profile_id, v_owner_profile_id
  from public.story_profiles sp
  where sp.owner_user_id = v_caller_user_id
  limit 1
  for update of sp;

  if v_story_profile_id is null then
    raise exception 'STORY profile is required before selecting metrics.' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_items) as item(
      source_service text,
      metric_key text,
      public_label text,
      sort_order smallint
    )
    where item.source_service is distinct from 'marketnote'
       or item.metric_key is null
       or nullif(btrim(item.public_label), '') is null
       or char_length(btrim(item.public_label)) > 40
       or item.sort_order is null
       or item.sort_order not between 0 and 2
  ) then
    raise exception 'Invalid STORY metric setting.' using errcode = '22023';
  end if;

  if (
    select count(*)
    from jsonb_to_recordset(v_items) as item(
      source_service text,
      metric_key text,
      public_label text,
      sort_order smallint
    )
  ) <> (
    select count(distinct (item.source_service, item.metric_key))
    from jsonb_to_recordset(v_items) as item(
      source_service text,
      metric_key text,
      public_label text,
      sort_order smallint
    )
  ) or (
    select count(*)
    from jsonb_to_recordset(v_items) as item(
      source_service text,
      metric_key text,
      public_label text,
      sort_order smallint
    )
  ) <> (
    select count(distinct item.sort_order)
    from jsonb_to_recordset(v_items) as item(
      source_service text,
      metric_key text,
      public_label text,
      sort_order smallint
    )
  ) then
    raise exception 'STORY metric keys and sort positions must be unique.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_items) as item(
      source_service text,
      metric_key text,
      public_label text,
      sort_order smallint
    )
    where not exists (
      select 1
      from public.market_event_types met
      where met.profile_id = v_owner_profile_id
        and met.user_id = v_caller_user_id
        and met.id::text = item.metric_key
    )
  ) then
    raise exception 'A selected STORY metric does not belong to the authenticated user.' using errcode = '42501';
  end if;

  delete from public.story_achievement_metric_settings settings
  where settings.story_profile_id = v_story_profile_id;

  insert into public.story_achievement_metric_settings (
    story_profile_id,
    source_service,
    metric_key,
    public_label,
    sort_order
  )
  select v_story_profile_id,
         item.source_service,
         item.metric_key,
         btrim(item.public_label),
         item.sort_order
  from jsonb_to_recordset(v_items) as item(
    source_service text,
    metric_key text,
    public_label text,
    sort_order smallint
  );

  return query
  select settings.source_service,
         settings.metric_key,
         settings.public_label,
         settings.sort_order
  from public.story_achievement_metric_settings settings
  where settings.story_profile_id = v_story_profile_id
  order by settings.sort_order;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_achievement_publish_mine"("p_achievement_id" "uuid") RETURNS TABLE("achievement_id" "uuid", "display_mode" "text", "publication_status" "text", "public_title" "text", "public_type_label" "text", "occurred_on" "date", "public_location" "text", "published_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_caller_user_id uuid := (select auth.uid());
begin
  if v_caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  update public.story_achievements sa
  set publication_status = 'published',
      published_at = coalesce(sa.published_at, now()),
      withdrawn_at = null
  from public.story_profiles sp, public.activity_logs al
  where sa.id = p_achievement_id
    and sp.id = sa.story_profile_id
    and sp.owner_user_id = v_caller_user_id
    and al.profile_id = sp.owner_profile_id
    and al.source_service = sa.source_service
    and al.source_service = 'marketnote'
    and al.source_record_id = sa.source_record_id
    and al.status = 'confirmed'
    and al.ended_at < (now() at time zone 'Asia/Tokyo')::date;

  if not found then
    raise exception 'Owned STORY achievement was not found.' using errcode = 'P0002';
  end if;

  return query
  select sa.id,
         sa.display_mode,
         sa.publication_status,
         sa.public_title,
         sa.public_type_label,
         sa.occurred_on,
         sa.public_location,
         sa.published_at,
         sa.updated_at
  from public.story_achievements sa
  where sa.id = p_achievement_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_achievement_stage_from_marketnote"("p_source_record_id" "uuid", "p_display_mode" "text", "p_public_title" "text" DEFAULT NULL::"text", "p_public_type_label" "text" DEFAULT NULL::"text", "p_occurred_on" "date" DEFAULT NULL::"date", "p_public_location" "text" DEFAULT NULL::"text") RETURNS TABLE("achievement_id" "uuid", "source_record_id" "text", "display_mode" "text", "publication_status" "text", "public_title" "text", "public_type_label" "text", "occurred_on" "date", "public_location" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_caller_user_id uuid := (select auth.uid());
  v_story_profile_id uuid;
  v_owner_profile_id uuid;
  v_event_ended_at date;
  v_event_type_id uuid;
  v_event_title text;
  v_event_type_name text;
  v_today_jst date := (now() at time zone 'Asia/Tokyo')::date;
  v_achievement_id uuid;
  v_title text;
  v_type_label text;
  v_occurred_on date;
  v_location text;
begin
  if v_caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;
  if p_source_record_id is null then
    raise exception 'MarketNote source record is required.' using errcode = '22023';
  end if;
  if p_display_mode not in ('count_only', 'card_only', 'card_and_count') then
    raise exception 'Invalid STORY display mode.' using errcode = '22023';
  end if;

  select sp.id, sp.owner_profile_id
  into v_story_profile_id, v_owner_profile_id
  from public.story_profiles sp
  where sp.owner_user_id = v_caller_user_id
  limit 1;

  if v_story_profile_id is null then
    raise exception 'STORY profile is required before adding an achievement.' using errcode = 'P0002';
  end if;

  select al.ended_at, met.id
  into v_event_ended_at, v_event_type_id
  from public.market_events me
  join public.market_event_types met
    on met.id = me.event_type_id
   and met.profile_id = me.profile_id
   and met.user_id = me.user_id
  join public.activity_logs al
    on al.profile_id = me.profile_id
   and al.source_service = 'marketnote'
   and al.source_record_id = me.id::text
   and al.status = 'confirmed'
   and al.ended_at < v_today_jst
  where me.id = p_source_record_id
    and me.user_id = v_caller_user_id
    and me.profile_id = v_owner_profile_id;

  if v_event_ended_at is null then
    raise exception 'Eligible MarketNote achievement source was not found.' using errcode = 'P0002';
  end if;

  if p_display_mode = 'count_only' then
    v_title := null;
    v_type_label := null;
    v_occurred_on := null;
    v_location := null;
  else
    select me.title, met.name
    into v_event_title, v_event_type_name
    from public.market_events me
    join public.market_event_types met
      on met.id = me.event_type_id
     and met.profile_id = me.profile_id
     and met.user_id = me.user_id
    where me.id = p_source_record_id
      and me.user_id = v_caller_user_id
      and me.profile_id = v_owner_profile_id;

    v_title := coalesce(nullif(btrim(p_public_title), ''), nullif(btrim(v_event_title), ''));
    v_type_label := coalesce(nullif(btrim(p_public_type_label), ''), nullif(btrim(v_event_type_name), ''));
    v_occurred_on := coalesce(p_occurred_on, v_event_ended_at);
    v_location := nullif(btrim(p_public_location), '');

    if v_title is null or char_length(v_title) > 120 then
      raise exception 'Public achievement title must be 1 to 120 characters.' using errcode = '22023';
    end if;
    if v_type_label is null or char_length(v_type_label) > 60 then
      raise exception 'Public achievement type must be 1 to 60 characters.' using errcode = '22023';
    end if;
    if v_location is not null and char_length(v_location) > 120 then
      raise exception 'Public achievement location must be at most 120 characters.' using errcode = '22023';
    end if;
  end if;

  insert into public.story_achievements as sa (
    story_profile_id,
    source_service,
    source_record_id,
    metric_key,
    display_mode,
    publication_status,
    public_title,
    public_type_label,
    occurred_on,
    public_location,
    public_note,
    public_photo_storage_path,
    withdrawn_at
  ) values (
    v_story_profile_id,
    'marketnote',
    p_source_record_id::text,
    v_event_type_id::text,
    p_display_mode,
    'draft',
    v_title,
    v_type_label,
    v_occurred_on,
    v_location,
    null,
    null,
    null
  )
  on conflict on constraint story_achievements_owner_source_unique
  do update set
    metric_key = excluded.metric_key,
    display_mode = excluded.display_mode,
    publication_status = 'draft',
    public_title = excluded.public_title,
    public_type_label = excluded.public_type_label,
    occurred_on = excluded.occurred_on,
    public_location = excluded.public_location,
    public_note = case when excluded.display_mode = 'count_only' then null else sa.public_note end,
    public_photo_storage_path = case when excluded.display_mode = 'count_only' then null else sa.public_photo_storage_path end,
    withdrawn_at = null
  returning sa.id into v_achievement_id;

  return query
  select sa.id,
         sa.source_record_id,
         sa.display_mode,
         sa.publication_status,
         sa.public_title,
         sa.public_type_label,
         sa.occurred_on,
         sa.public_location
  from public.story_achievements sa
  where sa.id = v_achievement_id;
end;
$$;




COMMENT ON FUNCTION "public"."story_achievement_stage_from_marketnote"("p_source_record_id" "uuid", "p_display_mode" "text", "p_public_title" "text", "p_public_type_label" "text", "p_occurred_on" "date", "p_public_location" "text") IS 'Validates an owned MarketNote source whose private Activity Log is confirmed and ended before today in JST; derives metric_key in the database; and stages a private STORY snapshot.';



CREATE OR REPLACE FUNCTION "public"."story_achievement_update_draft_mine"("p_achievement_id" "uuid", "p_display_mode" "text", "p_public_title" "text" DEFAULT NULL::"text", "p_public_type_label" "text" DEFAULT NULL::"text", "p_occurred_on" "date" DEFAULT NULL::"date", "p_public_location" "text" DEFAULT NULL::"text", "p_public_note" "text" DEFAULT NULL::"text", "p_public_photo_storage_path" "text" DEFAULT NULL::"text", "p_sort_order" integer DEFAULT 0) RETURNS TABLE("achievement_id" "uuid", "display_mode" "text", "publication_status" "text", "public_title" "text", "public_type_label" "text", "occurred_on" "date", "public_location" "text", "published_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_caller_user_id uuid := (select auth.uid());
  v_photo_path text := nullif(btrim(p_public_photo_storage_path), '');
begin
  if v_caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;
  if p_display_mode not in ('count_only', 'card_only', 'card_and_count') then
    raise exception 'Invalid STORY display mode.' using errcode = '22023';
  end if;
  if p_sort_order < 0 then
    raise exception 'Sort order must be zero or greater.' using errcode = '22023';
  end if;
  if p_display_mode <> 'count_only' then
    if nullif(btrim(p_public_title), '') is null or char_length(btrim(p_public_title)) > 120 then
      raise exception 'Public achievement title must be 1 to 120 characters.' using errcode = '22023';
    end if;
    if nullif(btrim(p_public_type_label), '') is null or char_length(btrim(p_public_type_label)) > 60 then
      raise exception 'Public achievement type must be 1 to 60 characters.' using errcode = '22023';
    end if;
    if p_occurred_on is null then
      raise exception 'Public achievement date is required for a card.' using errcode = '22023';
    end if;
    if nullif(btrim(p_public_location), '') is not null and char_length(btrim(p_public_location)) > 120 then
      raise exception 'Public achievement location must be at most 120 characters.' using errcode = '22023';
    end if;
    if p_public_note is not null and char_length(p_public_note) > 500 then
      raise exception 'Public achievement note must be at most 500 characters.' using errcode = '22023';
    end if;
    if v_photo_path is not null
      and split_part(v_photo_path, '/', 1) <> v_caller_user_id::text then
      raise exception 'Public achievement photo path must belong to the authenticated user.' using errcode = '42501';
    end if;
  end if;

  update public.story_achievements sa
  set display_mode = p_display_mode,
      publication_status = 'draft',
      public_title = case when p_display_mode = 'count_only' then null else nullif(btrim(p_public_title), '') end,
      public_type_label = case when p_display_mode = 'count_only' then null else nullif(btrim(p_public_type_label), '') end,
      occurred_on = case when p_display_mode = 'count_only' then null else p_occurred_on end,
      public_location = case when p_display_mode = 'count_only' then null else nullif(btrim(p_public_location), '') end,
      public_note = case when p_display_mode = 'count_only' then null else nullif(btrim(p_public_note), '') end,
      public_photo_storage_path = case when p_display_mode = 'count_only' then null else v_photo_path end,
      sort_order = p_sort_order,
      withdrawn_at = null
  from public.story_profiles sp
  where sa.id = p_achievement_id
    and sp.id = sa.story_profile_id
    and sp.owner_user_id = v_caller_user_id;

  if not found then
    raise exception 'Owned STORY achievement was not found.' using errcode = 'P0002';
  end if;

  return query
  select sa.id,
         sa.display_mode,
         sa.publication_status,
         sa.public_title,
         sa.public_type_label,
         sa.occurred_on,
         sa.public_location,
         sa.published_at,
         sa.updated_at
  from public.story_achievements sa
  where sa.id = p_achievement_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_achievement_withdraw_from_marketnote"("p_source_record_id" "uuid") RETURNS TABLE("achievement_id" "uuid", "source_record_id" "text", "display_mode" "text", "publication_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_caller_user_id uuid := (select auth.uid());
  v_achievement_id uuid;
begin
  if v_caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  update public.story_achievements sa
  set publication_status = 'withdrawn',
      withdrawn_at = now()
  from public.story_profiles sp
  where sp.id = sa.story_profile_id
    and sp.owner_user_id = v_caller_user_id
    and sa.source_service = 'marketnote'
    and sa.source_record_id = p_source_record_id::text
  returning sa.id into v_achievement_id;

  if v_achievement_id is null then
    raise exception 'Owned STORY achievement was not found.' using errcode = 'P0002';
  end if;

  return query
  select sa.id,
         sa.source_record_id,
         sa.display_mode,
         sa.publication_status
  from public.story_achievements sa
  where sa.id = v_achievement_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_achievement_withdraw_mine"("p_achievement_id" "uuid") RETURNS TABLE("achievement_id" "uuid", "display_mode" "text", "publication_status" "text", "public_title" "text", "public_type_label" "text", "occurred_on" "date", "public_location" "text", "published_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_caller_user_id uuid := (select auth.uid());
begin
  if v_caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  update public.story_achievements sa
  set publication_status = 'withdrawn',
      withdrawn_at = now()
  from public.story_profiles sp
  where sa.id = p_achievement_id
    and sp.id = sa.story_profile_id
    and sp.owner_user_id = v_caller_user_id;

  if not found then
    raise exception 'Owned STORY achievement was not found.' using errcode = 'P0002';
  end if;

  return query
  select sa.id,
         sa.display_mode,
         sa.publication_status,
         sa.public_title,
         sa.public_type_label,
         sa.occurred_on,
         sa.public_location,
         sa.published_at,
         sa.updated_at
  from public.story_achievements sa
  where sa.id = p_achievement_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_collection_get_state"("p_handle" "text") RETURNS TABLE("viewer_has_story" boolean, "is_own_story" boolean, "is_saved" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_user_id uuid := (select auth.uid());
  caller_profile_id uuid;
  target_story_id uuid;
  target_owner_user_id uuid;
  normalized_handle text := lower(trim(regexp_replace(coalesce(p_handle, ''), '^@', '')));
begin
  if caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  select p.id into caller_profile_id
  from public.profiles p
  where p.user_id = caller_user_id
  limit 1;

  select sp.id, sp.owner_user_id into target_story_id, target_owner_user_id
  from public.story_profiles sp
  where lower(sp.handle) = normalized_handle
    and sp.publication_status = 'published'
  limit 1;

  return query select
    caller_profile_id is not null,
    target_owner_user_id = caller_user_id,
    caller_profile_id is not null and target_story_id is not null and exists (
      select 1 from public.story_collections sc
      where sc.owner_user_id = caller_user_id
        and sc.saved_story_profile_id = target_story_id
    );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_collection_list_mine"() RETURNS TABLE("collection_id" "uuid", "saved_at" timestamp with time zone, "is_favorite" boolean, "available" boolean, "handle" "text", "display_name" "text", "role_label" "text", "avatar_storage_path" "text", "theme_key" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_user_id uuid := (select auth.uid());
begin
  if caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  return query
  select
    sc.id,
    sc.created_at,
    sc.is_favorite,
    sp.publication_status = 'published',
    case when sp.publication_status = 'published' then sp.handle else null end,
    case when sp.publication_status = 'published' then sp.display_name else null end,
    case when sp.publication_status = 'published' then sp.role_label else null end,
    case when sp.publication_status = 'published' then sp.avatar_storage_path else null end,
    case when sp.publication_status = 'published' then sp.theme_key else null end
  from public.story_collections sc
  join public.story_profiles sp on sp.id = sc.saved_story_profile_id
  where sc.owner_user_id = caller_user_id
  order by sc.is_favorite desc, sc.favorited_at desc nulls last, sc.created_at desc;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_collection_remove"("p_collection_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_user_id uuid := (select auth.uid());
begin
  if caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;
  delete from public.story_collections
  where id = p_collection_id and owner_user_id = caller_user_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_collection_remove_by_handle"("p_handle" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_user_id uuid := (select auth.uid());
  normalized_handle text := lower(trim(regexp_replace(coalesce(p_handle, ''), '^@', '')));
begin
  if caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;
  delete from public.story_collections sc
  using public.story_profiles sp
  where sc.saved_story_profile_id = sp.id
    and sc.owner_user_id = caller_user_id
    and lower(sp.handle) = normalized_handle;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_collection_save"("p_handle" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_user_id uuid := (select auth.uid());
  caller_profile_id uuid;
  target_story_id uuid;
  target_owner_user_id uuid;
  saved_id uuid;
  normalized_handle text := lower(trim(regexp_replace(coalesce(p_handle, ''), '^@', '')));
begin
  if caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  select p.id into caller_profile_id
  from public.profiles p
  where p.user_id = caller_user_id
  limit 1;
  if caller_profile_id is null then
    raise exception 'A mikke ID profile is required before saving a collection.' using errcode = 'P0002';
  end if;

  select sp.id, sp.owner_user_id into target_story_id, target_owner_user_id
  from public.story_profiles sp
  where lower(sp.handle) = normalized_handle
    and sp.publication_status = 'published'
  limit 1;
  if target_story_id is null then
    raise exception 'Published STORY was not found.' using errcode = 'P0002';
  end if;
  if target_owner_user_id = caller_user_id then
    raise exception 'Your own STORY cannot be saved to your collection.' using errcode = '22023';
  end if;

  insert into public.story_collections (owner_user_id, owner_profile_id, saved_story_profile_id)
  values (caller_user_id, caller_profile_id, target_story_id)
  on conflict (owner_profile_id, saved_story_profile_id) do update
    set owner_user_id = excluded.owner_user_id
  returning id into saved_id;

  return saved_id;
end;
$$;




COMMENT ON FUNCTION "public"."story_collection_save"("p_handle" "text") IS 'Saves a published STORY to the authenticated mikke ID profile private collection. Owning a STORY is not required.';



CREATE OR REPLACE FUNCTION "public"."story_collection_set_favorite"("p_collection_id" "uuid", "p_is_favorite" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_user_id uuid := (select auth.uid());
  updated_favorite boolean;
begin
  if caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  update public.story_collections
  set
    is_favorite = coalesce(p_is_favorite, false),
    favorited_at = case when coalesce(p_is_favorite, false) then now() else null end
  where id = p_collection_id
    and owner_user_id = caller_user_id
  returning is_favorite into updated_favorite;

  if updated_favorite is null then
    raise exception 'Collection item was not found.' using errcode = 'P0002';
  end if;

  return updated_favorite;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_follow_profile_mikke_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.story_profiles
  set handle = new.handle,
      updated_at = now()
  where owner_profile_id = new.id
    and owner_user_id = new.user_id
    and handle is distinct from new.handle;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_media_paths_valid"("owner_user_id" "uuid", "avatar_path" "text", "banner_path" "text", "portfolio" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select
    (avatar_path is null or avatar_path like owner_user_id::text || '/avatar/%')
    and (banner_path is null or banner_path like owner_user_id::text || '/banner/%')
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(portfolio, '[]'::jsonb)) item
      where item->>'source' <> 'upload'
        or item->>'storage_path' is null
        or item->>'storage_path' not like owner_user_id::text || '/portfolio/%'
    );
$$;




CREATE OR REPLACE FUNCTION "public"."story_profile_get_mine"() RETURNS TABLE("handle" "text", "display_name" "text", "role_label" "text", "bio" "text", "area" "text", "avatar_url" "text", "avatar_storage_path" "text", "banner_storage_path" "text", "portfolio_items" "jsonb", "theme_key" "text", "website_label" "text", "website_url" "text", "shop_label" "text", "shop_url" "text", "sns_links" "jsonb", "tags" "text"[], "status_label" "text", "pickup_text" "text", "publication_status" "text", "published_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select sp.handle, sp.display_name, sp.role_label, sp.bio, sp.area,
    sp.avatar_url, sp.avatar_storage_path, sp.banner_storage_path,
    sp.portfolio_items, sp.theme_key,
    sp.website_label, sp.website_url, sp.shop_label, sp.shop_url,
    sp.sns_links, sp.tags, sp.status_label, sp.pickup_text,
    sp.publication_status, sp.published_at, sp.created_at, sp.updated_at
  from public.story_profiles sp
  where sp.owner_user_id = (select auth.uid())
  limit 1;
$$;




CREATE OR REPLACE FUNCTION "public"."story_profile_save_mine"("p_handle" "text", "p_display_name" "text", "p_role_label" "text" DEFAULT ''::"text", "p_bio" "text" DEFAULT ''::"text", "p_area" "text" DEFAULT ''::"text", "p_avatar_url" "text" DEFAULT NULL::"text", "p_avatar_storage_path" "text" DEFAULT NULL::"text", "p_banner_storage_path" "text" DEFAULT NULL::"text", "p_portfolio_items" "jsonb" DEFAULT '[]'::"jsonb", "p_theme_key" "text" DEFAULT 'blue'::"text", "p_website_label" "text" DEFAULT 'Webサイト'::"text", "p_website_url" "text" DEFAULT NULL::"text", "p_shop_label" "text" DEFAULT 'ショップ'::"text", "p_shop_url" "text" DEFAULT NULL::"text", "p_sns_links" "jsonb" DEFAULT '[]'::"jsonb", "p_tags" "text"[] DEFAULT '{}'::"text"[], "p_status_label" "text" DEFAULT ''::"text", "p_pickup_text" "text" DEFAULT ''::"text", "p_publication_status" "text" DEFAULT 'draft'::"text") RETURNS TABLE("handle" "text", "display_name" "text", "role_label" "text", "bio" "text", "area" "text", "avatar_url" "text", "avatar_storage_path" "text", "banner_storage_path" "text", "portfolio_items" "jsonb", "theme_key" "text", "website_label" "text", "website_url" "text", "shop_label" "text", "shop_url" "text", "sns_links" "jsonb", "tags" "text"[], "status_label" "text", "pickup_text" "text", "publication_status" "text", "published_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_user_id uuid := (select auth.uid());
  caller_profile_id uuid;
  current_handle text;
  requested_handle text;
begin
  if caller_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;
  if p_publication_status not in ('draft', 'published') then
    raise exception 'Invalid publication status.' using errcode = '22023';
  end if;
  if p_theme_key not in ('blue', 'orange', 'green', 'yellow', 'pink') then
    raise exception 'Invalid theme.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_portfolio_items, '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(p_portfolio_items, '[]'::jsonb)) > 6 then
    raise exception 'Portfolio must be an array of at most six items.' using errcode = '22023';
  end if;

  select p.id, p.handle into caller_profile_id, current_handle
  from public.profiles p
  where p.user_id = caller_user_id
  order by p.created_at asc
  limit 1;
  if caller_profile_id is null then
    raise exception 'Profile not found for authenticated user.' using errcode = 'P0002';
  end if;

  -- ここだけが変更点。旧: 正規化＋書式検査＋33語の予約語リストを直書き
  requested_handle := public.mikke_normalize_mikke_id(p_handle, current_handle);

  if requested_handle is distinct from current_handle then
    update public.profiles
    set handle = requested_handle,
        updated_at = now()
    where id = caller_profile_id
      and user_id = caller_user_id;
  end if;

  insert into public.story_profiles as sp (
    owner_user_id, owner_profile_id, handle, display_name, role_label, bio, area,
    avatar_url, avatar_storage_path, banner_storage_path, portfolio_items, theme_key,
    website_label, website_url, shop_label, shop_url, sns_links, tags, status_label, pickup_text,
    publication_status, published_at
  ) values (
    caller_user_id, caller_profile_id, requested_handle, trim(p_display_name), trim(p_role_label),
    trim(p_bio), trim(p_area), nullif(trim(p_avatar_url), ''), nullif(trim(p_avatar_storage_path), ''),
    nullif(trim(p_banner_storage_path), ''), coalesce(p_portfolio_items, '[]'::jsonb), p_theme_key,
    coalesce(nullif(trim(p_website_label), ''), 'Webサイト'), nullif(trim(p_website_url), ''),
    coalesce(nullif(trim(p_shop_label), ''), 'ショップ'), nullif(trim(p_shop_url), ''),
    coalesce(p_sns_links, '[]'::jsonb), coalesce(p_tags, '{}'::text[]),
    trim(p_status_label), trim(p_pickup_text), p_publication_status,
    case when p_publication_status = 'published' then now() else null end
  )
  on conflict (owner_profile_id) do update set
    handle = excluded.handle, display_name = excluded.display_name, role_label = excluded.role_label,
    bio = excluded.bio, area = excluded.area, avatar_url = excluded.avatar_url,
    avatar_storage_path = excluded.avatar_storage_path, banner_storage_path = excluded.banner_storage_path,
    portfolio_items = excluded.portfolio_items, theme_key = excluded.theme_key,
    website_label = excluded.website_label, website_url = excluded.website_url,
    shop_label = excluded.shop_label, shop_url = excluded.shop_url, sns_links = excluded.sns_links,
    tags = excluded.tags, status_label = excluded.status_label, pickup_text = excluded.pickup_text,
    publication_status = excluded.publication_status,
    published_at = case when excluded.publication_status = 'published' then coalesce(sp.published_at, now()) else null end,
    updated_at = now()
  where sp.owner_user_id = caller_user_id;

  return query
  select sp.handle, sp.display_name, sp.role_label, sp.bio, sp.area,
    sp.avatar_url, sp.avatar_storage_path, sp.banner_storage_path,
    sp.portfolio_items, sp.theme_key,
    sp.website_label, sp.website_url, sp.shop_label, sp.shop_url,
    sp.sns_links, sp.tags, sp.status_label, sp.pickup_text,
    sp.publication_status, sp.published_at, sp.created_at, sp.updated_at
  from public.story_profiles sp
  where sp.owner_user_id = caller_user_id
  limit 1;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."story_public_achievement_cards"("p_handle" "text") RETURNS TABLE("achievement_id" "uuid", "public_title" "text", "public_type_label" "text", "occurred_on" "date", "public_location" "text", "public_note" "text", "public_photo_storage_path" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select sa.id,
         sa.public_title,
         sa.public_type_label,
         sa.occurred_on,
         sa.public_location,
         sa.public_note,
         sa.public_photo_storage_path
  from public.story_profiles sp
  join public.story_achievements sa on sa.story_profile_id = sp.id
  where lower(sp.handle) = lower(btrim(p_handle))
    and sp.publication_status = 'published'
    and sa.publication_status = 'published'
    and sa.display_mode in ('card_only', 'card_and_count')
  order by sa.sort_order, sa.occurred_on desc, sa.created_at desc;
$$;




CREATE OR REPLACE FUNCTION "public"."story_public_achievement_metrics"("p_handle" "text") RETURNS TABLE("public_label" "text", "achievement_count" bigint, "sort_order" smallint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with published_story as (
    select sp.id as story_profile_id, sp.owner_profile_id
    from public.story_profiles sp
    where lower(sp.handle) = lower(btrim(p_handle))
      and sp.publication_status = 'published'
    limit 1
  ),
  explicit_sources as (
    select sa.story_profile_id, sa.source_service, sa.source_record_id
    from public.story_achievements sa
    join published_story ps on ps.story_profile_id = sa.story_profile_id
    where sa.published_at is not null
  ),
  eligible_sources as (
    select ps.story_profile_id, al.source_service, al.source_record_id, al.subject_type_key as metric_key
    from published_story ps
    join public.activity_logs al on al.profile_id = ps.owner_profile_id
    where al.source_service = 'marketnote'
      and al.source_record_id is not null
      and al.subject_type_key is not null
      and al.counts_toward_summary = true
      and al.status = 'confirmed'
      and al.ended_at < (now() at time zone 'Asia/Tokyo')::date
      and not exists (
        select 1
        from explicit_sources es
        where es.story_profile_id = ps.story_profile_id
          and es.source_service = al.source_service
          and es.source_record_id = al.source_record_id
      )
    union
    select sa.story_profile_id, sa.source_service, sa.source_record_id, sa.metric_key
    from public.story_achievements sa
    join published_story ps on ps.story_profile_id = sa.story_profile_id
    where sa.publication_status = 'published'
      and sa.display_mode in ('count_only', 'card_and_count')
  ),
  distinct_sources as (
    select distinct story_profile_id, source_service, source_record_id, metric_key
    from eligible_sources
  ),
  counts as (
    select ds.story_profile_id, ds.source_service, ds.metric_key, count(*)::bigint as achievement_count
    from distinct_sources ds
    group by ds.story_profile_id, ds.source_service, ds.metric_key
  )
  select settings.public_label,
         coalesce(counts.achievement_count, 0)::bigint,
         settings.sort_order
  from published_story ps
  join public.story_achievement_metric_settings settings
    on settings.story_profile_id = ps.story_profile_id
  left join counts
    on counts.story_profile_id = settings.story_profile_id
   and counts.source_service = settings.source_service
   and counts.metric_key = settings.metric_key
  order by settings.sort_order
  limit 3;
$$;




COMMENT ON FUNCTION "public"."story_public_achievement_metrics"("p_handle" "text") IS 'Returns at most three configured aggregate numbers. Activity Log and manual STORY sources are never added directly; source identity is deduplicated first.';



CREATE OR REPLACE FUNCTION "public"."story_set_canonical_mikke_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  canonical_handle text;
begin
  select p.handle into canonical_handle
  from public.profiles p
  where p.id = new.owner_profile_id
    and p.user_id = new.owner_user_id;

  if canonical_handle is null then
    raise exception 'Canonical mikke ID profile was not found.' using errcode = 'P0002';
  end if;

  new.handle := canonical_handle;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."sync_mikke_media_usages"("p_app_key" "text", "p_entity_type" "text", "p_entity_id" "text", "p_asset_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$ select private.sync_mikke_media_usages(p_app_key, p_entity_type, p_entity_id, p_asset_ids); $$;




CREATE OR REPLACE FUNCTION "public"."team_works_activate_portal_membership"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  uid uuid := (select auth.uid());
  uemail text;
  suffix text := to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS');
begin
  if uid is null then
    return;
  end if;
  select lower(email) into uemail from auth.users where id = uid;
  if uemail is null then
    return;
  end if;

  insert into public.team_works_organization_members
    (organization_id, user_id, source_local_id, display_name, role, status)
  select p.organization_id, uid, 'directory:worker:' || uid::text || ':' || suffix, p.display_name, 'worker', 'active'
  from public.team_works_partners p
  where p.status = 'active'
    and lower(p.email) = uemail
    and not exists (
      select 1 from public.team_works_organization_members m
      where m.organization_id = p.organization_id
        and m.user_id = uid
        and m.role = 'worker'
        and m.status <> 'archived'
    )
  on conflict do nothing;

  insert into public.team_works_organization_members
    (organization_id, user_id, source_local_id, display_name, role, status)
  select c.organization_id, uid, 'directory:client:' || uid::text || ':' || suffix, c.display_name, 'client_user', 'active'
  from public.team_works_clients c
  where c.status = 'active'
    and lower(c.email) = uemail
    and not exists (
      select 1 from public.team_works_organization_members m
      where m.organization_id = c.organization_id
        and m.user_id = uid
        and m.role = 'client_user'
        and m.status <> 'archived'
    )
  on conflict do nothing;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."team_works_approve_client_project"("target_project_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  uid uuid := (select auth.uid());
  uemail text;
  v_org uuid;
  v_client uuid;
  v_member uuid;
begin
  if uid is null then
    raise exception 'not authenticated';
  end if;
  select lower(email) into uemail from auth.users where id = uid;

  select pc.organization_id, pc.client_id
    into v_org, v_client
  from public.team_works_project_clients pc
  join public.team_works_clients c on c.id = pc.client_id
  where pc.project_id = target_project_id
    and pc.status = 'invited'
    and c.status = 'active'
    and lower(c.email) = uemail
  limit 1;

  if v_org is null then
    raise exception 'no pending invitation for this project';
  end if;

  select id into v_member
  from public.team_works_organization_members
  where organization_id = v_org
    and user_id = uid
    and role = 'client_user'
    and status <> 'archived'
  limit 1;

  if v_member is null then
    raise exception 'client membership is not activated';
  end if;

  insert into public.team_works_project_members
    (project_id, organization_id, organization_member_id, project_role)
  values (target_project_id, v_org, v_member, 'client')
  on conflict (project_id, organization_member_id) do update set project_role = 'client';

  update public.team_works_project_clients
  set status = 'active', updated_at = now()
  where project_id = target_project_id and client_id = v_client;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."team_works_find_active_member"("target_organization_id" "uuid", "target_role" "text", "target_email" "text") RETURNS TABLE("member_id" "uuid", "display_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select m.id, m.display_name
  from public.team_works_organization_members m
  join auth.users u on u.id = m.user_id
  where m.organization_id = target_organization_id
    and m.role = target_role
    and m.status = 'active'
    and lower(u.email) = lower(target_email)
    and private.team_works_is_org_staff(target_organization_id)
  limit 1;
$$;




CREATE OR REPLACE FUNCTION "public"."team_works_get_my_client_profile"() RETURNS TABLE("id" "uuid", "organization_id" "uuid", "company_name" "text", "contact_name" "text", "department" "text", "email" "text", "phone" "text", "address" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ select c.id,c.organization_id,c.display_name as company_name,c.contact_name,c.department,c.email,c.phone,c.address from auth.users u join public.team_works_organization_members m on m.user_id=u.id and m.role='client_user' and m.status='active' join public.team_works_clients c on c.organization_id=m.organization_id and lower(c.email)=lower(coalesce(u.email,'')) and c.status<>'archived' where u.id=auth.uid() order by c.updated_at desc limit 1 $$;




CREATE OR REPLACE FUNCTION "public"."team_works_get_my_partner_profile"() RETURNS TABLE("id" "uuid", "organization_id" "uuid", "display_name" "text", "email" "text", "phone" "text", "address" "text", "skills" "text", "bio" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ select p.id,p.organization_id,p.display_name,p.email,p.phone,p.address,p.skills,p.bio from auth.users u join public.team_works_organization_members m on m.user_id=u.id and m.role='worker' and m.status='active' join public.team_works_partners p on p.organization_id=m.organization_id and lower(p.email)=lower(coalesce(u.email,'')) and p.status<>'archived' where u.id=auth.uid() order by p.updated_at desc limit 1 $$;




CREATE OR REPLACE FUNCTION "public"."team_works_list_client_pending_projects"() RETURNS TABLE("project_id" "uuid", "title" "text", "description" "text", "contract_started_on" "date", "contract_ended_on" "date", "organization_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p.id, p.title, p.description, p.contract_started_on, p.contract_ended_on, o.name
  from public.team_works_project_clients pc
  join public.team_works_clients c on c.id = pc.client_id
  join auth.users u on u.id = (select auth.uid())
  join public.team_works_projects p on p.id = pc.project_id
  join public.team_works_organizations o on o.id = p.organization_id
  where pc.status = 'invited'
    and c.status = 'active'
    and lower(c.email) = lower(u.email)
    and p.style = 'operations'
    and p.status = 'active';
$$;




CREATE OR REPLACE FUNCTION "public"."team_works_list_organization_members"("target_organization_id" "uuid") RETURNS TABLE("id" "uuid", "display_name" "text", "role" "text", "status" "text", "email" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select m.id, m.display_name, m.role, m.status, u.email
  from public.team_works_organization_members m
  join auth.users u on u.id = m.user_id
  where m.organization_id = target_organization_id
    and m.status <> 'archived'
    and private.team_works_is_org_staff(target_organization_id)
  order by m.display_name;
$$;




CREATE OR REPLACE FUNCTION "public"."team_works_save_partner_student_handoff"("p_roster_id" "uuid", "p_attendance_status" "text", "p_assessment" "jsonb", "p_handoff_note" "text", "p_complete" boolean DEFAULT false) RETURNS TABLE("current_manual_no" integer, "completed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_roster public.team_works_session_roster%rowtype;
  target_session public.team_works_op_sessions%rowtype;
  worker_member_id uuid;
  completed_now boolean := false;
begin
  if p_attendance_status not in ('scheduled', 'present', 'absent', 'late', 'excused') then
    raise exception 'Unsupported attendance status';
  end if;

  if p_assessment is null or jsonb_typeof(p_assessment) <> 'object' then
    raise exception 'Assessment must be an object';
  end if;

  if length(coalesce(p_handoff_note, '')) > 4000 then
    raise exception 'Handoff note is too long';
  end if;

  select *
    into target_roster
  from public.team_works_session_roster
  where id = p_roster_id
  for update;

  if target_roster.id is null then
    raise exception 'Roster row not found';
  end if;

  select *
    into target_session
  from public.team_works_op_sessions
  where id = target_roster.session_id
    and status <> 'cancelled';

  select pm.organization_member_id
    into worker_member_id
  from public.team_works_project_members pm
  join public.team_works_organization_members om
    on om.id = pm.organization_member_id
  where pm.project_id = target_roster.project_id
    and pm.project_role = 'worker'
    and om.user_id = (select auth.uid())
    and om.status = 'active'
  limit 1;

  if worker_member_id is null or target_session.partner_member_id is distinct from worker_member_id then
    raise exception 'You are not assigned to this session';
  end if;

  completed_now := p_complete and target_roster.partner_completed_at is null;

  update public.team_works_session_roster
  set attendance_status = p_attendance_status,
      partner_assessment = p_assessment,
      handoff_note = nullif(trim(coalesce(p_handoff_note, '')), ''),
      partner_completed_at = case
        when completed_now then now()
        else partner_completed_at
      end,
      updated_at = now()
  where id = p_roster_id;

  if completed_now then
    update public.team_works_participants as participant
    set current_manual_no = participant.current_manual_no + 1,
        updated_at = now()
    where participant.id = target_roster.participant_id;
  end if;

  return query
  select participant.current_manual_no, roster.partner_completed_at
  from public.team_works_participants participant
  join public.team_works_session_roster roster on roster.id = p_roster_id
  where participant.id = target_roster.participant_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."team_works_update_my_client_profile"("p_company_name" "text", "p_contact_name" "text", "p_department" "text", "p_phone" "text", "p_address" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ declare updated_client public.team_works_clients%rowtype; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if nullif(trim(p_company_name),'') is null then raise exception 'Company name is required'; end if; update public.team_works_clients c set display_name=trim(p_company_name),contact_name=nullif(trim(p_contact_name),''),department=nullif(trim(p_department),''),phone=nullif(trim(p_phone),''),address=nullif(trim(p_address),''),updated_at=now() from auth.users u, public.team_works_organization_members m where u.id=auth.uid() and m.user_id=u.id and m.organization_id=c.organization_id and m.role='client_user' and m.status='active' and lower(c.email)=lower(coalesce(u.email,'')) and c.status<>'archived' returning c.* into updated_client; if updated_client.id is null then raise exception 'Client profile not found'; end if; update public.team_works_organization_members set display_name=coalesce(nullif(updated_client.contact_name,''),updated_client.display_name),updated_at=now() where user_id=auth.uid() and organization_id=updated_client.organization_id and role='client_user' and status='active'; return true; end $$;




CREATE OR REPLACE FUNCTION "public"."team_works_update_my_partner_profile"("p_display_name" "text", "p_phone" "text", "p_address" "text", "p_skills" "text", "p_bio" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ declare updated_partner public.team_works_partners%rowtype; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if nullif(trim(p_display_name),'') is null then raise exception 'Display name is required'; end if; update public.team_works_partners p set display_name=trim(p_display_name),phone=nullif(trim(p_phone),''),address=nullif(trim(p_address),''),skills=nullif(trim(p_skills),''),bio=nullif(trim(p_bio),''),updated_at=now() from auth.users u, public.team_works_organization_members m where u.id=auth.uid() and m.user_id=u.id and m.organization_id=p.organization_id and m.role='worker' and m.status='active' and lower(p.email)=lower(coalesce(u.email,'')) and p.status<>'archived' returning p.* into updated_partner; if updated_partner.id is null then raise exception 'Partner profile not found'; end if; update public.team_works_organization_members set display_name=updated_partner.display_name,updated_at=now() where user_id=auth.uid() and organization_id=updated_partner.organization_id and role='worker' and status='active'; return true; end $$;




CREATE OR REPLACE FUNCTION "public"."team_works_update_partner_presence"("p_session_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_session public.team_works_op_sessions%rowtype;
  worker_member_id uuid;
begin
  if p_status not in ('not_started', 'standby', 'in_progress', 'ended') then
    raise exception 'Unsupported partner presence status';
  end if;

  select *
    into target_session
  from public.team_works_op_sessions
  where id = p_session_id
    and status <> 'cancelled';

  if target_session.id is null then
    raise exception 'Session not found';
  end if;

  select pm.organization_member_id
    into worker_member_id
  from public.team_works_project_members pm
  join public.team_works_organization_members om
    on om.id = pm.organization_member_id
  where pm.project_id = target_session.project_id
    and pm.project_role = 'worker'
    and om.user_id = (select auth.uid())
    and om.status = 'active'
  limit 1;

  if worker_member_id is null or target_session.partner_member_id is distinct from worker_member_id then
    raise exception 'You are not assigned to this session';
  end if;

  update public.team_works_op_sessions
  set partner_presence_status = p_status,
      partner_standby_at = case
        when p_status = 'not_started' then null
        when p_status in ('standby', 'in_progress') then coalesce(partner_standby_at, now())
        else partner_standby_at
      end,
      partner_ended_at = case when p_status = 'ended' then now() else null end,
      updated_at = now()
  where id = p_session_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."team_works_update_project_zoom"("p_project_id" "uuid", "p_zoom_url" "text", "p_zoom_meeting_id" "text", "p_zoom_passcode" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_organization_id uuid;
  v_zoom_url text := nullif(btrim(p_zoom_url), '');
  v_zoom_meeting_id text := nullif(btrim(p_zoom_meeting_id), '');
  v_zoom_passcode text := nullif(btrim(p_zoom_passcode), '');
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select p.organization_id
    into v_organization_id
  from public.team_works_projects p
  where p.id = p_project_id
    and p.style = 'operations';

  if v_organization_id is null
     or not private.team_works_is_org_staff(v_organization_id) then
    raise exception 'Not authorized to update project Zoom settings';
  end if;

  update public.team_works_projects
  set zoom_url = v_zoom_url,
      zoom_meeting_id = v_zoom_meeting_id,
      zoom_passcode = v_zoom_passcode,
      updated_at = now()
  where id = p_project_id;

  update public.team_works_op_sessions
  set zoom_url = v_zoom_url,
      zoom_meeting_id = v_zoom_meeting_id,
      zoom_passcode = v_zoom_passcode,
      updated_at = now()
  where project_id = p_project_id
    and session_date >= current_date
    and zoom_uses_project_default;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."team_works_update_session_zoom"("p_session_id" "uuid", "p_use_project_default" boolean, "p_zoom_url" "text" DEFAULT NULL::"text", "p_zoom_meeting_id" "text" DEFAULT NULL::"text", "p_zoom_passcode" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_project_id uuid;
  v_organization_id uuid;
  v_partner_member_id uuid;
  v_session_date date;
  v_worker_member_id uuid;
  v_zoom_url text := nullif(btrim(p_zoom_url), '');
  v_zoom_meeting_id text := nullif(btrim(p_zoom_meeting_id), '');
  v_zoom_passcode text := nullif(btrim(p_zoom_passcode), '');
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select s.project_id, p.organization_id, s.partner_member_id, s.session_date
    into v_project_id, v_organization_id, v_partner_member_id, v_session_date
  from public.team_works_op_sessions s
  join public.team_works_projects p on p.id = s.project_id
  where s.id = p_session_id
    and p.style = 'operations';

  if v_project_id is null then
    raise exception 'Session not found';
  end if;
  if v_session_date < current_date then
    raise exception 'Past session Zoom settings cannot be changed';
  end if;

  v_worker_member_id :=
    private.team_works_project_member_id_for(v_project_id, 'worker');

  if not private.team_works_is_org_staff(v_organization_id)
     and (v_worker_member_id is null or v_partner_member_id <> v_worker_member_id) then
    raise exception 'Not authorized to update this session Zoom setting';
  end if;

  if coalesce(p_use_project_default, false) then
    select p.zoom_url, p.zoom_meeting_id, p.zoom_passcode
      into v_zoom_url, v_zoom_meeting_id, v_zoom_passcode
    from public.team_works_projects p
    where p.id = v_project_id;
  end if;

  update public.team_works_op_sessions
  set zoom_url = v_zoom_url,
      zoom_meeting_id = v_zoom_meeting_id,
      zoom_passcode = v_zoom_passcode,
      zoom_uses_project_default = coalesce(p_use_project_default, false),
      updated_at = now()
  where id = p_session_id;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."trash_mikke_media_asset"("p_asset_id" "uuid") RETURNS "public"."mikke_media_assets"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$ select private.trash_mikke_media_asset(p_asset_id); $$;




CREATE OR REPLACE FUNCTION "public"."update_fund_participation_consent"("p_participation_id" "uuid", "p_owner_consent_status" "text" DEFAULT NULL::"text", "p_supporter_consent_status" "text" DEFAULT NULL::"text", "p_public_name" "text" DEFAULT NULL::"text", "p_display_mode" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_participation public.fund_participations%rowtype;
begin
  if v_actor is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select * into v_participation
  from public.fund_participations
  where id = p_participation_id
  for update;

  if not found then
    raise exception 'participation not found' using errcode = '42501';
  end if;

  if v_participation.owner_user_id = v_actor then
    if p_owner_consent_status is null
      or p_supporter_consent_status is not null
      or p_public_name is not null
      or p_display_mode is not null
      or p_owner_consent_status not in ('pending', 'granted', 'revoked') then
      raise exception 'owner may update only owner consent' using errcode = '42501';
    end if;

    update public.fund_participations
    set owner_consent_status = p_owner_consent_status
    where id = v_participation.id;
  elsif v_participation.supporter_user_id = v_actor then
    if p_owner_consent_status is not null
      or (p_supporter_consent_status is null and p_public_name is null and p_display_mode is null)
      or (p_supporter_consent_status is not null and p_supporter_consent_status not in ('pending', 'granted', 'revoked'))
      or (p_display_mode is not null and p_display_mode not in ('hidden', 'public_name', 'anonymous'))
      or (p_public_name is not null and char_length(p_public_name) > 80) then
      raise exception 'supporter request contains an unavailable field' using errcode = '42501';
    end if;

    update public.fund_participations
    set supporter_consent_status = coalesce(p_supporter_consent_status, supporter_consent_status),
        public_name = coalesce(p_public_name, public_name),
        display_mode = coalesce(p_display_mode, display_mode)
    where id = v_participation.id;
  else
    raise exception 'participation not found' using errcode = '42501';
  end if;

  return v_participation.id;
end;
$$;




CREATE TABLE IF NOT EXISTS "private"."mikkeos_dispatcher_credentials" (
    "credential_key" "text" NOT NULL,
    "secret_sha256" "text" NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "mikkeos_dispatcher_credentials_secret_sha256_check" CHECK (("secret_sha256" ~ '^[0-9a-f]{64}$'::"text"))
);




CREATE TABLE IF NOT EXISTS "public"."activity_logs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "profile_id" "uuid" NOT NULL,
    "activity_type" "text" NOT NULL,
    "category" "text" DEFAULT 'other'::"text" NOT NULL,
    "source_service" "text" DEFAULT 'manual'::"text" NOT NULL,
    "source_record_id" "text",
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "visibility" "text" DEFAULT 'private'::"text" NOT NULL,
    "status" "text" DEFAULT 'completed'::"text" NOT NULL,
    "display_on_story" boolean DEFAULT true NOT NULL,
    "display_in_timeline" boolean DEFAULT true NOT NULL,
    "display_as_achievement" boolean DEFAULT false NOT NULL,
    "counts_toward_summary" boolean DEFAULT true NOT NULL,
    "has_financial_value" boolean DEFAULT false NOT NULL,
    "amount" numeric(12,2),
    "transaction_type" "text" DEFAULT 'none'::"text" NOT NULL,
    "payment_status" "text" DEFAULT 'not_required'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ended_at" "date",
    "subject_type_key" "text",
    CONSTRAINT "activity_logs_amount_required_when_financial" CHECK (((("has_financial_value" = false) AND ("amount" IS NULL) AND ("transaction_type" = 'none'::"text")) OR (("has_financial_value" = true) AND ("amount" IS NOT NULL) AND ("transaction_type" = ANY (ARRAY['revenue'::"text", 'expense'::"text"]))))),
    CONSTRAINT "activity_logs_category_check" CHECK (("category" = ANY (ARRAY['consultation'::"text", 'production'::"text", 'product'::"text", 'event'::"text", 'workshop'::"text", 'review'::"text", 'profile'::"text", 'other'::"text"]))),
    CONSTRAINT "activity_logs_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['unpaid'::"text", 'paid'::"text", 'not_required'::"text"]))),
    CONSTRAINT "activity_logs_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'confirmed'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "activity_logs_transaction_type_check" CHECK (("transaction_type" = ANY (ARRAY['revenue'::"text", 'expense'::"text", 'none'::"text"]))),
    CONSTRAINT "activity_logs_visibility_check" CHECK (("visibility" = ANY (ARRAY['public'::"text", 'private'::"text", 'limited'::"text"])))
);




CREATE TABLE IF NOT EXISTS "public"."community_memberships" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "community_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "role" "text" DEFAULT 'member'::"text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "memo" "text",
    "joined_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "community_memberships_role_check" CHECK (("role" = ANY (ARRAY['owner'::"text", 'moderator'::"text", 'member'::"text"]))),
    CONSTRAINT "community_memberships_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'suspended'::"text", 'left'::"text"])))
);




CREATE TABLE IF NOT EXISTS "public"."market_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "profile_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "event_date" "date" NOT NULL,
    "venue_name" "text",
    "area" "text",
    "genre" "text",
    "status" "text" DEFAULT 'planned'::"text" NOT NULL,
    "visibility" "text" DEFAULT 'private'::"text" NOT NULL,
    "display_on_story" boolean DEFAULT true NOT NULL,
    "public_note" "text",
    "private_note" "text",
