    CONSTRAINT "story_profiles_sns_links_array" CHECK (("jsonb_typeof"("sns_links") = 'array'::"text")),
    CONSTRAINT "story_profiles_theme_key" CHECK (("theme_key" = ANY (ARRAY['blue'::"text", 'orange'::"text", 'green'::"text", 'yellow'::"text", 'pink'::"text"])))
);




