COMMENT ON COLUMN "public"."story_profiles"."owner_profile_id" IS 'Owner profile reference used only for ownership enforcement and upsert conflict handling.';



CREATE OR REPLACE VIEW "private"."mikkeos_hq_dashboard_summary" WITH ("security_barrier"='true') AS
 SELECT "jsonb_build_object"('profiles_total', ( SELECT "count"(*) AS "count"
           FROM "public"."profiles"), 'profiles_new_30d', ( SELECT "count"(*) AS "count"
           FROM "public"."profiles"
          WHERE ("profiles"."created_at" >= ("now"() - '30 days'::interval))), 'story_users', ( SELECT "count"(DISTINCT "story_profiles"."owner_user_id") AS "count"
           FROM "public"."story_profiles"), 'community_active_users', ( SELECT "count"(DISTINCT "community_memberships"."user_id") AS "count"
           FROM "public"."community_memberships"
          WHERE ("community_memberships"."status" = 'active'::"text")), 'marketnote_users', ( SELECT "count"(DISTINCT "market_events"."user_id") AS "count"
           FROM "public"."market_events"), 'active_users_30d', ( SELECT "count"(DISTINCT "activity_logs"."user_id") AS "count"
           FROM "public"."activity_logs"
          WHERE ("activity_logs"."occurred_at" >= ("now"() - '30 days'::interval))), 'inquiries_open', ( SELECT "count"(*) AS "count"
           FROM "public"."mikkeos_hq_inquiries"
          WHERE ("mikkeos_hq_inquiries"."status" <> 'resolved'::"text")), 'inquiries_urgent', ( SELECT "count"(*) AS "count"
           FROM "public"."mikkeos_hq_inquiries"
          WHERE (("mikkeos_hq_inquiries"."status" <> 'resolved'::"text") AND ("mikkeos_hq_inquiries"."priority" = 'urgent'::"text"))), 'announcement_drafts', ( SELECT "count"(*) AS "count"
           FROM "public"."mikkeos_hq_announcements"
          WHERE ("mikkeos_hq_announcements"."status" = ANY (ARRAY['draft'::"text", 'scheduled'::"text"]))), 'updates_drafts', ( SELECT "count"(*) AS "count"
           FROM "public"."mikkeos_hq_updates"
          WHERE ("mikkeos_hq_updates"."status" = 'draft'::"text"))) AS "summary"
  WHERE (EXISTS ( SELECT 1
           FROM "public"."mikkeos_hq_staff_members" "staff"
          WHERE (("staff"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND "staff"."is_active")));




CREATE OR REPLACE VIEW "private"."mikkeos_hq_dashboard_timeseries" WITH ("security_barrier"='true') AS
 WITH "days" AS (
         SELECT ("generate_series"((CURRENT_DATE - '29 days'::interval), (CURRENT_DATE)::timestamp without time zone, '1 day'::interval))::"date" AS "day"
        ), "profile_counts" AS (
         SELECT ("profiles"."created_at")::"date" AS "day",
            "count"(*) AS "new_profiles"
           FROM "public"."profiles"
          WHERE ("profiles"."created_at" >= (CURRENT_DATE - '29 days'::interval))
          GROUP BY (("profiles"."created_at")::"date")
        ), "activity_counts" AS (
         SELECT ("activity_logs"."occurred_at")::"date" AS "day",
            "count"(DISTINCT "activity_logs"."user_id") AS "active_users",
            "count"(*) AS "activity_records"
           FROM "public"."activity_logs"
          WHERE ("activity_logs"."occurred_at" >= (CURRENT_DATE - '29 days'::interval))
          GROUP BY (("activity_logs"."occurred_at")::"date")
        )
 SELECT "days"."day",
    COALESCE("profile_counts"."new_profiles", (0)::bigint) AS "new_profiles",
    COALESCE("activity_counts"."active_users", (0)::bigint) AS "active_users",
    COALESCE("activity_counts"."activity_records", (0)::bigint) AS "activity_records"
   FROM (("days"
     LEFT JOIN "profile_counts" USING ("day"))
     LEFT JOIN "activity_counts" USING ("day"))
  WHERE (EXISTS ( SELECT 1
           FROM "public"."mikkeos_hq_staff_members" "staff"
          WHERE (("staff"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND "staff"."is_active")))
  ORDER BY "days"."day";




