CREATE OR REPLACE VIEW "private"."mikkeos_hq_email_audience_summary" WITH ("security_barrier"='true') AS
 SELECT "jsonb_build_object"('all_accounts', ( SELECT "count"(*) AS "count"
           FROM "public"."profiles"), 'newsletter_subscribers', ( SELECT "count"(*) AS "count"
           FROM "public"."mikkeos_email_preferences"
          WHERE "mikkeos_email_preferences"."newsletter_enabled"), 'product_update_subscribers', ( SELECT "count"(*) AS "count"
           FROM "public"."mikkeos_email_preferences"
          WHERE "mikkeos_email_preferences"."product_updates_enabled"), 'campaign_drafts', ( SELECT "count"(*) AS "count"
           FROM "public"."mikkeos_email_campaigns"
          WHERE ("mikkeos_email_campaigns"."status" = 'draft'::"text"))) AS "summary"
  WHERE (EXISTS ( SELECT 1
           FROM "public"."mikkeos_hq_staff_members" "staff"
          WHERE (("staff"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND "staff"."is_active" AND ("staff"."role" = ANY (ARRAY['owner'::"text", 'admin'::"text", 'editor'::"text", 'analyst'::"text"])))));




