CREATE TABLE IF NOT EXISTS "public"."academy_kit_orders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "headquarters_id" "uuid" NOT NULL,
    "course_id" "uuid",
    "instructor_id" "uuid" NOT NULL,
    "user_id" "uuid",
    "application_id" "uuid",
    "items" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "title" "text" NOT NULL,
    "amount" numeric(12,0) DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'received'::"text" NOT NULL,
    "payment_url" "text",
    "payment_status" "text" DEFAULT 'unpaid'::"text" NOT NULL,
    "ordered_at" "date" DEFAULT CURRENT_DATE NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "shipping_address" "text",
    "desired_date" "date",
    "diploma_name_en" "text",
    "contact_email" "text",
    "instructor_note" "text",
    CONSTRAINT "academy_kit_orders_amount_check" CHECK (("amount" >= (0)::numeric)),
    CONSTRAINT "academy_kit_orders_payment_check" CHECK (("payment_status" = ANY (ARRAY['unpaid'::"text", 'paid'::"text", 'not_required'::"text"]))),
    CONSTRAINT "academy_kit_orders_status_check" CHECK (("status" = ANY (ARRAY['received'::"text", 'awaiting_payment'::"text", 'paid'::"text", 'preparing'::"text", 'shipped'::"text", 'closed'::"text", 'cancelled'::"text"])))
);




COMMENT ON COLUMN "public"."academy_kit_orders"."application_id" IS 'このキット注文がどの申込（受講者）向けかを示す。null許容。';



COMMENT ON COLUMN "public"."academy_kit_orders"."shipping_address" IS '送り先（受講者へ／自分（講師）へ／その他自由入力）。';



COMMENT ON COLUMN "public"."academy_kit_orders"."desired_date" IS '講師が確定した受講日。';



COMMENT ON COLUMN "public"."academy_kit_orders"."diploma_name_en" IS 'ディプロマに入れる氏名（英語表記）。';



COMMENT ON COLUMN "public"."academy_kit_orders"."contact_email" IS '受講者の連絡先メール。academy_kit_ordersにはapplicant_name・applicant_phoneに相当する列は
   意図的に追加していない（本部への非開示を構造的に保証するため）。';



COMMENT ON COLUMN "public"."academy_kit_orders"."instructor_note" IS '講師から本部へのメッセージ（任意）。';



