CREATE TABLE IF NOT EXISTS "public"."community_reports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "community_id" "uuid" NOT NULL,
    "reporter_user_id" "uuid" NOT NULL,
    "target_type" "text" NOT NULL,
    "target_id" "uuid",
    "reason" "text" NOT NULL,
    "details" "text",
    "content_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "handled_by_user_id" "uuid",
    "resolution_note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    CONSTRAINT "community_reports_reason_check" CHECK (("reason" = ANY (ARRAY['harassment'::"text", 'personal_information'::"text", 'spam'::"text", 'impersonation'::"text", 'inappropriate'::"text", 'rights'::"text", 'danger'::"text", 'rule_violation'::"text", 'other'::"text"]))),
    CONSTRAINT "community_reports_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'reviewing'::"text", 'resolved'::"text", 'dismissed'::"text"]))),
    CONSTRAINT "community_reports_target_type_check" CHECK (("target_type" = ANY (ARRAY['post'::"text", 'comment'::"text", 'chat'::"text", 'profile'::"text", 'member'::"text", 'other'::"text"])))
);




