    CONSTRAINT "community_rooms_conversation_mode_check" CHECK (("conversation_mode" = ANY (ARRAY['thread'::"text", 'chat'::"text"]))),
    CONSTRAINT "community_rooms_kind_check" CHECK (("kind" = ANY (ARRAY['announcement'::"text", 'normal'::"text", 'question'::"text", 'event'::"text"]))),
    CONSTRAINT "community_rooms_theme_color_check" CHECK (("theme_color" = ANY (ARRAY['blue'::"text", 'orange'::"text", 'yellow'::"text", 'pink'::"text", 'green'::"text"])))
);




COMMENT ON COLUMN "public"."community_rooms"."conversation_mode" IS 'Presentation and interaction mode. Access and writing permissions remain separate.';



CREATE TABLE IF NOT EXISTS "public"."community_safety_settings" (
    "community_id" "uuid" NOT NULL,
    "approval_mode" "text" DEFAULT 'manual'::"text" NOT NULL,
    "require_legal_name" boolean DEFAULT true NOT NULL,
    "require_phone" boolean DEFAULT true NOT NULL,
    "require_join_reason" boolean DEFAULT false NOT NULL,
    "terms_version" integer DEFAULT 1 NOT NULL,
    "terms_text" "text" DEFAULT '参加者同士を尊重し、誹謗中傷、迷惑行為、無断転載、個人情報の公開を行わないでください。運営者はルール違反に対して投稿の非表示、利用停止、退会等の対応を行うことがあります。'::"text" NOT NULL,
    "rules_version" integer DEFAULT 1 NOT NULL,
    "rules_text" "text" DEFAULT '相手を尊重して交流してください。個人情報、差別的表現、嫌がらせ、宣伝やスパム、権利を侵害する内容は禁止します。'::"text" NOT NULL,
    "privacy_version" integer DEFAULT 1 NOT NULL,
    "privacy_text" "text" DEFAULT '入力された氏名、メールアドレス、電話番号は、参加確認、本人確認、重要な連絡、トラブル対応のために利用し、Communityの一般参加者には公開しません。'::"text" NOT NULL,
    "new_member_limit_enabled" boolean DEFAULT false NOT NULL,
    "new_member_limit_hours" integer DEFAULT 24 NOT NULL,
    "new_member_max_actions" integer DEFAULT 5 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "community_safety_settings_approval_mode_check" CHECK (("approval_mode" = ANY (ARRAY['auto'::"text", 'manual'::"text"]))),
    CONSTRAINT "community_safety_settings_new_member_limit_hours_check" CHECK ((("new_member_limit_hours" >= 1) AND ("new_member_limit_hours" <= 168))),
    CONSTRAINT "community_safety_settings_new_member_max_actions_check" CHECK ((("new_member_max_actions" >= 1) AND ("new_member_max_actions" <= 100))),
    CONSTRAINT "community_safety_settings_privacy_version_check" CHECK (("privacy_version" > 0)),
    CONSTRAINT "community_safety_settings_rules_version_check" CHECK (("rules_version" > 0)),
    CONSTRAINT "community_safety_settings_terms_version_check" CHECK (("terms_version" > 0))
);




