CREATE TABLE IF NOT EXISTS "public"."fund_challenge_records" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "source_local_id" "text" NOT NULL,
    "title" "text" NOT NULL,
    "summary" "text" NOT NULL,
    "outcome" "text" DEFAULT ''::"text" NOT NULL,
    "image_url" "text" DEFAULT ''::"text" NOT NULL,
    "visibility" "text" DEFAULT 'private'::"text" NOT NULL,
    "story_enabled" boolean DEFAULT false NOT NULL,
    "completed_at" "date" NOT NULL,
    "published_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "fund_challenge_records_image_url_check" CHECK ((("image_url" = ''::"text") OR (("char_length"("image_url") <= 2048) AND ("image_url" ~ '^https?://'::"text")))),
    CONSTRAINT "fund_challenge_records_outcome_length_check" CHECK (("char_length"("outcome") <= 5000)),
    CONSTRAINT "fund_challenge_records_source_local_id_length_check" CHECK ((("char_length"("source_local_id") >= 1) AND ("char_length"("source_local_id") <= 160))),
    CONSTRAINT "fund_challenge_records_story_visibility_check" CHECK (((NOT "story_enabled") OR ("visibility" = 'public'::"text"))),
    CONSTRAINT "fund_challenge_records_summary_length_check" CHECK ((("char_length"("summary") >= 1) AND ("char_length"("summary") <= 5000))),
    CONSTRAINT "fund_challenge_records_title_length_check" CHECK ((("char_length"("title") >= 1) AND ("char_length"("title") <= 160))),
    CONSTRAINT "fund_challenge_records_visibility_check" CHECK (("visibility" = ANY (ARRAY['private'::"text", 'public'::"text"])))
);

ALTER TABLE ONLY "public"."fund_challenge_records" FORCE ROW LEVEL SECURITY;




COMMENT ON TABLE "public"."fund_challenge_records" IS 'Owner-private Fund completion record source of truth.';



CREATE TABLE IF NOT EXISTS "public"."fund_participations" (
