CREATE TABLE IF NOT EXISTS "public"."fund_plans" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "source_local_id" "text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text" DEFAULT ''::"text" NOT NULL,
    "image_url" "text" DEFAULT ''::"text" NOT NULL,
    "plan_type" "text" DEFAULT 'support'::"text" NOT NULL,
    "price" numeric(12,2),
    "quantity_limit" integer,
    "per_person_limit" integer,
    "delivery_date" "date",
    "external_payment_url" "text" DEFAULT ''::"text" NOT NULL,
    "external_application_url" "text" DEFAULT ''::"text" NOT NULL,
    "required_information_note" "text" DEFAULT ''::"text" NOT NULL,
    "requires_shipping" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "fund_plans_application_url_check" CHECK ((("external_application_url" = ''::"text") OR (("char_length"("external_application_url") <= 2048) AND ("external_application_url" ~ '^https?://'::"text")))),
    CONSTRAINT "fund_plans_description_length_check" CHECK (("char_length"("description") <= 5000)),
    CONSTRAINT "fund_plans_image_url_check" CHECK ((("image_url" = ''::"text") OR (("char_length"("image_url") <= 2048) AND ("image_url" ~ '^https?://'::"text")))),
    CONSTRAINT "fund_plans_payment_url_check" CHECK ((("external_payment_url" = ''::"text") OR (("char_length"("external_payment_url") <= 2048) AND ("external_payment_url" ~ '^https?://'::"text")))),
    CONSTRAINT "fund_plans_per_person_limit_check" CHECK ((("per_person_limit" IS NULL) OR ("per_person_limit" > 0))),
    CONSTRAINT "fund_plans_plan_type_check" CHECK (("plan_type" = ANY (ARRAY['preorder'::"text", 'early_application'::"text", 'reservation'::"text", 'sponsorship'::"text", 'support'::"text", 'interest'::"text", 'non_financial'::"text"]))),
    CONSTRAINT "fund_plans_price_check" CHECK ((("price" IS NULL) OR ("price" >= (0)::numeric))),
    CONSTRAINT "fund_plans_quantity_limit_check" CHECK ((("quantity_limit" IS NULL) OR ("quantity_limit" > 0))),
    CONSTRAINT "fund_plans_required_information_length_check" CHECK (("char_length"("required_information_note") <= 2000)),
    CONSTRAINT "fund_plans_sort_order_check" CHECK (("sort_order" >= 0)),
    CONSTRAINT "fund_plans_source_local_id_length_check" CHECK ((("char_length"("source_local_id") >= 1) AND ("char_length"("source_local_id") <= 160))),
    CONSTRAINT "fund_plans_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'sold_out'::"text", 'closed'::"text", 'hidden'::"text"]))),
    CONSTRAINT "fund_plans_title_length_check" CHECK ((("char_length"("title") >= 1) AND ("char_length"("title") <= 160)))
);

ALTER TABLE ONLY "public"."fund_plans" FORCE ROW LEVEL SECURITY;




COMMENT ON TABLE "public"."fund_plans" IS 'Owner-private Fund plans, including fields that are not always public.';



CREATE TABLE IF NOT EXISTS "public"."fund_projects" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_user_id" "uuid" NOT NULL,
    "owner_profile_id" "uuid" NOT NULL,
    "source_local_id" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "title" "text" NOT NULL,
    "visibility" "text" DEFAULT 'private'::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "short_description" "text" DEFAULT ''::"text" NOT NULL,
    "description" "text" DEFAULT ''::"text" NOT NULL,
    "project_type" "text" DEFAULT 'other'::"text" NOT NULL,
    "campaign_type" "text" DEFAULT 'support'::"text" NOT NULL,
    "stage" "text" DEFAULT 'concept'::"text" NOT NULL,
    "cover_image_url" "text" DEFAULT ''::"text" NOT NULL,
    "goal_type" "text" DEFAULT 'supporters'::"text" NOT NULL,
    "goal_value" numeric(12,2) DEFAULT 1 NOT NULL,
    "display_amount" boolean DEFAULT false NOT NULL,
    "start_at" "date",
    "end_at" "date",
    "external_payment_url" "text" DEFAULT ''::"text" NOT NULL,
    "external_application_url" "text" DEFAULT ''::"text" NOT NULL,
    "why_now" "text" DEFAULT ''::"text" NOT NULL,
    "audience" "text" DEFAULT ''::"text" NOT NULL,
    "use_of_support" "text" DEFAULT ''::"text" NOT NULL,
    "schedule" "text" DEFAULT ''::"text" NOT NULL,
    "risk_notes" "text" DEFAULT ''::"text" NOT NULL,
    "cancellation_policy" "text" DEFAULT ''::"text" NOT NULL,
    "contact_note" "text" DEFAULT ''::"text" NOT NULL,
    "published_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    CONSTRAINT "fund_projects_application_url_check" CHECK ((("external_application_url" = ''::"text") OR (("char_length"("external_application_url") <= 2048) AND ("external_application_url" ~ '^https?://'::"text")))),
    CONSTRAINT "fund_projects_campaign_type_check" CHECK (("campaign_type" = ANY (ARRAY['preorder'::"text", 'early_application'::"text", 'reservation'::"text", 'sponsorship'::"text", 'support'::"text", 'interest'::"text"]))),
    CONSTRAINT "fund_projects_cover_url_check" CHECK ((("cover_image_url" = ''::"text") OR (("char_length"("cover_image_url") <= 2048) AND ("cover_image_url" ~ '^https?://'::"text")))),
    CONSTRAINT "fund_projects_date_order_check" CHECK ((("start_at" IS NULL) OR ("end_at" IS NULL) OR ("end_at" >= "start_at"))),
    CONSTRAINT "fund_projects_description_length_check" CHECK (("char_length"("description") <= 10000)),
    CONSTRAINT "fund_projects_display_amount_check" CHECK (((NOT "display_amount") OR ("goal_type" = 'amount'::"text"))),
    CONSTRAINT "fund_projects_goal_type_check" CHECK (("goal_type" = ANY (ARRAY['amount'::"text", 'supporters'::"text", 'reservations'::"text", 'participants'::"text", 'vendors'::"text", 'sponsors'::"text"]))),
    CONSTRAINT "fund_projects_goal_value_check" CHECK (("goal_value" > (0)::numeric)),
    CONSTRAINT "fund_projects_payment_url_check" CHECK ((("external_payment_url" = ''::"text") OR (("char_length"("external_payment_url") <= 2048) AND ("external_payment_url" ~ '^https?://'::"text")))),
    CONSTRAINT "fund_projects_project_type_check" CHECK (("project_type" = ANY (ARRAY['product'::"text", 'course'::"text", 'event'::"text", 'session'::"text", 'community'::"text", 'place'::"text", 'activity'::"text", 'other'::"text"]))),
    CONSTRAINT "fund_projects_public_text_lengths_check" CHECK ((("char_length"("why_now") <= 10000) AND ("char_length"("audience") <= 10000) AND ("char_length"("use_of_support") <= 10000) AND ("char_length"("schedule") <= 10000) AND ("char_length"("risk_notes") <= 10000) AND ("char_length"("cancellation_policy") <= 10000) AND ("char_length"("contact_note") <= 2000))),
    CONSTRAINT "fund_projects_short_description_length_check" CHECK (("char_length"("short_description") <= 500)),
    CONSTRAINT "fund_projects_slug_format_check" CHECK (("slug" ~ '^[a-z0-9][a-z0-9-]{0,79}$'::"text")),
    CONSTRAINT "fund_projects_source_local_id_length_check" CHECK ((("char_length"("source_local_id") >= 1) AND ("char_length"("source_local_id") <= 160))),
    CONSTRAINT "fund_projects_stage_check" CHECK (("stage" = ANY (ARRAY['concept'::"text", 'campaign'::"text", 'realization'::"text"]))),
    CONSTRAINT "fund_projects_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'interest_open'::"text", 'ready'::"text", 'open'::"text", 'goal_reached'::"text", 'closed'::"text", 'in_progress'::"text", 'delivering'::"text", 'completed'::"text", 'postponed'::"text", 'cancelled'::"text", 'archived'::"text"]))),
    CONSTRAINT "fund_projects_title_length_check" CHECK ((("char_length"("title") >= 1) AND ("char_length"("title") <= 160))),
    CONSTRAINT "fund_projects_visibility_check" CHECK (("visibility" = ANY (ARRAY['private'::"text", 'unlisted'::"text", 'public'::"text"])))
);

ALTER TABLE ONLY "public"."fund_projects" FORCE ROW LEVEL SECURITY;




COMMENT ON TABLE "public"."fund_projects" IS 'Fund owner boundary for F4. Public Fund content is not exposed from this table.';



