CREATE TABLE IF NOT EXISTS "public"."fund_supports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "source_local_id" "text" NOT NULL,
    "plan_source_id" "text",
    "supporter_name" "text" NOT NULL,
    "supporter_email" "text",
    "comment" "text" DEFAULT ''::"text" NOT NULL,
    "support_type" "text" DEFAULT 'support'::"text" NOT NULL,
    "amount" numeric(12,2),
    "quantity" integer DEFAULT 1 NOT NULL,
    "payment_status" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "fulfillment_status" "text" DEFAULT 'not_required'::"text" NOT NULL,
    "record_status" "text" DEFAULT 'valid'::"text" NOT NULL,
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "supported_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "public_name" "text" DEFAULT ''::"text" NOT NULL,
    "is_anonymous" boolean DEFAULT false NOT NULL,
    CONSTRAINT "fund_supports_amount_check" CHECK ((("amount" IS NULL) OR ("amount" >= (0)::numeric))),
    CONSTRAINT "fund_supports_cancellation_state_check" CHECK ((((("payment_status" = 'cancelled'::"text") OR ("fulfillment_status" = 'cancelled'::"text")) AND ("cancelled_at" IS NOT NULL)) OR (("payment_status" <> 'cancelled'::"text") AND ("fulfillment_status" <> 'cancelled'::"text") AND ("cancelled_at" IS NULL)))),
    CONSTRAINT "fund_supports_comment_length_check" CHECK (("char_length"("comment") <= 5000)),
    CONSTRAINT "fund_supports_completion_state_check" CHECK (((("fulfillment_status" = 'completed'::"text") AND ("completed_at" IS NOT NULL)) OR (("fulfillment_status" <> 'completed'::"text") AND ("completed_at" IS NULL)))),
    CONSTRAINT "fund_supports_fulfillment_status_check" CHECK (("fulfillment_status" = ANY (ARRAY['not_required'::"text", 'waiting'::"text", 'preparing'::"text", 'scheduled'::"text", 'shipped'::"text", 'participated'::"text", 'in_service'::"text", 'completed'::"text", 'on_hold'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "fund_supports_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['unknown'::"text", 'pending'::"text", 'confirmed'::"text", 'refunded'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "fund_supports_plan_source_id_length_check" CHECK ((("plan_source_id" IS NULL) OR (("char_length"("plan_source_id") >= 1) AND ("char_length"("plan_source_id") <= 160)))),
    CONSTRAINT "fund_supports_public_name_length_check" CHECK (("char_length"("public_name") <= 80)),
    CONSTRAINT "fund_supports_quantity_check" CHECK (("quantity" > 0)),
    CONSTRAINT "fund_supports_record_status_check" CHECK (("record_status" = ANY (ARRAY['valid'::"text", 'test'::"text", 'duplicate'::"text", 'invalid'::"text"]))),
    CONSTRAINT "fund_supports_source_length_check" CHECK ((("char_length"("source") >= 1) AND ("char_length"("source") <= 160))),
    CONSTRAINT "fund_supports_source_local_id_length_check" CHECK ((("char_length"("source_local_id") >= 1) AND ("char_length"("source_local_id") <= 160))),
    CONSTRAINT "fund_supports_support_type_check" CHECK (("support_type" = ANY (ARRAY['preorder'::"text", 'early_application'::"text", 'reservation'::"text", 'sponsorship'::"text", 'support'::"text", 'interest'::"text", 'non_financial'::"text"]))),
    CONSTRAINT "fund_supports_supporter_email_length_check" CHECK ((("supporter_email" IS NULL) OR ("char_length"("supporter_email") <= 320))),
    CONSTRAINT "fund_supports_supporter_name_length_check" CHECK ((("char_length"("supporter_name") >= 1) AND ("char_length"("supporter_name") <= 160)))
);

ALTER TABLE ONLY "public"."fund_supports" FORCE ROW LEVEL SECURITY;




COMMENT ON TABLE "public"."fund_supports" IS 'Owner-private Fund support records. Never expose supporter identity or amount to anon.';



CREATE TABLE IF NOT EXISTS "public"."fund_updates" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "source_local_id" "text" NOT NULL,
    "title" "text" NOT NULL,
    "body" "text" NOT NULL,
    "image_url" "text" DEFAULT ''::"text" NOT NULL,
    "visibility" "text" DEFAULT 'draft'::"text" NOT NULL,
    "published_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "fund_updates_body_length_check" CHECK ((("char_length"("body") >= 1) AND ("char_length"("body") <= 10000))),
    CONSTRAINT "fund_updates_image_url_check" CHECK ((("image_url" = ''::"text") OR (("char_length"("image_url") <= 2048) AND ("image_url" ~ '^https?://'::"text")))),
    CONSTRAINT "fund_updates_publication_state_check" CHECK (((("visibility" = 'draft'::"text") AND ("published_at" IS NULL)) OR (("visibility" = 'public'::"text") AND ("published_at" IS NOT NULL)))),
    CONSTRAINT "fund_updates_source_local_id_length_check" CHECK ((("char_length"("source_local_id") >= 1) AND ("char_length"("source_local_id") <= 160))),
    CONSTRAINT "fund_updates_title_length_check" CHECK ((("char_length"("title") >= 1) AND ("char_length"("title") <= 160))),
    CONSTRAINT "fund_updates_visibility_check" CHECK (("visibility" = ANY (ARRAY['draft'::"text", 'public'::"text"])))
);

ALTER TABLE ONLY "public"."fund_updates" FORCE ROW LEVEL SECURITY;




COMMENT ON TABLE "public"."fund_updates" IS 'Owner-private Fund activity reports. Public clients must read fund_public_updates instead.';



