    CONSTRAINT "market_financial_records_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['unpaid'::"text", 'paid'::"text", 'not_required'::"text"]))),
    CONSTRAINT "market_financial_records_record_type_check" CHECK (("record_type" = ANY (ARRAY['revenue'::"text", 'expense'::"text"])))
);




