CREATE TABLE IF NOT EXISTS "public"."market_schedule_projections" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "source_service" "text" NOT NULL,
    "source_calendar_key" "text" DEFAULT 'default'::"text" NOT NULL,
    "source_record_id" "text" NOT NULL,
    "occurrence_key" "text" DEFAULT 'single'::"text" NOT NULL,
    "title" "text" NOT NULL,
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "starts_on" "date",
    "ends_on_exclusive" "date",
    "all_day" boolean DEFAULT false NOT NULL,
    "time_zone" "text" DEFAULT 'Asia/Tokyo'::"text" NOT NULL,
    "location" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "source_href" "text",
    "source_updated_at" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "market_schedule_projections_calendar_key_check" CHECK ((("length"("btrim"("source_calendar_key")) >= 1) AND ("length"("btrim"("source_calendar_key")) <= 200))),
    CONSTRAINT "market_schedule_projections_google_manual_identity_check" CHECK ((("source_service" <> 'google_manual'::"text") OR (("source_calendar_key" = 'ics_manual'::"text") AND ("source_record_id" ~ '^uid_[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "market_schedule_projections_location_check" CHECK ((("location" IS NULL) OR (("length"("btrim"("location")) >= 1) AND ("length"("btrim"("location")) <= 200)))),
    CONSTRAINT "market_schedule_projections_occurrence_key_check" CHECK ((("length"("btrim"("occurrence_key")) >= 1) AND ("length"("btrim"("occurrence_key")) <= 200))),
    CONSTRAINT "market_schedule_projections_service_check" CHECK (("source_service" ~ '^[a-z][a-z0-9_]{0,39}$'::"text")),
    CONSTRAINT "market_schedule_projections_source_href_check" CHECK ((("source_href" IS NULL) OR ((("length"("source_href") >= 1) AND ("length"("source_href") <= 500)) AND ("source_href" ~~ '/%'::"text") AND ("source_href" !~~ '//%'::"text") AND ("source_href" !~ '[[:cntrl:]\\]'::"text")))),
    CONSTRAINT "market_schedule_projections_source_record_check" CHECK ((("length"("btrim"("source_record_id")) >= 1) AND ("length"("btrim"("source_record_id")) <= 500))),
    CONSTRAINT "market_schedule_projections_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'cancelled'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "market_schedule_projections_temporal_shape_check" CHECK ((("all_day" AND ("starts_on" IS NOT NULL) AND ("ends_on_exclusive" IS NOT NULL) AND ("ends_on_exclusive" > "starts_on") AND ("starts_at" IS NULL) AND ("ends_at" IS NULL)) OR ((NOT "all_day") AND ("starts_at" IS NOT NULL) AND (("ends_at" IS NULL) OR ("ends_at" >= "starts_at")) AND ("starts_on" IS NULL) AND ("ends_on_exclusive" IS NULL)))),
    CONSTRAINT "market_schedule_projections_time_zone_check" CHECK ((("length"("btrim"("time_zone")) >= 1) AND ("length"("btrim"("time_zone")) <= 100))),
    CONSTRAINT "market_schedule_projections_title_check" CHECK ((("length"("btrim"("title")) >= 1) AND ("length"("btrim"("title")) <= 200)))
);




COMMENT ON TABLE "public"."market_schedule_projections" IS 'Private read-only schedule cache/projection. It never creates Activity Log or STORY rows and is not a MarketNote event.';



COMMENT ON COLUMN "public"."market_schedule_projections"."source_record_id" IS 'Stable ID from the source. For recurring schedules, pair with occurrence_key; never use a series ID alone.';



COMMENT ON COLUMN "public"."market_schedule_projections"."ends_on_exclusive" IS 'Exclusive end date for all-day schedules, matching iCalendar DTEND semantics.';



COMMENT ON COLUMN "public"."market_schedule_projections"."source_href" IS 'Optional internal relative route back to the source app. External URLs are rejected.';



CREATE TABLE IF NOT EXISTS "public"."market_schedule_source_preferences" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "source_service" "text" NOT NULL,
    "source_calendar_key" "text" DEFAULT 'default'::"text" NOT NULL,
    "source_label" "text",
    "is_visible" boolean DEFAULT true NOT NULL,
    "notifications_enabled" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "display_color" "text" DEFAULT '#9CCDB9'::"text" NOT NULL,
    CONSTRAINT "market_schedule_source_preferences_calendar_key_check" CHECK ((("length"("btrim"("source_calendar_key")) >= 1) AND ("length"("btrim"("source_calendar_key")) <= 200))),
    CONSTRAINT "market_schedule_source_preferences_display_color_check" CHECK (("display_color" ~ '^#[0-9A-Fa-f]{6}$'::"text")),
    CONSTRAINT "market_schedule_source_preferences_google_manual_identity_check" CHECK ((("source_service" <> 'google_manual'::"text") OR (("source_calendar_key" = 'ics_manual'::"text") AND ("source_label" IS NOT NULL) AND ("source_label" = 'Googleカレンダー（手動取り込み）'::"text")))),
    CONSTRAINT "market_schedule_source_preferences_label_check" CHECK ((("source_label" IS NULL) OR (("length"("btrim"("source_label")) >= 1) AND ("length"("btrim"("source_label")) <= 80)))),
    CONSTRAINT "market_schedule_source_preferences_service_check" CHECK (("source_service" ~ '^[a-z][a-z0-9_]{0,39}$'::"text"))
);




COMMENT ON TABLE "public"."market_schedule_source_preferences" IS 'Private per-user visibility and notification preferences for MarketNote schedule sources. Visibility never deletes or stops the source.';



COMMENT ON COLUMN "public"."market_schedule_source_preferences"."source_calendar_key" IS 'Stable non-sensitive source/calendar key. Do not store an email address or OAuth token here.';



COMMENT ON COLUMN "public"."market_schedule_source_preferences"."notifications_enabled" IS 'Independent from calendar visibility. Notification delivery is a later phase.';



COMMENT ON COLUMN "public"."market_schedule_source_preferences"."display_color" IS 'Owner-selected display color used only in MarketNote and Manager calendar projections. It never writes back to the source.';



CREATE TABLE IF NOT EXISTS "public"."mikke_app_entitlements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "app_key" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
