    "ends_at" timestamp with time zone,
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "mikke_app_entitlements_app_key_check" CHECK (("app_key" ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::"text")),
    CONSTRAINT "mikke_app_entitlements_period_check" CHECK ((("ends_at" IS NULL) OR ("starts_at" IS NULL) OR ("ends_at" > "starts_at"))),
    CONSTRAINT "mikke_app_entitlements_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'paused'::"text", 'expired'::"text", 'revoked'::"text"])))
);




COMMENT ON TABLE "public"."mikke_app_entitlements" IS 'Account-level app entrances. Users can read only their own rows; grants are managed by trusted server or admin tooling.';



CREATE TABLE IF NOT EXISTS "public"."mikke_app_menu_preferences" (
    "user_id" "uuid" NOT NULL,
    "app_key" "text" NOT NULL,
    "sort_order" integer NOT NULL,
    "is_hidden" boolean DEFAULT false NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "mikke_app_menu_preferences_app_key_check" CHECK (("app_key" = ANY (ARRAY['marketnote'::"text", 'story'::"text", 'community'::"text", 'ninteikoza'::"text"]))),
    CONSTRAINT "mikke_app_menu_preferences_sort_order_check" CHECK ((("sort_order" >= 0) AND ("sort_order" <= 31)))
);




COMMENT ON TABLE "public"."mikke_app_menu_preferences" IS 'Account-scoped display overrides for the shared app menu. These rows never grant ownership or change app data, entitlements, notifications, or sync.';



COMMENT ON COLUMN "public"."mikke_app_menu_preferences"."app_key" IS 'Stable entitlement key. Add a new key only through a reviewed migration that updates both this check constraint and the replace RPC allowlist.';



COMMENT ON COLUMN "public"."mikke_app_menu_preferences"."sort_order" IS 'Unique account-local position. Apps without an override keep the registry default order after explicitly ordered apps.';



COMMENT ON COLUMN "public"."mikke_app_menu_preferences"."is_hidden" IS 'Display-only flag. Hidden apps remain owned and directly reachable when otherwise authorized.';



