CREATE TABLE IF NOT EXISTS "public"."mikkeos_ai_tech_adoptions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "experiment_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "area" "text" NOT NULL,
    "summary" "text" NOT NULL,
    "method_markdown" "text" DEFAULT ''::"text" NOT NULL,
    "codex_target_kind" "text" DEFAULT 'pending'::"text" NOT NULL,
    "codex_target_path" "text",
    "integration_status" "text" DEFAULT 'pending'::"text" NOT NULL,
