CREATE TABLE IF NOT EXISTS "public"."story_achievements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "story_profile_id" "uuid" NOT NULL,
    "source_service" "text" DEFAULT 'marketnote'::"text" NOT NULL,
    "source_record_id" "text" NOT NULL,
    "metric_key" "text" NOT NULL,
    "display_mode" "text" NOT NULL,
    "publication_status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "public_title" "text",
    "public_type_label" "text",
    "occurred_on" "date",
    "public_location" "text",
    "public_note" "text",
    "public_photo_storage_path" "text",
    "sort_order" integer DEFAULT 0 NOT NULL,
    "published_at" timestamp with time zone,
    "withdrawn_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "story_achievements_display_mode_check" CHECK (("display_mode" = ANY (ARRAY['count_only'::"text", 'card_only'::"text", 'card_and_count'::"text"]))),
    CONSTRAINT "story_achievements_display_payload_check" CHECK (((("display_mode" = 'count_only'::"text") AND ("public_title" IS NULL) AND ("public_type_label" IS NULL) AND ("occurred_on" IS NULL) AND ("public_location" IS NULL) AND ("public_note" IS NULL) AND ("public_photo_storage_path" IS NULL)) OR (("display_mode" = ANY (ARRAY['card_only'::"text", 'card_and_count'::"text"])) AND ("public_title" IS NOT NULL) AND ("public_type_label" IS NOT NULL) AND ("occurred_on" IS NOT NULL)))),
    CONSTRAINT "story_achievements_metric_key_not_blank" CHECK (("length"("btrim"("metric_key")) > 0)),
    CONSTRAINT "story_achievements_public_location_length" CHECK ((("public_location" IS NULL) OR (("length"("btrim"("public_location")) >= 1) AND ("length"("btrim"("public_location")) <= 120)))),
    CONSTRAINT "story_achievements_public_note_length" CHECK ((("public_note" IS NULL) OR ("char_length"("public_note") <= 500))),
    CONSTRAINT "story_achievements_public_photo_path_length" CHECK ((("public_photo_storage_path" IS NULL) OR ("char_length"("public_photo_storage_path") <= 500))),
    CONSTRAINT "story_achievements_public_title_length" CHECK ((("public_title" IS NULL) OR (("length"("btrim"("public_title")) >= 1) AND ("length"("btrim"("public_title")) <= 120)))),
    CONSTRAINT "story_achievements_public_type_label_length" CHECK ((("public_type_label" IS NULL) OR (("length"("btrim"("public_type_label")) >= 1) AND ("length"("btrim"("public_type_label")) <= 60)))),
    CONSTRAINT "story_achievements_publication_status_check" CHECK (("publication_status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "story_achievements_sort_order_check" CHECK (("sort_order" >= 0)),
    CONSTRAINT "story_achievements_source_record_id_not_blank" CHECK (("length"("btrim"("source_record_id")) > 0)),
    CONSTRAINT "story_achievements_source_service_check" CHECK (("source_service" = 'marketnote'::"text"))
);




COMMENT ON TABLE "public"."story_achievements" IS 'STORY-owned snapshots explicitly staged from MarketNote and published by the owner. Never stores MarketNote memo, photo, finance, or payment data.';



COMMENT ON COLUMN "public"."story_achievements"."metric_key" IS 'Non-public aggregate key derived by database validation from market_events.event_type_id; never trusted from client input.';



COMMENT ON COLUMN "public"."story_achievements"."display_mode" IS 'count_only: aggregate only and no card payload; card_only: public card and explicit no-count override; card_and_count: one aggregate count plus public card.';



COMMENT ON COLUMN "public"."story_achievements"."publication_status" IS 'draft: private staged snapshot; published: eligible for configured public output; withdrawn: retained for dedupe/republication but not public.';



CREATE TABLE IF NOT EXISTS "public"."story_collections" (
