    "deliverable_note" "text",
    "checklist" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "outputs" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    CONSTRAINT "team_works_project_tasks_checklist_check" CHECK (("jsonb_typeof"("checklist") = 'array'::"text")),
    CONSTRAINT "team_works_project_tasks_outputs_check" CHECK (("jsonb_typeof"("outputs") = 'array'::"text")),
    CONSTRAINT "team_works_project_tasks_owner_role_check" CHECK (("owner_role" = ANY (ARRAY['admin'::"text", 'worker'::"text", 'client'::"text"]))),
    CONSTRAINT "team_works_project_tasks_standard_days_check" CHECK ((("standard_days" IS NULL) OR ("standard_days" > 0))),
    CONSTRAINT "team_works_project_tasks_status_check" CHECK (("status" = ANY (ARRAY['not_started'::"text", 'in_progress'::"text", 'review_pending'::"text", 'revising'::"text", 'completed'::"text", 'on_hold'::"text", 'cancelled'::"text", 'archived'::"text"]))),
    CONSTRAINT "team_works_project_tasks_submission_type_check" CHECK (("submission_type" = ANY (ARRAY['none'::"text", 'form'::"text", 'file'::"text", 'url'::"text"])))
);

ALTER TABLE ONLY "public"."team_works_project_tasks" FORCE ROW LEVEL SECURITY;




COMMENT ON COLUMN "public"."team_works_project_tasks"."due_on" IS 'このタスクの期日。ワーカーの成果物提出・クライアントの提出物・Zoom会議日などをカレンダー表示するために使用。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."position" IS '作業の並び順。期日が未設定の段階でも表示順を保持するために使用。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."owner_role" IS 'この工程の主担当ロール。admin=本部, worker=担当メンバー, client=クライアント。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."submission_type" IS 'この工程で提出を要するものの種類。none=提出物なし。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."submit_due_on" IS '担当者が提出する期日。due_on(工程の完了期日)とは別に持つ。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."assignee_label" IS '名簿登録・ポータルログインがまだの仮担当者名。実メンバーが決まればassignee_member_idを設定し、この列は使わなくてよい。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."standard_days" IS 'この工程に要する標準日数。納期からの逆算配置(自動でsubmit_due_on/due_onを埋める)に使用。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."description" IS 'この工程で何を作るか(成果物の概要)。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."purpose" IS 'この工程をなぜやるか(目的)。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."method" IS '使うツール・方法(例:Canva、スライド制作ツール)。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."deliverable_note" IS '提出物の具体的な形。submission_typeが種別、この列がその中身の説明。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."checklist" IS '作業順(文字列の配列)。担当者が上から順に進める手順。';



COMMENT ON COLUMN "public"."team_works_project_tasks"."outputs" IS '完成物に含まれるもの(文字列の配列)。';



CREATE TABLE IF NOT EXISTS "public"."team_works_projects" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "source_local_id" "text",
    "client_member_id" "uuid",
    "title" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "client_visible" boolean DEFAULT false NOT NULL,
    "payouts_enabled" boolean DEFAULT false NOT NULL,
    "invoices_enabled" boolean DEFAULT false NOT NULL,
    "archived_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "style" "text" DEFAULT 'delivery'::"text" NOT NULL,
    "contract_started_on" "date",
    "contract_ended_on" "date",
    "description" "text",
    "client_partner_contact_visible" boolean DEFAULT true NOT NULL,
    "zoom_url" "text",
    "zoom_meeting_id" "text",
    "zoom_passcode" "text",
    "delivery_due_on" "date",
    "operation_settings" "jsonb",
    "feature_settings" "jsonb",
    CONSTRAINT "team_works_projects_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'on_hold'::"text", 'completed'::"text", 'cancelled'::"text", 'archived'::"text"]))),
    CONSTRAINT "team_works_projects_style_check" CHECK (("style" = ANY (ARRAY['operations'::"text", 'delivery'::"text"])))
);

ALTER TABLE ONLY "public"."team_works_projects" FORCE ROW LEVEL SECURITY;




COMMENT ON COLUMN "public"."team_works_projects"."client_partner_contact_visible" IS 'false の場合、クライアントポータルの連絡先/メッセージから担当パートナーを除外し、本部窓口のみを表示する。';



COMMENT ON COLUMN "public"."team_works_projects"."zoom_url" IS 'Default Zoom join URL for future sessions in this project.';



COMMENT ON COLUMN "public"."team_works_projects"."delivery_due_on" IS '納品型(style=''delivery'')プロジェクトの納期。工程の期日を逆算配置する起点として使用。';



COMMENT ON COLUMN "public"."team_works_projects"."operation_settings" IS 'このプロジェクトだけの休日設定の上書き。null=組織設定(operation_settings)に従う。キーは組織側と同じTeamWorksOperationSettings。';



COMMENT ON COLUMN "public"."team_works_projects"."feature_settings" IS '機能ON/OFF設定。null=全機能ON(現行仕様)。運営型/納品型でキーが異なる。lib/team-works-feature-settings.tsを参照。RLSとは独立(表示設定のみ)。';



CREATE TABLE IF NOT EXISTS "public"."team_works_schedule_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "partner_member_id" "uuid",
    "weekday" smallint NOT NULL,
    "start_time" time without time zone NOT NULL,
    "duration_min" integer NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "work_description" "text",
    CONSTRAINT "team_works_schedule_rules_duration_min_check" CHECK (("duration_min" > 0)),
    CONSTRAINT "team_works_schedule_rules_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'paused'::"text", 'archived'::"text"]))),
    CONSTRAINT "team_works_schedule_rules_weekday_check" CHECK ((("weekday" >= 0) AND ("weekday" <= 6)))
);

ALTER TABLE ONLY "public"."team_works_schedule_rules" FORCE ROW LEVEL SECURITY;




COMMENT ON COLUMN "public"."team_works_schedule_rules"."work_description" IS '週次パターンの作業内容(任意)。コマ自動生成時にteam_works_op_sessions.work_descriptionへコピーされる。';



CREATE TABLE IF NOT EXISTS "public"."team_works_session_roster" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_id" "uuid" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "participant_id" "uuid" NOT NULL,
    "order_index" integer NOT NULL,
    "attendance_status" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "partner_assessment" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "handoff_note" "text",
    "partner_completed_at" timestamp with time zone,
    CONSTRAINT "team_works_session_roster_attendance_status_check" CHECK (("attendance_status" = ANY (ARRAY['scheduled'::"text", 'present'::"text", 'absent'::"text", 'late'::"text", 'excused'::"text"]))),
    CONSTRAINT "team_works_session_roster_order_index_check" CHECK (("order_index" >= 1))
);

ALTER TABLE ONLY "public"."team_works_session_roster" FORCE ROW LEVEL SECURITY;




