CREATE POLICY "Active HQ staff can read mikkeos_ai_tech_adoptions" ON "public"."mikkeos_ai_tech_adoptions" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."mikkeos_hq_staff_members" "staff"
  WHERE (("staff"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND "staff"."is_active"))));



CREATE POLICY "Active HQ staff can read mikkeos_ai_tech_candidates" ON "public"."mikkeos_ai_tech_candidates" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."mikkeos_hq_staff_members" "staff"
  WHERE (("staff"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND "staff"."is_active"))));



CREATE POLICY "Active HQ staff can read mikkeos_ai_tech_experiments" ON "public"."mikkeos_ai_tech_experiments" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."mikkeos_hq_staff_members" "staff"
